  local clone = logic.start_clone(block, cast)
  if not clone then return end
  scatter(block.puff, clone.from.x, clone.from.y, clone.z - cast.height / 2, cast.height)
  show_clone(cast, clone, "")
end

local function strike(step, strikes)
  if #strikes == 0 then return end
  if combat.is_joined(step.world) or not combat.can_hit(step.world) then return end
  local pid = combat.id(step.player)
  local damage = logic.damage(block, combat.damage_stat(step.player))
  for _, s in ipairs(strikes) do
    if not s.clone.sounded then   -- one hit sound per clone, however many creatures it struck
      s.clone.sounded = true
      combat.play_sound(block.hit_sounds[cast.clip] or block.hit_sound, s.e.x, s.e.y, s.e.z, block.hit_volume)
    end
    combat.hit(pid, s.e.addr, damage, 0)
    combat.flash(s.e.addr)                    -- the blink at once, as the game shows a hit
    kyubu.info(("skills_unleashed: assassin: clone %d struck creature %d for %.0f"):format(s.clone.index, s.e.id, damage))
  end
end

-- One step of cast `c` (ability time `now`): the smoke, the clones' move, the puffs at their ends, the specks on their way and their
-- shadows (of `shadow_owner`, nil: the local player). Returns the strikes: each enemy of `owner` (the caster's address) that a clone
-- touched for the first time.
local function step_cast(step, c, now, owner, prefix, shadow_owner)
  local t = c.target
  for _ = 1, logic.smoke_due(block, c, step.dt, now) do scatter(block.smoke, t.x, t.y, t.z, c.height) end
  local strikes, evs = logic.step(block, c, step.dt, combat.enemies(step.world, owner))
  for _, e in ipairs(evs) do
    if e.kind == logic.EVENT_FADE then
      scatter(block.puff_end, e.pos.x, e.pos.y, e.pos.z - c.height / 2, c.height, logic.clone_velocity(block, e.clone))
    end
  end
  for _, clone in ipairs(c.clones) do
    if clone.gone then
      hide_clone(prefix, clone.index)
    else
      if not clone.faded then
        local pos = logic.clone_at(block, clone, clone.age)
        scatter(block.wisp, pos.x, pos.y, pos.z - c.height / 2, c.height, logic.clone_velocity(block, clone))
      end
      show_clone(c, clone, prefix, shadow_owner)
    end
  end
  return strikes
end

-- Another player's strikes: the clones set off on the run's time (from the server's at the event), as the server's do; a clone that
-- touches an enemy plays its sound once, and nothing is applied.
local function watch_step(step)
  for id, w in pairs(watched) do
    local owner = combat.find(step.world, id)
    if w.world ~= step.world or not owner then
      drop_watched(id)
    else
      local c = w.cast
      w.ms = w.ms + step.dt
      for _ = 1, logic.clones_due(block, c.started, w.ms) do
        local clone = logic.start_clone(block, c)
        scatter(block.puff, clone.from.x, clone.from.y, clone.z - c.height / 2, c.height)
      end
      for _, s in ipairs(step_cast(step, c, w.ms, owner, "w" .. id .. "_", owner)) do
        if not s.clone.sounded then
          s.clone.sounded = true
          combat.play_sound(block.hit_sounds[c.clip] or block.hit_sound, s.e.x, s.e.y, s.e.z, block.hit_volume)
        end
      end
      if logic.over(block, c) then
        kyubu.info(("skills_unleashed: assassin: the last watched clone of player %d has faded"):format(id))
        drop_watched(id)
      end
    end
  end
end

local function tick(step)
  shadow.set_player(step.player)
  if ability_ms then ash_step(step.player) end
  keep_steering(step)
  watch_step(step)
  if not cast then return end
  if cast_world ~= step.world then
    drop_cast()
    return
  end
  strike(step, step_cast(step, cast, ability_ms or block.duration_ms, step.player, ""))
  if logic.over(block, cast) then
    kyubu.info("skills_unleashed: assassin: the last clone has faded")
    drop_cast()
  end
end

-- The server's `strike` (skills_unleashed:world), in the World step after it came: another player's is drawn from here on.
local function on_strike_event(step, ev)
  if type(ev.owner) ~= "number" or type(ev.ms) ~= "number" or type(ev.target) ~= "table" or type(ev.from) ~= "table" then return end
  if step.player and combat.id(step.player) == ev.owner then
    kyubu.info(("skills_unleashed: assassin: the server took the strike of run %s"):format(tostring(ev.run)))
    return
  end
  local owner = combat.find(step.world, ev.owner)
  if not owner then return end
  drop_watched(ev.owner)
  local fx_, fy = units.facing(combat.yaw_deg(owner))
  local clip = block.clone_clips[ev.clip] and ev.clip or block.clone_clip_default
  local c = logic.new_cast(block, { x = ev.target.x, y = ev.target.y, z = ev.target.z }, { x = ev.from.x, y = ev.from.y },
    { x = fx_, y = fy }, { half_width = combat.half_width(owner), height = combat.height(owner) }, clip)
  logic.start_smoke(c)
  rules_on()
  watched[ev.owner] = { cast = c, world = step.world, ms = ev.ms }
  kyubu.info(("skills_unleashed: assassin: watched strike of player %d at %.1f, %.1f, %.1f (clones: %s, %d ms into its run)")
    :format(ev.owner, c.target.x, c.target.y, c.target.z, clip, ev.ms))
end

-- ---- the skill tooltip -----------------------------------------------------------------------------------------------------

local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "rogue", specialization = SPEC, name = TEXT_NAME,
    values = function(r) return logic.tooltip_values(block, r) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: assassin: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the definition --------------------------------------------------------------------------------------------------------

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  if shadow.install() then
    for key, id in pairs(block.clone_clips) do
      clip_modes[key] = kyubu.ability.number(id)
      if not clip_modes[key] then warn_once("pose:" .. key, id .. " has no number: those clones wear the player's own pose") end
    end
    shadow.set_color(unpack(block.clone_color))
  end
  ash_model = kyubu.read_file(block.ash_model)
  if not ash_model then warn_once("ash", "the aura's model was not found: no aura") end
  combat.every(tick)
  events.on(logic.EVENT_STRIKE, function(ev) combat.defer(function(step) on_strike_event(step, ev) end) end)
end

local function forget()
  ash_off()
  drop_cast()
  for id in pairs(watched) do drop_watched(id) end
  shadow.clear()
  ability_ms = nil
  if steer_ms > 0 then rules_off() end
  steer_ms = 0
end

local function on_start(ctx)
  setup()
  ability_ms = 0
  channel.new_run(logic.EVENT_STRIKE)
  combat.defer(function(step)
    local x, y, z = combat.position(step.player)
    combat.play_sound(block.cast_sound, x, y, z, block.cast_volume)
  end)
end

local function on_end()
  ability_ms = nil
  ash_off()
end

local function on_step(ctx)
  ability_ms = ctx.elapsed_ms
  combat.defer(function(step) combat.stand_still(step.player) end)   -- no move until the clip is over
  for _, name in ipairs(ctx:marker()) do
    if name == logic.MARKER_SMOKE then
      combat.defer(fix_target)
    elseif name == logic.MARKER_CLONE then
      combat.defer(start_clone)
    end
  end
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "assassin.png",
    anim = t.clip,
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "rogue", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
    on_end = on_end,
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  -- The clones' strikes: abilities on no bar whose clips the loader's pose provider draws while lib/shadow swaps their numbers in.
  local names = {}
  for key in pairs(t.clone_clips) do names[#names + 1] = key end
  table.sort(names)                                 -- one order, so the numbers do not change from run to run
  for _, key in ipairs(names) do
    local id = t.clone_clips[key]
    local cok, cerr = kyubu.ability.define(id, { duration_ms = t.clone_clip_ms, cooldown_ms = 0, anim = id })
    if not cok then kyubu.warn("skills_unleashed: assassin: the clone clip " .. id .. ": " .. tostring(cerr)) end
  end
  kyubu.on("lifecycle.game_ready", setup_tooltip)
  kyubu.on("lifecycle.game_ready", setup)          -- the hooks go in at the menu, never at a cast
  kyubu.on("lifecycle.world_exit", forget)
end

M._tick, M._fix_target, M._start_clone, M._on_step = tick, fix_target, start_clone, on_step
M._state = function() return cast, ability_ms, ash, watched end   -- for the unit test

return M
end

-- @module skills_unleashed.abilities.berserker (abilities/berserker.lua)
package.preload["skills_unleashed.abilities.berserker"] = function(...)
-- skills_unleashed.abilities.berserker: Warrior, Berserker, slot 4: Uppercut.
-- The numbers are in lib/tuning.lua (`berserker`), the geometry in logic/berserker.lua; this module is the callbacks.
--
--   on_start   the shared hook and the game's functions are set up once
--   on_step    0 to windup_ms: the player is held in place; windup + hop delay: the hop; the clip's `hit` marker: the strike
--   every step while a creature is in the air (combat.every): the landing's effects when it comes down
--
-- This VM never hits or moves a monster: on Cube.exe the client side owns only the local player (creature_state_set).
-- The strike, the flight and the landing are server/berserker.lua's. In single-player the strike is sent at the `hit` marker as
-- `skills_unleashed:berserker { rank }` over the loopback channel to the mod's own server VM;
-- a joined client sends nothing (Server.exe strikes at strike_ms, and combat.can_hit logs why this side does not).
-- Either way this VM hops, and draws what the strike shows (show_strike, the same as a watched one).
--
--   watch      a joined client's view of another player's Uppercut: at the
--              clip's `hit` marker the rings on the enemies this client's own logic.strike_targets picks, and the landing's burst,
--              wave and sound where the thrown creature comes down (its flight is the server's). Presentation only: no hit, no
--              push, no stun, no hop.
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local fx = require("skills_unleashed.lib.fx")
local tooltip = require("skills_unleashed.lib.tooltip")
local units = require("skills_unleashed.lib.units")
local logic = require("skills_unleashed.logic.berserker")

local M = {}

local ID = "skills_unleashed:berserker"
local CHANNEL = "skills_unleashed:berserker"   -- the loopback to the server VM (server/berserker.lua, M.CHANNEL)
local SPEC = "berserker"
local TEXT_NAME = "AbilityUppercut"   -- the dictionary suffix: assets/text/dict_en.xml has description: and details: of it

local block = nil                 -- the checked tuning block
local flying = {}                 -- creature id -> mark (see logic.fly) of a creature thrown up and not yet landed, every one a
                                  -- watch mark: the server VM moves it, this VM only shows the landing
local ready = false
local show_strike                 -- the strike a joined client shows (defined with the watched strike, below)

local function world_pos(x, y, z)
  return { units.to_units(x), units.to_units(y), units.to_units(z) }
end

local function particle_def(base, color)
  local d = {}
  for k, v in pairs(base) do d[k] = v end
  d.color = color
  return d
end

local function facing_of(player)
  local x, y = units.facing(combat.yaw_deg(player))
  return { x = x, y = y }
end

-- ---- the strike ------------------------------------------------------------------------------------------------------

-- What shows on a creature the strike connects with: a ring at chest height tilted along the blow (forward and up).
local function connect_effects(entry, facing)
  local t = block
  local where = world_pos(entry.c.x, entry.c.y, entry.c.z + t.hit_height)
  fx.shockwave(logic.strike_wave_def(t, where, facing))
end

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  kyubu.warn("skills_unleashed: berserker: " .. text)
end

-- Single-player: the local player's strike goes to the server VM, which hits, throws and lands (server/berserker.lua).
local function send_strike(rank)
  local ch = kyubu.channel
  if not ch then
    warn_once("no channel", "this Kyubu has no channels: the strike hits nobody")
    return false
  end
  local ok, err = ch.send(CHANNEL, ch.SERVER, { rank = rank })
  if not ok then warn_once("send:" .. tostring(err), "the strike was not sent: " .. tostring(err)) end
  return ok == true
end

local function strike(step, rank)
  local player = step.player
  if combat.can_hit(step.world) then send_strike(rank) end
  show_strike(step, player, rank)
end

-- ---- the landing -----------------------------------------------------------------------------------------------------

-- What shows where a thrown creature comes down: the sound, the burst and the wave. The landing's own effects, and all of a watched one.
local function landing_effects(rank, x, y, z)
  local t = block
  combat.play_sound(t.impact_sound, x, y, z)
  fx.burst(particle_def(t.impact_particles, t.color), world_pos(x, y, z))
  fx.shockwave(logic.shockwave_def(t, rank, world_pos(x, y, z - t.impact_wave_drop)))
end

-- Runs in every World step of the local player (combat.every): follows each creature in the air, shows its landing.
local function tick(step)
  if next(flying) == nil then return end
  local found = {}
  combat.each_creature(step.world, function(c)
    local id = combat.id(c)
    if flying[id] then found[id] = c end
  end)
  for id, mark in pairs(flying) do
    if mark.world ~= step.world then
      flying[id] = nil
    else
      local c = found[id]
      local seen = { present = c ~= nil, alive = c ~= nil and combat.is_alive(c), grounded = c ~= nil and combat.landed(c) }
      if c then mark.x, mark.y, mark.z = combat.position(c) end
      local verdict = logic.fly(block, mark, step.dt, seen)
      if verdict ~= "fly" and verdict ~= "gone" then
        flying[id] = nil
        landing_effects(mark.rank, mark.x, mark.y, mark.z)
      elseif verdict == "gone" then
        flying[id] = nil
      end
    end
  end
end

-- ---- another player's strike, watched ---------------------------------------------------------------------------------

-- What a strike by `player` shows on this client, which never hits: the targets the strike would pick here, the rings and the
-- sound on them, and a watched mark on the primary so that its landing shows. The server has already hit them, or will.
function show_strike(step, player, rank)
  local t = block
  local px, py, pz = combat.position(player)
  local facing = facing_of(player)
  local primary, others = logic.strike_targets(t, { x = px, y = py, z = pz }, facing, combat.enemies(step.world, player))
  if not primary then return end
  combat.play_sound(t.strike_sound, primary.c.x, primary.c.y, primary.c.z)
  connect_effects(primary, facing)
  for _, entry in ipairs(others) do connect_effects(entry, facing) end
  if flying[primary.c.id] then return end   -- already marked (another strike in flight on it)
  local _, _, vz = logic.primary_launch(t, primary, facing)
  flying[primary.c.id] = {
    id = primary.c.id, world = step.world, rank = rank, watch = true,
    vz = vz, age_ms = 0, left_ground = false,
    x = primary.c.x, y = primary.c.y, z = primary.c.z,
  }
end

-- The strike of the player with the id `owner_id` as this client sees it.
local function watch_strike(step, owner_id, rank)
  local player = combat.find(step.world, owner_id)
  if not player or not combat.is_alive(player) then return end
  show_strike(step, player, rank)
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature:get()
  return info and info.id or nil
end

-- ---- the player ------------------------------------------------------------------------------------------------------

local function hop(step)
  local t = block
  local facing = facing_of(step.player)
  combat.push(step.player, facing.x * t.hop_forward, facing.y * t.hop_forward)
  combat.set_vertical_velocity(step.player, t.hop_up)
end

-- ---- the skill tooltip -----------------------------------------------------------------------------------------------

-- Runs at the first frame, when the game's code is there to be wrapped: the name at index 9 of the World's skill-name map (each
-- step) and the numbers of the level lines. The words themselves are in assets/text/dict_en.xml.
local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "warrior", specialization = SPEC, name = TEXT_NAME,
    values = function(rank) return logic.tooltip_values(block, rank) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: berserker: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the definition --------------------------------------------------------------------------------------------------

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
end

local function on_start(ctx)
  setup()
  ctx.state.hopped = false
end

local function on_step(ctx)
  local t = block
  local state = ctx.state
  local elapsed = ctx.elapsed_ms
  if logic.holds_player(t, elapsed) then
    combat.defer(function(step) combat.stand_still(step.player) end)
  end
  if not state.hopped and logic.hop_due(t, elapsed) then
    state.hopped = true
    combat.defer(hop)
  end
  local rank = ctx.rank
  for _, name in ipairs(ctx:marker()) do
    if name == logic.MARKER_HIT then
      combat.defer(function(step) strike(step, rank) end)
    end
  end
end

local function watch_start(ctx)
  setup()
  ctx.state.owner = owner_of(ctx)
end

local function watch_step(ctx)
  local state = ctx.state
  state.owner = state.owner or owner_of(ctx)
  if not state.owner then return end
  local owner, rank = state.owner, ctx.rank
  for _, name in ipairs(ctx:marker()) do
    if name == logic.MARKER_HIT then
      combat.defer(function(step) watch_strike(step, owner, rank) end)
    end
  end
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "berserker.png",
    anim = "skills_unleashed:berserker",
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "warrior", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
    watch = { on_start = watch_start, on_step = watch_step },
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  kyubu.on("lifecycle.game_ready", setup_tooltip)
end

M._tick, M._flying, M._watch_strike, M._watch_step, M._show_strike = tick, flying, watch_strike, watch_step, show_strike

return M
end

-- @module skills_unleashed.abilities.fire_mage (abilities/fire_mage.lua)
package.preload["skills_unleashed.abilities.fire_mage"] = function(...)
-- skills_unleashed.abilities.fire_mage: Mage, Fire Mage, slot 4: Fire Circle.
-- The numbers are in lib/tuning.lua (`fire_mage`), the rules in logic/fire_mage.lua, the game's side in lib/combat; this module is
-- the callbacks.
--
--   on_start, on_step, on_end   only note what happened (the start, the clip's `cast` marker, the end): the work is done in the step
--                               below; on_step also ends the ability when the logic is through with it
--   every step (combat.every)   the charge: key 4 held grows the charge at the game's own rate (at most the mp), the player walks at
--                               half speed, the embers (EMTweaks' swirl) turn round the raised hands and swell with the charge, a
--                               sound repeats; the cooldown is held at its full length all along (an ability whose cooldown runs
--                               out under a held key ends and restarts, probe fire-mage-charge)
--                               the release: the key up (or held_max): the embers flare, the release clip is bound for the player
--                               alone (kyubu.animation.bind_for) and the mode time written to 0 so that it plays from its start (the
--                               loader sees a new activation: logic expects it)
--                               the cast, at the clip's `cast` marker: the charge is spent, the aimed spot (capped in range) gets a
--                               mark and, from there, the circle (EMTweaks' circle, built for the radius the charge gives) with the
--                               two points coming down onto it; the embers shrink away
--                               the circles, also after the ability is over: each becomes active when its points have landed and
--                               hurts every enemy in it every tick, without stunning it
--
-- Damage goes through the World's own hit, so a joined client sees the circle and does no damage (lib/combat can_hit); on a server
-- the damage is server/fire_mage.lua's, from the `cast { charge, spot }` a joined client sends at the cast (lib/ability_channel). Another player's cast is rebuilt by the watch callbacks:
-- the embers from the charge the server sends (`charged_mp`), the release from the run's restart (KyubuAbilityDef.restarts) with
-- the release clip bound for that creature, the cast at the clip's `cast` marker from that player's aim, and the circle drawn with
-- no damage.
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local fx = require("skills_unleashed.lib.fx")
local glow = require("skills_unleashed.lib.glow")
local terrain = require("skills_unleashed.lib.terrain")
local channel = require("skills_unleashed.lib.ability_channel")
local tooltip = require("skills_unleashed.lib.tooltip")
local units = require("skills_unleashed.lib.units")
local logic = require("skills_unleashed.logic.fire_mage")

local M = {}

local ID = "skills_unleashed:fire_mage"
local SPEC = "fire_mage"
local TEXT_NAME = "AbilityFireCircle"   -- the dictionary suffix: assets/text/dict_en.xml has description: and details: of it

local block = nil                 -- the checked tuning block
local state = logic.new_state()
local owner = nil                 -- the player creature the state belongs to (an address)
local number = nil                -- the ability's number, for the cooldown map
local handle = nil                -- the creature of the callbacks, for ending the ability
local ended = false               -- the end of the ability was asked for already
local pending = {}                -- what the callbacks noted since the last step: { kind =, ... } in order
local circles = {}                -- the circles alive (logic.new_circle), also after the ability is over
local circles_world = nil         -- the World they belong to
local mine = {}                   -- the player's embers: mine.ids = { first, second } emtweaks:swirl ids while the hands are raised
local slow_from = nil             -- where the slow left the player at the last step, {x, y} in blocks
local glow_left = 0             -- ms the player is to glow still after the ability is over
local PLAYER_LIGHT = {}           -- the key of the player's light (glow.light_set)
local bound_for = nil             -- the id of the player the release clip is bound for now (kyubu.animation.bind_for), or nil
local ready = false

local function facing_of(player)
  local x, y = units.facing(combat.yaw_deg(player))
  return { x = x, y = y }
end

local function place_of(player)
  local x, y, z = combat.position(player)
  return { x = x, y = y, z = z }
end

local function feet_of(player, place)
  return place.z - combat.height(player) / 2
end

-- The release clip for one creature (its game id), or (on false) that creature's binding dropped: the ability's own clip again.
local function bind_release(creature_id, on)
  if not kyubu.animation.bind_for then return end
  local ok, why = kyubu.animation.bind_for(ID, creature_id, on and block.release_clip or nil)
  if not ok then
    kyubu.warn("skills_unleashed: fire_mage: the release clip was not " .. (on and "bound" or "dropped") .. ": " .. tostring(why))
  end
end

local function release_clip_for(player)
  local id = combat.id(player)
  if bound_for and bound_for ~= id then bind_release(bound_for, false) end
  bind_release(id, true)
  bound_for = id
end

local function release_clip_off()
  if not bound_for then return end
  bind_release(bound_for, false)
  bound_for = nil
end

-- ---- the embers (`h` holds them: the player's own, or a watched player's) ---------------------------------------------------

local function embers_off(h)
  if not h.ids then return end
  fx.swirl_cancel(h.ids[1])
  fx.swirl_cancel(h.ids[2])
  h.ids = nil
end

local function embers_on(h, player)
  embers_off(h)
  local place = place_of(player)
  local centre = logic.hands_centre(block, place, feet_of(player, place), facing_of(player))
  local first, second = logic.ember_defs(block, centre)
  h.ids = { fx.swirl(first), fx.swirl(second) }
end

-- The embers follow the raised hands and swell with the charge (`scale`: nil keeps the size they have).
local function embers_follow(h, player, scale)
  if not h.ids then return end
  local place = place_of(player)
  local centre = logic.hands_centre(block, place, feet_of(player, place), facing_of(player))
  fx.swirl_set(h.ids[1], logic.first_pos(centre), nil, scale)
  fx.swirl_set(h.ids[2], logic.second_pos(block, centre), nil, scale)
end

local function embers_flare(h)
  if not h.ids then return end
  fx.swirl_set(h.ids[1], nil, nil, block.flare)
  fx.swirl_set(h.ids[2], nil, nil, block.flare)
end

local function embers_end(h)
  if not h.ids then return end
  fx.swirl_end(h.ids[1], block.ember_end_ticks)
  fx.swirl_end(h.ids[2], block.ember_end_ticks)
  h.ids = nil
end

-- ---- the circles -----------------------------------------------------------------------------------------------------------

local function circles_drop()
  for _, c in ipairs(circles) do
    fx.circle_cancel(c.id)
    fx.shockwave_cancel(c.mark)
    glow.light_clear(c)
  end
  circles = {}
end

-- A new World starts without circles.
local function reset_for(world)
  if world ~= circles_world then
    circles_drop()
    circles_world = world
  end
end

-- One tick of damage to every enemy in the circle: the World's own hit with no stun (kyubu.game.hit gives exactly none). A watched
-- player's circle is a look only: its damage is the server's.
local function hurt(step, c)
  if c.watch or not combat.can_hit(step.world) then return end
  local list = logic.targets(block, c, combat.enemies(step.world, step.player))
  if #list == 0 then return end
  local attacker = combat.id(step.player)
  local amount = logic.damage(block, combat.damage_stat(step.player))
  for _, e in ipairs(list) do
    combat.hit(attacker, e.addr, amount, 0, true)      -- a spell: the target's resistance, not its armor
    combat.flash(e.addr)                      -- the blink at once, as the game shows a hit
    c.hits = c.hits + 1
  end
end

local function circles_step(step)
  reset_for(step.world)
  for i = #circles, 1, -1 do
    local c = circles[i]
    local due, event, done = logic.circle_step(block, c, step.dt)
    if not c.land_sounded and c.age_ms >= logic.landing_ms(block) then      -- the sound is made as the circle appears, not at the star
      c.land_sounded = true
      combat.play_sound(block.land_sound, c.x, c.y, c.z, block.land_volume)
    end
    if event == "active" then
      kyubu.info(("skills_unleashed: fire_mage: the circle at %.1f, %.1f, %.1f (radius %.1f) is active"):format(c.x, c.y, c.z, c.radius))
    end
    for _ = 1, due do hurt(step, c) end
    local light = logic.circle_light(block, c)
    if light then glow.light_set(c, light) else glow.light_clear(c) end
    if logic.pulse_due(block, c, step.dt) then fx.shockwave(logic.pulse_def(block, c)) end
    local spots = logic.ember_spots(block, c, logic.embers_due(block, c, step.dt), math.random)
    for _, p in ipairs(spots) do
      local def = {}
      for k, v in pairs(block.ember_particle) do def[k] = v end
      def.color = p.color
      fx.burst(def, { units.to_units(p.x), units.to_units(p.y), units.to_units(p.z) })
    end
    if done then
      kyubu.info(("skills_unleashed: fire_mage: the circle is over after %d hits"):format(c.hits))
      glow.light_clear(c)
      table.remove(circles, i)
    end
  end
end

-- ---- the cast --------------------------------------------------------------------------------------------------------------

-- The circle of `player`'s cast with `charge`, at the spot their aim gives: the mark, the circle and the sound; `h`'s embers go.
-- `watch`: another player's, drawn only. Returns the spot and the radius.
local function circle_at(step, player, charge, seed, watch, h)
  local t = block
  local place = place_of(player)
  local ax, ay, az = combat.aim(player)
  local spot = logic.target(t, place, ax and { x = ax, y = ay, z = az } or nil, facing_of(player))
  spot.z = logic.find_ground(t, terrain.solid_fn(step.world), spot)
  local radius = logic.radius(t, charge)
  reset_for(step.world)
  local c = logic.new_circle(t, spot, radius, seed)
  c.watch = watch
  c.mark = fx.shockwave(logic.mark_def(t, c))
  c.id = fx.circle(logic.circle_def(t, c))
  circles[#circles + 1] = c
  embers_end(h)
  combat.play_sound(t.cast_sound, place.x, place.y, place.z, t.cast_volume)
  return spot, radius
end

local function cast(step)
  local player = step.player
  local charge = state.charge
  combat.set_mp(player, logic.mp_after(combat.mp(player), charge))
  combat.set_charged(player, 0)
  local spot, radius = circle_at(step, player, charge, state.casts, false, mine)
  -- A joined game's circle is the server's: it is told what was cast, and checks it. Here the circle is a look only.
  if combat.is_joined(step.world) then
    channel.send("cast", { charge = charge, spot = { x = spot.x, y = spot.y, z = spot.z } })
  end
  kyubu.info(("skills_unleashed: fire_mage: cast at %.1f, %.1f, %.1f (%s), charge %.2f, radius %.1f, ground %s")
    :format(spot.x, spot.y, spot.z, spot.clamped and "capped at the range" or spot.ahead and "no aim, ahead" or "the aim", charge,
      radius, terrain.available() and "found" or "not asked"))
end

-- ---- the activation --------------------------------------------------------------------------------------------------------

-- The activation is over for good (`outcome` is logic's word): the embers go, the charge bar is cleared and the cooldown is set.
local function over(step, outcome)
  local player = step.player
  slow_from = nil
  embers_off(mine)
  release_clip_off()
  if outcome ~= logic.ENDED_DIED then combat.set_charged(player, 0) end
  if number then combat.set_cooldown(player, number, logic.cooldown_after(block, outcome, state.rank or 1)) end
  handle, ended = nil, false
  kyubu.info(("skills_unleashed: fire_mage: over (%s)%s"):format(outcome, state.restart_missed and ", the mode time restart was not seen" or ""))
end

-- Everything is dropped without a write into the game: the world was left, or the player is another creature now.
local function forget()
  logic.finish(state, logic.ENDED_DIED)
  pending = {}
  circles_drop()
  circles_world = nil
  embers_off(mine)
  release_clip_off()
  owner, handle, ended, slow_from = nil, nil, false, nil
  glow.lights_forget()
  glow_left = 0
end

-- The slow of the charge: of the way the player went since the last step, only move_factor is kept.
local function slow(player)
  local x, y = combat.position(player)
  if slow_from then
    x, y = logic.slowed(slow_from, x, y, block.move_factor)
    combat.set_ground_position(player, x, y)
  end
  slow_from = { x = x, y = y }
end

local function run_pending(step)
  local queue = pending
  pending = {}
  for _, e in ipairs(queue) do
    if e.kind == "start" then
      if logic.on_start(state, e.rank) then
        number = e.number
        ended = false
        channel.new_run("cast")
        release_clip_off()              -- the charge clip again (the ability's own)
        embers_on(mine, step.player)
      end
    elseif e.kind == "marker" then
      if e.name == logic.MARKER_CAST and logic.on_cast(state) then cast(step) end
    elseif e.kind == "end" then
      local outcome = logic.on_ability_end(state, e.reason)
      if outcome then over(step, outcome) end
    end
  end
end

local function released(step)
  local t = block
  local player = step.player
  embers_flare(mine)
  slow_from = nil
  release_clip_for(player)
  logic.request_restart(state)
  combat.restart_mode_time(player)
  kyubu.info(("skills_unleashed: fire_mage: released after %d ms, charge %.2f (radius %.1f)"):format(state.held_ms, state.charge,
    logic.radius(t, state.charge)))
end

local function charge_effects(step)
  local t = block
  local player = step.player
  combat.set_charged(player, state.charge)
  embers_follow(mine, player, logic.ember_scale(t, state.charge))
  if logic.sound_due(state, step.dt, t.charge_sound_every_ms) then
    local p = place_of(player)
    combat.play_sound(t.charge_sound, p.x, p.y, p.z, t.charge_volume)
  end
end

-- The player gives a light at the hands (the loader's light API) while the ability is on and for glow_ms after it.
local function glow_step(step)
  local player = step.player
  if logic.active(state) then
    glow_left = block.glow_ms
  elseif glow_left > 0 then
    glow_left = glow_left - step.dt
  end
  if glow_left <= 0 then
    glow.light_clear(PLAYER_LIGHT)
    return
  end
  local place = place_of(player)
  local centre = logic.hands_centre(block, place, feet_of(player, place), facing_of(player))
  glow.light_set(PLAYER_LIGHT, logic.player_light(block, centre, glow_left))
end

local function tick(step)
  local t = block
  local player = step.player
  if owner ~= nil and owner ~= player then forget() end
  owner = player
  run_pending(step)
  circles_step(step)
  glow_step(step)
  if not logic.active(state) then return end

  if number then combat.set_cooldown(player, number, tuning.cooldown_at(t, state.rank or 1)) end
  if logic.charging(state) then slow(player) end
  local event = logic.step(t, state, step.dt, {
    alive = combat.is_alive(player), held = combat.ability_key_down(), mp = combat.mp(player) })
  if logic.charging(state) then charge_effects(step) end
  if event == logic.EVENT_RELEASE then
    released(step)
  elseif event == logic.EVENT_FIZZLE then
    embers_off(mine)
    kyubu.info(("skills_unleashed: fire_mage: released with %.2f, under the least charge: nothing is cast"):format(state.charge))
  elseif event == logic.EVENT_CAST then
    if logic.on_cast(state) then cast(step) end
  elseif event == logic.EVENT_FINISH and state.outcome == logic.ENDED_DIED then
    over(step, logic.finish(state, logic.ENDED_DIED))
  end
  if state.phase == logic.RELEASE then embers_follow(mine, player, nil) end      -- the hands go on until the cast
end

local setup                       -- below: the hook and the step callback, set up once

-- ---- another player's cast (the watch callbacks, a joined client) ----------------------------------------------------------
-- The run is the server's report of that player's mode: its charge is `charged_mp` as sent (the highest seen, since their client
-- clears it at the cast), its release is the run's restart (ctx.restarts 1), its cast the release clip's `cast` marker (or
-- cast_fallback_ms) from their aim as sent. Each step is deferred into the World step, where the player is looked up by id.

local function watch_drop(st)
  embers_off(st)
  if st.bound then
    bind_release(st.owner, false)
    st.bound = false
  end
end

local function watch_tick(step, st, now)
  local t = block
  local player = combat.find(step.world, st.owner)
  if not player then
    watch_drop(st)
    return
  end
  if not st.released then
    local charged = combat.charged(player)
    if charged > st.charge then st.charge = charged end
    if not st.ids and not st.cast then embers_on(st, player) end
    embers_follow(st, player, logic.ember_scale(t, st.charge))
    if logic.sound_due(st, now.dt, t.charge_sound_every_ms) then
      local p = place_of(player)
      combat.play_sound(t.charge_sound, p.x, p.y, p.z, t.charge_volume)
    end
    if now.restarts < 1 then return end
    st.released = true
    embers_flare(st)
    bind_release(st.owner, true)
    st.bound = true
  end
  if st.cast then return end
  local due = now.elapsed >= t.cast_fallback_ms
  for _, name in ipairs(now.markers) do if name == logic.MARKER_CAST then due = true end end
  if not due then
    embers_follow(st, player, nil)
    return
  end
  st.cast = true
  st.casts = (st.casts or 0) + 1
  local spot, radius = circle_at(step, player, st.charge, st.casts, true, st)
  kyubu.info(("skills_unleashed: fire_mage: watched cast at %.1f, %.1f, %.1f, charge %.2f, radius %.1f")
    :format(spot.x, spot.y, spot.z, st.charge, radius))
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature.get and ctx.creature:get()
  return info and info.id or nil
end

local function watch_start(ctx)
  setup()
  local st = ctx.state
  st.owner = owner_of(ctx)
  st.charge, st.released, st.cast, st.sound_ms = 0, false, false, 0
end

local function watch_step(ctx)
  local st = ctx.state
  st.owner = st.owner or owner_of(ctx)
  if not st.owner then return end
  local now = { elapsed = ctx.elapsed_ms, dt = ctx.dt_ms or 0, restarts = ctx.restarts or 0, markers = ctx:marker() }
  combat.defer(function(step) watch_tick(step, st, now) end)
end

local function watch_end(ctx)
  local st = ctx.state
  combat.defer(function() watch_drop(st) end)
end

M._watch_tick = watch_tick

-- ---- the skill tooltip -----------------------------------------------------------------------------------------------------

local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "mage", specialization = SPEC, name = TEXT_NAME,
    values = function(rank) return logic.tooltip_values(block, rank) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: fire_mage: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the definition --------------------------------------------------------------------------------------------------------

function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
end

local function on_start(ctx)
  setup()
  handle = ctx.creature
  pending[#pending + 1] = { kind = "start", rank = ctx.rank, number = ctx.number }
end

local function note_markers(ctx)
  for _, name in ipairs(ctx:marker()) do pending[#pending + 1] = { kind = "marker", name = name } end
end

-- The logic is through with the activation (the release is played out, or nothing was cast): the ability is ended from here.
local function on_step(ctx)
  handle = ctx.creature
  note_markers(ctx)
  if logic.wants_end(state) and not ended then
    ended = true
    local ok, why = kyubu.game.ability_end(handle)
    if not ok then kyubu.warn("skills_unleashed: fire_mage: the ability was not ended: " .. tostring(why)) end
  end
end

local function on_end(ctx)
  if ctx.reason == "gone" then
    forget()
    return
  end
  note_markers(ctx)
  pending[#pending + 1] = { kind = "end", reason = ctx.reason }
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "fire_mage.png",
    anim = t.charge_clip,
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "mage", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
    on_end = on_end,
    restarts = 1,                 -- the release writes the mode time 0 once: a server or a bystander keeps the run going
    watch = { on_start = watch_start, on_step = watch_step, on_end = watch_end },
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  kyubu.on("lifecycle.game_ready", setup_tooltip)
  kyubu.on("lifecycle.game_ready", setup)        -- the hook goes in at the menu: at the first use it costs a hitch
  kyubu.on("lifecycle.world_exit", forget)
end

return M
end

-- @module skills_unleashed.abilities.guardian (abilities/guardian.lua)
package.preload["skills_unleashed.abilities.guardian"] = function(...)
-- skills_unleashed.abilities.guardian: Warrior, Guardian, slot 4: Taunt.
-- The numbers are in lib/tuning.lua (`guardian`), the rules in logic/guardian.lua; this module is the callbacks and the game's side.
--
--   on_step    the clip's `shout` marker: the rings at the feet, and the enemy at the aimed point is taunted
--   every step (combat.every): each taunt is written into the creature's threat map again (the chase lowers it), the time runs,
--              and a taunt that ended gives the map back what it held
--   hooks (lib/sites): the damage a taunted creature does to its taunter is cut, it is drawn red, and the bolts are drawn over
--              its head in the place of the stun's mark; a creature that cannot be taunted for now is drawn blue
--
-- The player may walk through the whole ability: nothing holds them. Nothing is thrown and no damage is dealt.
-- A joined client: the taunt is the server's (server/guardian.lua). At the shout this
-- client draws the rings, plays the cue and sends `taunt { aim, from }` on skills_unleashed:ability; it writes no threat and cuts no
-- hit (the server cuts the hit before its packet is made). Every client, caster and bystander, draws the tint and the bolts from the
-- server's `taunt_on` / `taunt_off` on skills_unleashed:world, and the immunity's blue tint on its own clock after a `taunt_off`.
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local fx = require("skills_unleashed.lib.fx")
local sites = require("skills_unleashed.lib.sites")
local tooltip = require("skills_unleashed.lib.tooltip")
local units = require("skills_unleashed.lib.units")
local channel = require("skills_unleashed.lib.ability_channel")
local events = require("skills_unleashed.lib.world_events")
local logic = require("skills_unleashed.logic.guardian")

local M = {}

local ID = "skills_unleashed:guardian"
local SPEC = "guardian"
local TEXT_NAME = "AbilityTaunt"      -- the dictionary suffix: assets/text/dict_en.xml has description: and details: of it
local MODEL_ID = "skills_unleashed:taunt_bolts"            -- the two bolts over the head: assets/models/<file>.vox
local MODEL_FILE = "skills_unleashed-taunt-bolts.cub"

local block = nil                 -- the checked tuning block
local state = logic.new_state()   -- the taunts in force and the immunities (logic.new_state)
local state_world = nil           -- the World `state` belongs to: a new World starts empty
local joined = false              -- that World is a joined game: `state` is the server's taunts as told, drawn only
local ready = false
local bolt_slot = nil
local tint_factors = nil
local immune_factors = nil

local function world_pos(x, y, z)
  return { units.to_units(x), units.to_units(y), units.to_units(z) }
end

local function reset_for(world)
  if world ~= state_world then
    state = logic.new_state()
    state_world = world
    joined = world ~= nil and combat.is_joined(world)
  end
end

-- ---- the shout -------------------------------------------------------------------------------------------------------

local function shout(step, rank)
  local t = block
  local player = step.player
  reset_for(step.world)
  local px, py, pz = combat.position(player)
  for _, def in ipairs(logic.ring_defs(t, world_pos(px, py, pz - t.ring_drop))) do fx.shockwave(def) end
  combat.play_sound(t.shout_sound, px, py, pz)

  local ax, ay, az = combat.aim(player)
  local aim = ax and { x = ax, y = ay, z = az } or nil
  if joined then
    if aim then channel.send(logic.EVENT_TAUNT, { aim = aim, from = { x = px, y = py, z = pz } }) end
    kyubu.info(("skills_unleashed: guardian: shout at rank %d, joined: %s"):format(rank,
      aim and "the taunt is sent to the server" or "no aim, nothing sent"))
    return
  end
  local target = logic.pick_target(t, state, { x = px, y = py, z = pz }, aim, combat.enemies(step.world, player))
  if not target then
    kyubu.info(("skills_unleashed: guardian: shout at rank %d, aim %s: nobody taunted"):format(rank,
      aim and ("%.1f, %.1f, %.1f"):format(aim.x, aim.y, aim.z) or "none"))
    return
  end
  local taunter = combat.id(player)
  local prior = combat.threat_of(target.addr, taunter)
  logic.start(t, state, rank, target.id, taunter, prior)
  combat.set_threat(target.addr, taunter, logic.threat_value(t))
  kyubu.info(("skills_unleashed: guardian: taunt of creature %d at %.1f blocks (aim %.1f, %.1f, %.1f), rank %d, %.0f s%s")
    :format(target.id, math.sqrt((target.x - px) ^ 2 + (target.y - py) ^ 2), aim.x, aim.y, aim.z, rank,
      logic.duration_ms(t, rank) / units.MS_PER_S, ""))
end

-- ---- the taunts, every step --------------------------------------------------------------------------------------------

local function tick(step)
  reset_for(step.world)
  if next(state.taunts) == nil and next(state.immune) == nil then return end
  local t = block
  local alive, found = {}, {}
  combat.each_creature(step.world, function(c)
    local id = combat.id(c)
    found[id] = c
    if combat.is_alive(c) then alive[id] = true end
  end)
  if joined then
    logic.show_step(state, step.dt, found)
    return
  end
  for _, e in ipairs(logic.step(t, state, step.dt, alive)) do
    local c = found[e.target]
    if c and alive[e.target] then combat.set_threat(c, e.by, logic.restore_value(t, e.prior)) end
    kyubu.info(("skills_unleashed: guardian: taunt of creature %d ended (%s)"):format(e.target, e.reason))
  end
  for id, taunt in pairs(state.taunts) do
    local c = found[id]
    if c then combat.set_threat(c, taunt.by, logic.threat_value(t)) end
  end
end

-- ---- the game's hit and draw code --------------------------------------------------------------------------------------

local function install_sites()
  tint_factors = logic.tint(block)
  immune_factors = logic.immune_tint(block)
  sites.on_hit(function(attacker, victim, damage)
    if joined then return nil end           -- the server decides the cut
    logic.on_hit(state, attacker, victim)
    local cut = logic.scale_damage(block, state, attacker, victim, damage)
    return cut
  end)
  sites.on_tint(function(creature)
    local id = combat.id(creature)
    if state.taunts[id] then return tint_factors end
    if state.immune[id] then return immune_factors end
    return nil
  end)
  sites.on_mark(function(creature)
    return state.taunts[combat.id(creature)] ~= nil
  end, function()
    if bolt_slot == nil and kyubu.model and kyubu.model.slot then bolt_slot = kyubu.model.slot(MODEL_ID) end
    return bolt_slot
  end)
end

-- ---- the server's taunts, on a joined client ----------------------------------------------------------------------------------

-- `taunt_on` / `taunt_off` from the server (lib/world_events): taken in the next World step, where the World is known.
local function on_taunt_event(step, ev)
  reset_for(step.world)
  if not joined then return end
  if ev.kind == logic.EVENT_TAUNT_ON then
    logic.show_on(state, ev)
    kyubu.info(("skills_unleashed: guardian: the server: creature %s taunted by player %s"):format(tostring(ev.target),
      tostring(ev.by)))
  else
    logic.show_off(block, state, ev)
    kyubu.info(("skills_unleashed: guardian: the server: the taunt of creature %s ended (%s)"):format(tostring(ev.target),
      tostring(ev.why)))
  end
end

-- ---- the skill tooltip -------------------------------------------------------------------------------------------------

-- At the first frame: the name at index 9 of the World's skill-name map (each step) and the numbers of the level lines. The words
-- are in assets/text/dict_en.xml.
local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "warrior", specialization = SPEC, name = TEXT_NAME,
    values = function(rank) return logic.tooltip_values(block, rank) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: guardian: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the definition ----------------------------------------------------------------------------------------------------

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
  install_sites()
  for _, kind in ipairs({ logic.EVENT_TAUNT_ON, logic.EVENT_TAUNT_OFF }) do
    events.on(kind, function(ev) combat.defer(function(step) on_taunt_event(step, ev) end) end)
  end
end

local function on_start()
  setup()
  channel.new_run(logic.EVENT_TAUNT)
end

local function on_step(ctx)
  local rank = ctx.rank
  for _, name in ipairs(ctx:marker()) do
    if name == logic.MARKER_SHOUT then
      combat.defer(function(step) shout(step, rank) end)
    end
  end
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "guardian.png",
    anim = "skills_unleashed:guardian",
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "warrior", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  if kyubu.model and kyubu.model.add then
    local mok, merr = pcall(kyubu.model.add, MODEL_ID, MODEL_FILE)
    if not mok then kyubu.warn("skills_unleashed: guardian: the bolts' model was not added: " .. tostring(merr)) end
  else
    kyubu.warn("skills_unleashed: guardian: this Kyubu has no kyubu.model: no bolts over the taunted creature")
  end
  kyubu.on("lifecycle.game_ready", setup_tooltip)
  kyubu.on("lifecycle.game_ready", setup)          -- the hooks and the server's events go in at the menu: bystanders draw too
end

M._tick = tick
M._state = function() return state end

return M
end

-- @module skills_unleashed.abilities.ninja (abilities/ninja.lua)
package.preload["skills_unleashed.abilities.ninja"] = function(...)
-- skills_unleashed.abilities.ninja: Rogue, Ninja, slot 4: Flash Bomb.
-- The numbers are in lib/tuning.lua (`ninja`), the rules in logic/ninja.lua; this module is the callbacks and the game's side.
--
--   on_start   notes the rank; the next World step binds the ground clip or, off the ground, the air clip
--   markers    `jump`: the player is pushed up (in the air too); `throw`: the bomb leaves the hand, downward, leaning with the camera
--              (a marker not told in time is acted on at the clip's own time: logic.cast_step)
--   every step (combat.every), also after the ability is over:
--              the bomb flies (EMTweaks' ghost of the mod's bomb model) until it strikes an enemy or the ground; the blast: every enemy
--              within 2 blocks is hit with 2 times the damage stat, the one struck stunned; the bang (the mod's own sound), the flash (a
--              ghost) and the smoke (the game's particles); the player is kicked away from it into the bounce clip (the mode time is
--              rewound so the clip plays from its start, as the Fire Mage's release); then true stealth.
--              True stealth, each step while it lasts: the threat for the player of every enemy that holds one is written below 0
--              (never the target), the player is kept out of the monsters' first-target scan (lib/sites on_scan) and the game's
--              stealth is held full (the pale stealth look). It ends when its time runs out, the game's own stealth then draining
--              away, or at once when the player deals damage (lib/sites on_hit; this build has no poison), with the game's stealth
--              set to 0. At its end the entries it held below 0 are erased: an entry left in a map comes back as 0.01 and makes
--              the player that monster's target from any distance (an enemy without one is never given one).
--
-- The player walks at full speed throughout (lib/sites on_walk, as the Water Mage). A joined client throws and flies but hurts and
-- hides from nothing: the monsters are the server's (server/ninja.lua). At the throw it sends `bomb { from, view }` to the server
-- (lib/ability_channel), which throws its own bomb and runs true stealth on its monsters. The
-- look stays this client's own; a `stealth_off` from the server (lib/world_events) with `revealed` for this player ends it: a
-- joined client does not see its own hits on monsters at its hit sites.
--
-- Another player's Flash Bomb (a bystander) is drawn from the server's events alone: `bomb { owner, from, view }` throws a
-- look-only copy that flies on this client's blocks (it hits nothing and stops at its own impact without a burst), `burst { owner,
-- x, y, z }` ends it and draws the flash, smoke and bang at the server's point, and `stealth_on { owner, ms }` holds the game's
-- stealth full on that player's creature here (the pale look; the game drains only the local player's) until `stealth_off`, or
-- `ms` + `watch_stealth_slack_ms` if that is lost, then writes 0. This player's own events are skipped: it draws its own.
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local bow = require("skills_unleashed.lib.bow")
local fx = require("skills_unleashed.lib.fx")
local sites = require("skills_unleashed.lib.sites")
local sound = require("skills_unleashed.lib.sound")
local terrain = require("skills_unleashed.lib.terrain")
local tooltip = require("skills_unleashed.lib.tooltip")
local units = require("skills_unleashed.lib.units")
local channel = require("skills_unleashed.lib.ability_channel")
local events = require("skills_unleashed.lib.world_events")
local logic = require("skills_unleashed.logic.ninja")

local M = {}

local ID = "skills_unleashed:ninja"
local SPEC = "ninja"
local TEXT_NAME = "AbilityFlashBomb"   -- the dictionary suffix: assets/text/dict_en.xml has description: and details: of it

local block = nil
local state = logic.new_state()
local state_world = nil
local owner = 0                   -- the local player, as last seen in a step
local pending = {}                -- the callbacks' news for the next step: { kind = "start"|"marker"|"end", ... }
local handle = nil                -- the creature the loader gave the callbacks (for ability_end)
local ended = false
local bound = nil                 -- the clip bound now
local bomb = nil                  -- the bomb in flight (logic.throw), and its ghost
local bomb_ghost, bomb_spin = nil, 0
local flashes = {}                -- { ghost = id, left = ms }: the flashes shown now (this player's and watched ones)
local watched = {}                -- player id -> { bomb = logic's bomb, ghost = id, spin = deg, world = World }: another's bomb
local veiled = {}                 -- player id -> { left = ms, world = World }: another player's true stealth, drawn here
local models = nil                -- { bomb =, flash = } the .cub bytes once read
local ready = false
local walk_on, walk_after = false, false
local held = {}                   -- [creature address] = true: the enemies whose threat for the player true stealth holds below 0

local reset_for                   -- (below) a new World starts with nothing in flight

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  kyubu.warn("skills_unleashed: ninja: " .. text)
end

local function world_pos(x, y, z) return { units.to_units(x), units.to_units(y), units.to_units(z) } end

local function place_of(player)
  local x, y, z = combat.position(player)
  return { x = x, y = y, z = z }
end

local function bind(clip)
  if bound == clip then return end
  local ok, why = kyubu.animation.bind(ID, clip)
  if not ok then
    warn_once("bind:" .. clip, "the clip " .. clip .. " was not bound: " .. tostring(why))
    return
  end
  bound = clip
end

-- The camera's view: from its eye through the player's aim (the crosshair's ray), else to the player; nil outside a game.
local function view_of(player)
  local ex, ey, ez = bow.camera()
  if not ex then return nil end
  local tx, ty, tz = combat.aim(player)
  if not tx then tx, ty, tz = combat.position(player) end
  return { x = tx - ex, y = ty - ey, z = tz - ez }
end

-- ---- the look ------------------------------------------------------------------------------------------------------------

local function load_models()
  if models then return end
  local b, f = kyubu.read_file(block.bomb_model), kyubu.read_file(block.flash_model)
  if not b then warn_once("bomb", "the bomb's model was not found: the bomb flies unseen") end
  if not f then warn_once("flash", "the flash's model was not found: no flash") end
  models = { bomb = b, flash = f }
end

local function bomb_off()
  if bomb_ghost then fx.ghost_cancel(bomb_ghost) end
  bomb, bomb_ghost, bomb_spin = nil, nil, 0
end

local function flash_off()
  for _, f in ipairs(flashes) do fx.ghost_cancel(f.ghost) end
  flashes = {}
end

-- The ghost of bomb `b` in flight: `ghost` its ghost or nil, `spin` its turn (deg). Returns the ghost and the new turn.
local function spin_look(b, ghost, spin, dt)
  spin = (spin + block.bomb_spin * dt / units.MS_PER_S) % units.FULL_TURN_DEG
  local pos, rot = world_pos(b.x, b.y, b.z), { spin, spin, 0 }
  if ghost and fx.ghost_set(ghost, pos, rot, nil) then return ghost, spin end
  local id = fx.ghost({ cub = models.bomb, pos = pos, rotation = rot, voxel = block.bomb_voxel })
  return (id ~= 0) and id or nil, spin
end

local function bomb_look(dt)
  if not bomb or not models.bomb then return end
  bomb_ghost, bomb_spin = spin_look(bomb, bomb_ghost, bomb_spin, dt)
end

local function flash_step(dt)
  for i = #flashes, 1, -1 do
    local f = flashes[i]
    f.left = f.left - dt
    if f.left <= 0 then
      fx.ghost_cancel(f.ghost)
      table.remove(flashes, i)
    elseif not fx.ghost_set(f.ghost, nil, nil, f.left / block.flash_ms) then
      table.remove(flashes, i)
    end
  end
end

local function burst_look(impact)
  local pos = world_pos(impact.x, impact.y, impact.z)
  if models.flash then
    local id = fx.ghost({ cub = models.flash, pos = pos, voxel = block.flash_voxel })
    if id ~= 0 then flashes[#flashes + 1] = { ghost = id, left = block.flash_ms } end
  end
  for _, def in ipairs(block.smoke) do fx.burst(def, pos) end
  sound.play(block.bang_sound, block.bang_volume)
end

-- ---- true stealth --------------------------------------------------------------------------------------------------------

-- Every step while it lasts: the threat for the player below 0 on each enemy that holds an entry for the player (one without is
-- left alone: the scan cut keeps it from finding the player), the game's stealth full. Returns the end, if it ended.
local function hide(step, enemies)
  if not logic.stealthed(state) then return nil end
  local player = step.player
  if not combat.is_joined(step.world) then
    local pid = combat.id(player)
    for _, e in ipairs(enemies) do
      if combat.holds_threat(e.addr, pid) then
        combat.set_threat(e.addr, pid, block.drop_threat)
        held[e.addr] = true
      end
    end
  end
  combat.set_stealth(player, block.stealth_hold)
  local why = logic.stealth_step(state, step.dt)
  if why then kyubu.info("skills_unleashed: ninja: true stealth ran out: the game's own stealth goes on") end
  return why
end

-- Once true stealth is over (time, a hit dealt, death): the entries it held below 0 are erased, so the monsters it hid from have
-- forgotten the player and must find it again by the scan. An entry a hit raised since stays. Runs in the World step, never
-- inside a hit (applyHit walks the victim's map).
local function release(step, enemies)
  if next(held) == nil or logic.stealthed(state) then return end
  if not combat.is_joined(step.world) then
    local pid = combat.id(step.player)
    local n = 0
    for _, e in ipairs(enemies) do
      if held[e.addr] and combat.forget_threat(e.addr, pid, block.forget_at_most) then n = n + 1 end
    end
    kyubu.info(("skills_unleashed: ninja: %d enemies forgot the player"):format(n))
  end
  held = {}
end

-- lib/sites on_hit: a hit the player deals ends true stealth, and the game's stealth with it.
local function on_hit(attacker, victim, damage)
  if owner == 0 then return nil end
  local why = logic.stealth_on_hit(state, combat.id(owner), attacker, victim, damage)
  if why then
    combat.set_stealth(owner, 0)
    kyubu.info(("skills_unleashed: ninja: true stealth ended: the player hit creature %d"):format(victim))
  end
  return nil
end

-- The server's `stealth_off` (a joined game): a hit this player dealt ended true stealth there, so the look ends here too.
local function on_stealth_off(ev)
  if ev.why ~= logic.END_REVEALED or owner == 0 or ev.owner ~= combat.id(owner) or not logic.stealthed(state) then return end
  state.stealth = nil
  combat.set_stealth(owner, 0)
  kyubu.info("skills_unleashed: ninja: true stealth ended: the server saw the player's hit")
end

-- lib/sites on_scan: the player is out of every monster's first-target scan while true stealth lasts.
local function on_scan(creature) return creature == owner and logic.stealthed(state) end

-- ---- another player's bomb and stealth (a bystander) ---------------------------------------------------------------------

local function own_id(step) return (step.player and step.player ~= 0) and combat.id(step.player) or nil end

local function unwatch(id)
  local w = watched[id]
  if w and w.ghost then fx.ghost_cancel(w.ghost) end
  watched[id] = nil
end

local function unveil(step, id, why)
  veiled[id] = nil
  local c = combat.find(step.world, id)
  if c then combat.set_stealth(c, 0) end
  kyubu.info(("skills_unleashed: ninja: watched stealth of player %d ended (%s)"):format(id, why))
end

local function finite(v) return type(v) == "number" and v == v and v ~= math.huge and v ~= -math.huge end
local function point(p) return type(p) == "table" and finite(p.x) and finite(p.y) and finite(p.z) end

-- The server's events, each in the World step after it came. This player's own are skipped (it draws its own).
local function on_watch_event(step, ev)
  reset_for(step.world)
  if type(ev.owner) ~= "number" or ev.owner == own_id(step) then return end
  local id = ev.owner
  if ev.kind == logic.EVENT_BOMB then
    if not point(ev.from) or (ev.view ~= nil and not point(ev.view)) then return end
    load_models()
    unwatch(id)
    watched[id] = { bomb = logic.throw(block, ev.from, ev.view), world = step.world, spin = 0 }
    kyubu.info(("skills_unleashed: ninja: watched bomb of player %d from %.1f, %.1f, %.1f"):format(id, ev.from.x, ev.from.y,
      ev.from.z))
  elseif ev.kind == logic.EVENT_BURST then
    if not finite(ev.x) or not finite(ev.y) or not finite(ev.z) then return end
    load_models()
    unwatch(id)
    burst_look({ x = ev.x, y = ev.y, z = ev.z })
    kyubu.info(("skills_unleashed: ninja: watched burst of player %d at %.1f, %.1f, %.1f"):format(id, ev.x, ev.y, ev.z))
  elseif ev.kind == logic.EVENT_STEALTH_ON then
    if not finite(ev.ms) or ev.ms <= 0 then return end
    veiled[id] = { left = ev.ms + block.watch_stealth_slack_ms, world = step.world }
    kyubu.info(("skills_unleashed: ninja: watched stealth of player %d for %.1f s"):format(id, ev.ms / units.MS_PER_S))
  elseif ev.kind == logic.EVENT_STEALTH_OFF then
    if veiled[id] then unveil(step, id, tostring(ev.why)) end
  end
end

-- Every step: the watched bombs fly (look only: no enemy stops them, the ground does) and the watched stealth is held.
local function watch_step(step)
  local solid = nil
  for id, w in pairs(watched) do
    if w.world ~= step.world then
      unwatch(id)
    else
      solid = solid or terrain.solid_fn(step.world)
      if logic.fly(block, w.bomb, step.dt, {}, solid) then
        unwatch(id)
      elseif models.bomb then
        w.ghost, w.spin = spin_look(w.bomb, w.ghost, w.spin, step.dt)
      end
    end
  end
  for id, v in pairs(veiled) do
    v.left = v.left - step.dt
    local c = combat.find(step.world, id)
    if v.world ~= step.world or not c then
      veiled[id] = nil
    elseif v.left <= 0 then
      unveil(step, id, "no stealth_off came")
    else
      combat.set_stealth(c, block.stealth_hold)
    end
  end
end

-- ---- the blast -----------------------------------------------------------------------------------------------------------

local function blast(step, impact, enemies)
  local player = step.player
  local victims = logic.victims(block, impact, enemies)
  if #victims > 0 and combat.can_hit(step.world) then
    local damage = logic.damage(block, combat.damage_stat(player))
    local pid = combat.id(player)
    for _, v in ipairs(victims) do combat.hit(pid, v.c.addr, damage, v.stun_ms) end
  end
  burst_look(impact)
  local vx, vy, vz = logic.blast_push(block, place_of(player), impact)
  combat.launch(player, vx, vy, vz)
  logic.stealth_start(block, state, state.cast.rank)
  if logic.on_impact(state) then
    bind(block.clip_bounce)
    combat.restart_mode_time(player)
  end
  kyubu.info(("skills_unleashed: ninja: the bomb burst on %s at %.1f, %.1f, %.1f: %d hit, true stealth %.1f s"):format(
    impact.struck and ("creature " .. impact.struck.id) or impact.why, impact.x, impact.y, impact.z, #victims,
    logic.stealth_ms(block, state.cast.rank) / units.MS_PER_S))
end

-- ---- the cast ------------------------------------------------------------------------------------------------------------

local function act(step, event)
  local player = step.player
  if event == logic.EVENT_JUMP then
    combat.set_vertical_velocity(player, block.jump_speed)
  elseif event == logic.EVENT_THROW then
    bomb_off()
    load_models()
    local from, view = place_of(player), view_of(player)
    bomb = logic.throw(block, from, view)
    bomb_look(0)
    if combat.is_joined(step.world) then channel.send(logic.EVENT_BOMB, { from = from, view = view }) end
  end
end

local function run_pending(step)
  local queue = pending
  pending = {}
  for _, e in ipairs(queue) do
    if e.kind == "start" then
      if logic.on_start(state, e.rank, combat.on_ground(step.player)) then
        ended = false
        bind(logic.clip_for(block, not state.cast.air))
      end
    elseif e.kind == "marker" then
      act(step, logic.on_marker(state, e.name))
    elseif e.kind == "end" then
      logic.on_ability_end(state, e.reason)
    end
  end
end

-- A new World starts with nothing in flight.
function reset_for(world)
  if world == state_world then return end
  bomb_off()
  flash_off()
  for id in pairs(watched) do unwatch(id) end
  held, veiled = {}, {}
  state, state_world = logic.new_state(), world
end

local function tick(step)
  reset_for(step.world)
  owner = step.player
  run_pending(step)
  for _, event in ipairs(logic.cast_step(block, state, step.dt)) do act(step, event) end
  flash_step(step.dt)
  if next(watched) ~= nil or next(veiled) ~= nil then watch_step(step) end
  if not bomb and not logic.stealthed(state) and next(held) == nil then return end
  local enemies = combat.enemies(step.world, step.player)
  if bomb then
    local impact = logic.fly(block, bomb, step.dt, enemies, terrain.solid_fn(step.world))
    if impact then
      bomb_off()
      blast(step, impact, enemies)
    else
      bomb_look(step.dt)
    end
  end
  hide(step, enemies)
  release(step, enemies)
end

-- ---- the skill tooltip -----------------------------------------------------------------------------------------------------

local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "rogue", specialization = SPEC, name = TEXT_NAME,
    values = function(r) return logic.tooltip_values(block, r) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: ninja: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the walk ------------------------------------------------------------------------------------------------------------

local function keep_walk(player)
  if walk_on then return true end
  if walk_after then
    if combat.mode(player) == 0 and combat.mode_time(player) < sites.WALK_LOCK_AFTER_MS then return true end
    walk_after = false
  end
  return false
end

-- ---- the definition --------------------------------------------------------------------------------------------------------

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
  sites.on_hit(on_hit)
  sites.on_scan(on_scan)
  sites.on_walk(keep_walk)
  events.on(logic.EVENT_STEALTH_OFF, on_stealth_off)
  for _, kind in ipairs({ logic.EVENT_BOMB, logic.EVENT_BURST, logic.EVENT_STEALTH_ON, logic.EVENT_STEALTH_OFF }) do
    events.on(kind, function(ev) combat.defer(function(step) on_watch_event(step, ev) end) end)
  end
end

local function forget()
  bomb_off()
  flash_off()
  for id in pairs(watched) do unwatch(id) end
  veiled = {}
  logic.forget(state)
  pending, ended, owner = {}, false, 0
  walk_on, walk_after = false, false
  state, state_world = logic.new_state(), nil
end

local function note_markers(ctx)
  for _, name in ipairs(ctx:marker()) do pending[#pending + 1] = { kind = "marker", name = name } end
end

local function on_start(ctx)
  setup()
  handle = ctx.creature
  walk_on, walk_after = true, false
  channel.new_run(logic.EVENT_BOMB)
  pending[#pending + 1] = { kind = "start", rank = ctx.rank }
end

-- The cast is over (the bounce has played): the ability is ended from here.
local function on_step(ctx)
  handle = ctx.creature
  note_markers(ctx)
  if logic.wants_end(state) and not ended then
    ended = true
    local ok, why = kyubu.game.ability_end(handle)
    if not ok then kyubu.warn("skills_unleashed: ninja: the ability was not ended: " .. tostring(why)) end
  end
end

local function on_end(ctx)
  if ctx.reason == "gone" then
    forget()
    return
  end
  note_markers(ctx)
  pending[#pending + 1] = { kind = "end", reason = ctx.reason }
  walk_on, walk_after = false, true              -- the restart's end is followed at once by its start, which turns it back on
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "ninja.png",
    anim = t.clip,
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    restarts = 1,                 -- the blast writes the mode time 0 once (the bounce): a server or a bystander keeps the run going
    claim = { slot = tuning.SLOT, class = "rogue", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
    on_end = on_end,
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  bound = t.clip
  kyubu.on("lifecycle.game_ready", setup_tooltip)
  kyubu.on("lifecycle.game_ready", setup)          -- the hooks go in at the menu, never at a cast
  kyubu.on("lifecycle.world_exit", forget)
end

M._tick, M._on_hit, M._on_scan, M._on_stealth_off = tick, on_hit, on_scan, on_stealth_off
M._state = function() return state, bomb end       -- for the unit test
M._watched = function() return watched, veiled, flashes end

return M
end

-- @module skills_unleashed.abilities.scout (abilities/scout.lua)
package.preload["skills_unleashed.abilities.scout"] = function(...)
-- skills_unleashed.abilities.scout: Ranger, Scout, slot 4: Trap Deployment.
-- The numbers are in lib/tuning.lua (`scout`), the rules in logic/scout.lua; this module is the callbacks and the game's side.
--
--   on_step    the player's clip's `spawn` marker (the hand in front): a shut trap leaves the hand
--   every step (combat.every): each trap flies and bounces on the world's blocks (lib/terrain), then plays its own clips on its three
--              ghosts (lib/clip, lib/trap_rig, EMTweaks' emtweaks:ghost): the opening (`open`: trap_open.wav; armed at its
--              end), and once an enemy that is neither stunned nor snared is on it, the snap (`hit`: the damage, the snare, the
--              mod's trap_shut.wav, red particles at the others). A sprung trap lives as long as its snare, then fades, and the
--              snare ends with it; an armed trap fades after 5 min; a fourth trap of the player makes the oldest go at once.
--              While a trap waits (from its landing until it goes off) a V turns and bobs over it (a ghost of
--              models-src/make_trap_marker.py) and a still ring of EMTweaks' shockwave lies round it at the trigger radius; as it goes
--              off, the V and the ring go and a ring grows out and fades. The game's swing sound is the throw, its drop sound each
--              landing of the flight (louder the harder it lands).
--   the snare is lib/snare's: held in place, no AI, one pose, no stun, whitish.
--
-- The trap is no creature of the game: the game's creatures cannot wear a mod's model, and a hidden one could be hit and would block
-- arrows (probe trap-body). Its flight is the game's gravity (about 30 blocks/s^2, measured in that probe) on the game's blocks.
-- The player may walk through the whole ability.
--
-- A joined client: at the `spawn` marker it sends `throw { from, yaw }` to the server
-- (lib/ability_channel) and draws its own trap at once, as a prediction. The trap is the server's: it tells every joined client
-- (lib/world_events) trap_thrown, trap_landed, trap_armed, trap_sprung, trap_closed, trap_fading and trap_gone, and each client, the
-- caster and bystanders alike, draws from them. The caster's prediction becomes the server's trap of its run at trap_thrown and moves
-- to the server's place at trap_landed; a prediction the server never takes (a refused throw) goes after predict_ms. A trap that
-- follows the server only flies and plays its clips here: it springs, closes and fades when the server says so, and applies nothing.
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local fx = require("skills_unleashed.lib.fx")
local sound = require("skills_unleashed.lib.sound")
local snare = require("skills_unleashed.lib.snare")
local terrain = require("skills_unleashed.lib.terrain")
local clip = require("skills_unleashed.lib.clip")
local rig = require("skills_unleashed.lib.trap_rig")
local tooltip = require("skills_unleashed.lib.tooltip")
local units = require("skills_unleashed.lib.units")
local channel = require("skills_unleashed.lib.ability_channel")
local events = require("skills_unleashed.lib.world_events")
local effect_log = require("skills_unleashed.lib.effect_log")
local logic = require("skills_unleashed.logic.scout")

local M = {}

local ID = "skills_unleashed:scout"
local SPEC = "scout"
local TEXT_NAME = "AbilityTrap"   -- the dictionary suffix: assets/text/dict_en.xml has description: and details: of it

local block = nil
local state = logic.new_state()
local state_world = nil
local looks = {}                  -- trap id -> { ghosts = { [part] = id }, last = the pose it was last drawn in, snared = creature id,
                                  --   marker = the V's ghost (false: refused or gone), ring = the ring's shockwave (false: gone), ring_ms = its age }
local clips = nil                 -- { open =, snap = } once read
local models = nil                -- { plate =, jaw =, marker = } the .cub bytes once read
local by_sid = {}                 -- a joined client: the server's trap id -> the trap drawn for it
local my_run = 0                  -- a joined client: the run number of the last start (lib/ability_channel)
local clock = 0                   -- ms of World steps: the V's bob and turn
local ready = false
local warned = {}

local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  kyubu.warn("skills_unleashed: scout: " .. text)
end

local function world_pos(x, y, z) return { units.to_units(x), units.to_units(y), units.to_units(z) } end

local function load_assets()
  if clips then return end
  local t = block
  local open, why_open = clip.load(t.open_clip)
  local snap, why_snap = clip.load(t.snap_clip)
  if not open then warn_once("open", tostring(why_open) .. ": the trap opens at once") end
  if not snap then warn_once("snap", tostring(why_snap) .. ": the trap closes at once") end
  clips = { open = open, snap = snap }
  local plate, jaw = kyubu.read_file(t.plate_model), kyubu.read_file(t.jaw_model)
  if not plate or not jaw then warn_once("models", "the trap's models were not found: the traps work unseen") end
  local marker = kyubu.read_file(t.marker_model)
  if not marker then warn_once("marker", "the V's model was not found: no V over the traps") end
  models = { plate = plate, jaw = jaw, marker = marker }
end

-- The pose of a trap's parts: the clips sampled (a missing clip reads as the shut or the open trap of the rig).
local function shut_pose() return clips.open and clip.sample(clips.open, 0) or nil end
local function open_pose()
  if clips.open then return clip.sample(clips.open, clips.open.duration) end
  return shut_pose()
end
local function snap_pose(t_ms)
  if clips.snap then return clip.sample(clips.snap, t_ms) end
  return shut_pose()
end
local function open_ms() return clips.open and clips.open.duration or 0 end

-- ---- the ghosts -----------------------------------------------------------------------------------------------------------

local function part_model(name) if name == "plate" then return models.plate end return models.jaw end

local function draw(trap, pose)
  local look = looks[trap.id]
  if not look then return end
  look.last = pose
  local alpha = logic.alpha(block, trap)
  for name, p in pairs(rig.place(pose, trap, trap.yaw, block.voxel)) do
    local pos, rot = world_pos(p.x, p.y, p.z), { p.yaw, p.pitch, p.roll }
    local id = look.ghosts[name]
    if id then
      fx.ghost_set(id, pos, rot, alpha)
    elseif look.ghosts[name] == nil and part_model(name) then
      id = fx.ghost({ cub = part_model(name), pos = pos, rotation = rot, voxel = block.voxel, color = block.trap_color, alpha = alpha })
      if id == 0 then warn_once("ghosts", "EMTweaks refused a ghost (16 alive, or no emtweaks:ghost): a trap is not drawn") end
      look.ghosts[name] = id ~= 0 and id or false
    end
  end
end

-- ---- the V and the ring --------------------------------------------------------------------------------------------------

local function in_world(def)
  def.pos = world_pos(unpack(def.pos))
  return def
end

-- The V and the still ring go (false: they are not made again).
local function unmark(look)
  if look.marker then fx.ghost_cancel(look.marker) end
  if look.ring then fx.shockwave_cancel(look.ring) end
  look.marker, look.ring = false, false
end

-- The V and the ring of a waiting trap, made at its landing and kept each step; the ring is started anew before EMTweaks ends it.
local function mark(trap, dt)
  local look = looks[trap.id]
  if not look or look.ring == false then return end
  local t = block
  if look.ring_ms == nil or look.ring_ms >= t.ring_renew_ms then      -- a refused ring is tried again only at the next renewal
    local old = look.ring
    local id = fx.shockwave(in_world(logic.ring_def(t, trap)))
    if id == 0 then warn_once("ring", "EMTweaks refused the ring (or no emtweaks:shockwave): no ring round a trap") end
    look.ring, look.ring_ms = id ~= 0 and id or nil, 0
    if old then fx.shockwave_cancel(old) end
  end
  look.ring_ms = look.ring_ms + dt
  local place, yaw = logic.marker_place(t, trap, clock)
  local pos, rot = world_pos(place.x, place.y, place.z), { yaw, 0, 0 }
  if look.marker then
    fx.ghost_set(look.marker, pos, rot, nil)
  elseif look.marker == nil and models.marker then
    local id = fx.ghost({ cub = models.marker, pos = pos, rotation = rot, voxel = t.marker_voxel, color = t.marker_color,
      alpha = t.marker_alpha })
    if id == 0 then warn_once("ghosts", "EMTweaks refused a ghost (16 alive, or no emtweaks:ghost): a trap is not drawn") end
    look.marker = id ~= 0 and id or false
  end
end

-- Everything a trap shows goes.
local function clear_look(look)
  for _, id in pairs(look.ghosts) do if id then fx.ghost_cancel(id) end end
  if look.marker then fx.ghost_cancel(look.marker) end
  if look.ring then fx.shockwave_cancel(look.ring) end
end

-- Takes a trap out: what it shows goes and its snare ends.
local function drop(trap, why)
  local look = looks[trap.id]
  if look then
    clear_look(look)
    if look.snared then snare.release(look.snared) end
  end
  looks[trap.id] = nil
  if trap.sid then by_sid[trap.sid] = nil end
  logic.remove(state, trap)
  kyubu.info(("skills_unleashed: scout: trap %d gone (%s)"):format(trap.id, why))
end

local function reset_for(world)
  if world == state_world then return end
  for _, look in pairs(looks) do clear_look(look) end
  looks, state, state_world, by_sid = {}, logic.new_state(), world, {}
end

-- ---- the sounds -------------------------------------------------------------------------------------------------------------

local function play_at(name, trap, player)
  local px, py, pz = combat.position(player)
  local d = math.sqrt((trap.x - px) ^ 2 + (trap.y - py) ^ 2 + (trap.z - pz) ^ 2)
  local v = logic.sound_volume(block, d)
  if v > 0 then sound.play(name, v) end
end

-- ---- the throw ----------------------------------------------------------------------------------------------------------------

local function throw(step)
  local t = block
  reset_for(step.world)
  load_assets()
  local player = step.player
  local px, py, pz = combat.position(player)
  local yaw = combat.yaw_deg(player)
  local trap = logic.throw(t, state, { x = px, y = py, z = pz }, yaw)
  if terrain.solid(step.world, trap.x, trap.y, trap.z) then trap.x, trap.y = px, py end   -- the hand is in a wall: drop it at the feet
  looks[trap.id] = { ghosts = {} }
  if combat.is_joined(step.world) then
    -- the server's trap: this one is the prediction until trap_thrown; the server takes the fourth trap away (trap_gone)
    trap.follow, trap.predicted, trap.run, trap.wait_ms = true, true, my_run, 0
    state.traps[#state.traps + 1] = trap
    channel.send("throw", { from = { x = px, y = py, z = pz }, yaw = yaw })
  else
    for _, old in ipairs(logic.add(t, state, trap)) do drop(old, "a fourth trap") end
  end
  draw(trap, shut_pose())
  combat.play_sound(t.throw_sound, trap.x, trap.y, trap.z)
  kyubu.info(("skills_unleashed: scout: trap %d thrown from %.1f, %.1f, %.1f (yaw %.0f)%s"):format(trap.id, trap.x, trap.y, trap.z,
    trap.yaw, terrain.available() and "" or ", no ground lookup"))
end

-- ---- the jaws close --------------------------------------------------------------------------------------------------------------

local function close_on(step, trap)
  local t = block
  local look = looks[trap.id]
  play_at(t.shut_sound, trap, step.player)
  local can, why = combat.can_hit(step.world)
  local v = logic.victims(t, trap, combat.enemies(step.world, step.player), snare.is_snared, snare.can_snare)
  if not v.target then
    kyubu.info(("skills_unleashed: scout: trap %d closed on nobody"):format(trap.id))
    return
  end
  for _, e in ipairs(v.others) do
    fx.burst({ type = t.blood.type, count = t.blood.count, scale = t.blood.scale, spreading = t.blood.spreading, accel = t.blood.accel,
      color = t.blood_color }, world_pos(e.c.x, e.c.y, e.c.z))
  end
  if not can then
    kyubu.info(("skills_unleashed: scout: trap %d closed on creature %d: no damage (%s)"):format(trap.id, v.target.c.id, tostring(why)))
    return
  end
  local attacker = combat.id(step.player)
  local full, part = logic.damage(t, combat.damage_stat(step.player))
  combat.hit(attacker, v.target.c.addr, full, 0)
  local snared = false
  if v.snare and combat.is_alive(v.target.c.addr) then
    snared = snare.start(v.target.c.addr, nil, SPEC)
    if snared and look then look.snared = v.target.c.id end
  end
  for _, e in ipairs(v.others) do
    local knock = nil                -- the hit's own direction: the game makes it the knockback
    if not snare.is_snared(e.c.id) and not combat.unstoppable(e.c.addr) then
      local kx, ky, kz = logic.knock(t, trap, e)
      knock = { kx, ky, kz }
    end
    combat.hit(attacker, e.c.addr, part, 0, false, knock)
  end
  kyubu.info(("skills_unleashed: scout: trap %d closed on creature %d (%.0f damage%s), %d other(s) took %.0f"):format(trap.id,
    v.target.c.id, full, snared and ", snared" or (v.snare and ", not snared: it died" or ", not snared: snared or immune"), #v.others, part))
end

-- While a trap is armed and the option log_effects is on: the nearest enemy, now and then, so a trap that does not go off can
-- be read from the log.
local report_ms = {}
local function report(trap, enemies, dt)
  if not effect_log.enabled() then return end
  local left = (report_ms[trap.id] or 0) - dt
  if left > 0 then report_ms[trap.id] = left; return end
  report_ms[trap.id] = block.debug_every_ms
  local e, up = logic.nearest(block, trap, enemies)
  if not e then return end
  kyubu.info(("skills_unleashed: scout: trap %d armed at z %.2f: nearest enemy %d at %.2f blocks, feet %.2f above, middle %.2f above, stunned %s, snared %s")
    :format(trap.id, trap.z, e.c.id, e.d, up, e.c.middle - trap.z, tostring(e.c.stunned),
      tostring(snare.is_snared(e.c.id))))
end

-- ---- every step ----------------------------------------------------------------------------------------------------------------------

local function tick(step)
  reset_for(step.world)
  if #state.traps == 0 then return end
  local t = block
  clock = clock + step.dt
  local solid = terrain.solid_fn(step.world)
  local enemies = nil
  local list = {}
  for i, tr in ipairs(state.traps) do list[i] = tr end
  for _, trap in ipairs(list) do
    local pose
    if trap.predicted then trap.wait_ms = trap.wait_ms + step.dt end
    if trap.predicted and trap.wait_ms > t.predict_ms then
      drop(trap, "the server took no throw")
    elseif trap.phase == "flight" then
      logic.fly(t, trap, step.dt, solid)
      local v = logic.bounce_volume(t, trap.impact)
      if v > 0 then combat.play_sound(t.bounce_sound, trap.x, trap.y, trap.z, v) end
      trap.impact = nil
      pose = shut_pose()
    else
      local from = trap.t
      local was = trap.phase
      local entered = logic.advance(t, trap, step.dt, open_ms())
      if was == "opening" then
        for _, name in ipairs(clips.open and clip.crossed(clips.open, from, trap.t) or {}) do
          if name == logic.MARKER_OPEN then play_at(t.open_sound, trap, step.player) end
        end
      elseif was == "sprung" then
        local hit = clips.snap and clip.crossed(clips.snap, from, trap.t) or (from == 0 and { logic.MARKER_HIT } or {})
        for _, name in ipairs(hit) do
          if name == logic.MARKER_HIT and not trap.follow then close_on(step, trap) end
        end
      end
      if entered == "fading" then
        local look = looks[trap.id]
        if look and look.snared then snare.release(look.snared); look.snared = nil end
      end
      if trap.phase == "gone" then
        drop(trap, was == "fading" and "faded" or "ended")
      elseif trap.phase == "armed" and not trap.follow then
        enemies = enemies or combat.enemies(step.world, step.player)
        report(trap, enemies, step.dt)
        if logic.should_trigger(t, trap, enemies, snare.is_snared) then
          logic.spring(trap)
          local look = looks[trap.id]
          if look then unmark(look) end
          fx.shockwave(in_world(logic.pulse_def(t, trap)))
          kyubu.info(("skills_unleashed: scout: trap %d sprung"):format(trap.id))
        end
      end
      if trap.phase == "opening" then pose = clips.open and clip.sample(clips.open, trap.t) or shut_pose()
      elseif trap.phase == "armed" then pose = open_pose()
      elseif trap.phase == "sprung" then pose = snap_pose(trap.t)
      elseif trap.phase == "fading" then pose = (looks[trap.id] or {}).last end
    end
    if trap.phase ~= "gone" and looks[trap.id] then
      draw(trap, pose)
      if logic.marked(trap) then mark(trap, step.dt) end
    end
  end
end

-- ---- the server's traps (a joined client) ---------------------------------------------------------------------------------

local function sprung(trap)
  local look = looks[trap.id]
  if look then unmark(look) end
  fx.shockwave(in_world(logic.pulse_def(block, trap)))
  kyubu.info(("skills_unleashed: scout: trap %d sprung (the server's %d)"):format(trap.id, trap.sid))
end

-- The server threw a trap: the caster's own prediction of that run becomes it, any other is drawn anew.
local function on_thrown(step, ev)
  if by_sid[ev.id] then return end
  local me = step.player and combat.id(step.player)
  if me and ev.owner == me then
    for _, tr in ipairs(state.traps) do
      if tr.predicted and tr.run == ev.run then
        tr.predicted, tr.sid, tr.owner = false, ev.id, ev.owner
        by_sid[ev.id] = tr
        kyubu.info(("skills_unleashed: scout: trap %d is the server's trap %d"):format(tr.id, ev.id))
        return
      end
    end
  end
  local trap = logic.from_event(block, ev)
  trap.id, trap.born = state.next_id, state.next_id
  state.next_id = state.next_id + 1
  state.traps[#state.traps + 1] = trap
  by_sid[ev.id] = trap
  looks[trap.id] = { ghosts = {} }
  draw(trap, shut_pose())
  combat.play_sound(block.throw_sound, trap.x, trap.y, trap.z)
  kyubu.info(("skills_unleashed: scout: trap %d shown for the server's trap %d of player %s"):format(trap.id, ev.id, tostring(ev.owner)))
end

local function on_closed(step, trap, ev)
  local t = block
  if step.player then play_at(t.shut_sound, trap, step.player) end
  for _, id in ipairs(type(ev.others) == "table" and ev.others or {}) do
    local c = type(id) == "number" and combat.find(step.world, id)
    if c then
      local x, y, z = combat.position(c)
      fx.burst({ type = t.blood.type, count = t.blood.count, scale = t.blood.scale, spreading = t.blood.spreading, accel = t.blood.accel,
        color = t.blood_color }, world_pos(x, y, z))
    end
  end
  kyubu.info(("skills_unleashed: scout: trap %d closed (the server's %d) on creature %s"):format(trap.id, trap.sid, tostring(ev.target)))
end

-- One server event, in the World step after it came (the World and the player are known there).
local function on_event(step, ev)
  reset_for(step.world)
  load_assets()
  if ev.kind == "trap_thrown" then return on_thrown(step, ev) end
  local trap = type(ev.id) == "number" and by_sid[ev.id]
  if not trap then return end
  if ev.kind == "trap_gone" then return drop(trap, "the server: " .. tostring(ev.why)) end
  if ev.kind == "trap_closed" then return on_closed(step, trap, ev) end
  local was_x, was_y, was_z, was = trap.x, trap.y, trap.z, trap.phase
  if logic.on_event(trap, ev) == "sprung" then sprung(trap) end
  if ev.kind == "trap_landed" then
    kyubu.info(("skills_unleashed: scout: trap %d landed at the server's %.2f, %.2f, %.2f (drawn %s at %.2f blocks across, %.2f up)")
      :format(trap.id, trap.x, trap.y, trap.z, was, math.sqrt((was_x - trap.x) ^ 2 + (was_y - trap.y) ^ 2), was_z - trap.z))
  end
end

local EVENTS = { "trap_thrown", "trap_landed", "trap_armed", "trap_sprung", "trap_closed", "trap_fading", "trap_gone" }
local function listen()
  for _, kind in ipairs(EVENTS) do
    events.on(kind, function(ev) combat.defer(function(step) on_event(step, ev) end) end)
  end
end

-- ---- the skill tooltip -------------------------------------------------------------------------------------------------------------

local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "ranger", specialization = SPEC, name = TEXT_NAME,
    values = function(rank) return logic.tooltip_values(block, rank) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: scout: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the definition ------------------------------------------------------------------------------------------------------------------

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  snare.configure({ immune_ms = block.immune_ms, tint = block.snare_tint })
  snare.install()
  listen()
  combat.every(tick)
end

local function forget()
  for _, look in pairs(looks) do clear_look(look) end
  looks, state, state_world, by_sid = {}, logic.new_state(), nil, {}
end

local function on_step(ctx)
  for _, name in ipairs(ctx:marker()) do
    if name == logic.MARKER_SPAWN then combat.defer(throw) end
  end
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "scout.png",
    anim = "skills_unleashed:scout",
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "ranger", specialization = SPEC },
    on_start = function()
      setup()
      my_run = channel.new_run("throw")
    end,
    on_step = on_step,
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  kyubu.on("lifecycle.game_ready", setup_tooltip)
  kyubu.on("lifecycle.game_ready", setup)          -- the hooks go in at the menu, never at a cast
  kyubu.on("lifecycle.world_exit", forget)
end

M._tick, M._throw, M._state = tick, throw, function() return state, looks end   -- for the unit test

return M
end

-- @module skills_unleashed.abilities.sniper (abilities/sniper.lua)
package.preload["skills_unleashed.abilities.sniper"] = function(...)
-- skills_unleashed.abilities.sniper: Ranger, Sniper, slot 4: Bow of Light.
-- The numbers are in lib/tuning.lua (`sniper`), the rules in logic/sniper.lua, the game's side in lib/bow.lua; this module is the
-- callbacks.
--
--   on_start, on_step, on_end   only note what happened (the start, the clip's markers, the end): the work is done in the step below
--   every step (combat.every)   the summoning: from the press a slow white ring above the bow and see-through rays down from it
--                               that turn (EMTweaks' shockwave and beams), faded out at the take; the player walks at a third of
--                               the speed, white motes fall from above onto the bow
--                               and fade into it (from 450 ms), the spawn sound at `spawn` (the hands reach the clasp) and the bow
--                               fading in there (EMTweaks' ghost, put at each step where the game will draw the bow in the right
--                               hand: lib/grip), the take at `catch` (the ghost goes, the weapon becomes the bow of light in the
--                               same place)
--                               the lights (glow_step, lib/glow): the bow's at its point while it is held, the player's from the
--                               press until glow_ms after the ability is over; the held bow: the charge's particles and sound
--                               (its step follows the charged mp), the
--                               time; once, just after the take, the ghost's place is checked against the drawn bow (the log)
--                               all along: the mp guard, and the cooldown held at its full length until the bow is gone
--   every frame (frame.begin)   apart from the World's steps: a dead player loses the bow at once, and once it is gone a marked
--                               item still on the player is put right (lib/bow's repair)
--   lib/bow's sites             both mouse buttons charge, the game's own charge sound is silent, the release is one arrow (its sound the mod's), the
--                               arrow is straight, flies along the crosshair's ray, goes through every creature and has the
--                               mod's damage; its trail, and the puff where it ends; the bow cannot be taken out of the hand
--
-- In single-player the arrow's hits are the owner's. On a joined client the arrow still flies and is drawn (its shoot packet is the
-- server's input) but makes no hit: the server flies its checked copy and makes them (server/sniper.lua).
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local bow = require("skills_unleashed.lib.bow")
local fx = require("skills_unleashed.lib.fx")
local glow = require("skills_unleashed.lib.glow")
local grip = require("skills_unleashed.lib.grip")
local sound = require("skills_unleashed.lib.sound")
local tooltip = require("skills_unleashed.lib.tooltip")
local units = require("skills_unleashed.lib.units")
local logic = require("skills_unleashed.logic.sniper")

local M = {}

local ID = "skills_unleashed:sniper"
local SPEC = "sniper"
local TEXT_NAME = "AbilityBowOfLight"   -- the dictionary suffix: assets/text/dict_en.xml has description: and details: of it
-- the bow is a hand edit of the model models-src/make_bow_of_light.py builds (assets/models/); the arrow is the game's own, made white (bow.provide_white)
local BOW_MODEL_ID, BOW_MODEL_FILE = "skills_unleashed:bow_of_light", "skills_unleashed-bow-of-light_edited.cub"
local ARROW_MODEL_ID, ARROW_MODEL_FILE = "skills_unleashed:arrow_of_light", "skills_unleashed-arrow-of-light.cub"

local block = nil                 -- the checked tuning block
local state = logic.new_state()
local owner = nil                 -- the player creature the state belongs to (an address)
local number = nil                -- the ability's number, for the cooldown map
local pending = {}                -- what the callbacks noted since the last step: { kind =, ... } in order
local last_arrow = nil            -- where the arrow was at its last step, {x, y, z} in blocks
local steer_ms = 0                -- lib/fx steers the charge's and the trail's particles while this is above 0
local RULE_CHARGE, RULE_TRAIL, RULE_MOTES = "sniper.charge", "sniper.trail", "sniper.motes"
local RULE_SWIRL, RULE_PUFF = "sniper.swirl", "sniper.puff"
local swirl_phase = 0            -- the helix of the swirl, in radians at the arrow
local pulse_ms = 0               -- the time to the next pulse ring of the arrow
local ready = false
local slow_from = nil             -- where the slow left the player at the last step of the summoning, {x, y} in blocks
local watch = false               -- a bow was given in this world: the frame guard looks after the player until the world is left
local repair_ms = 0               -- until the frame guard's next look for a marked item
local ghost = nil                 -- the materializing bow (an emtweaks:ghost id) from `spawn` to `catch`
local bow_cub, bow_size = nil, nil   -- the bow model's bytes and size {x, y, z}, read once
local check_ms = nil              -- until the one check of the ghost's place against the drawn bow, after the take
local halo = nil                  -- the ring and its rays: { centre (blocks), age_ms, ring (id), rays = { ids }, fade_ms (nil until
                                  -- the fade) }
local glow_left = 0              -- ms the player is to glow still after the ability is over
local PLAYER_LIGHT, BOW_LIGHT = {}, {}   -- the keys of the player's light and of the bow's (glow.light_set)

local function world_pos(x, y, z)
  return { units.to_units(x), units.to_units(y), units.to_units(z) }
end

local function facing_of(player)
  local x, y = units.facing(combat.yaw_deg(player))
  return { x = x, y = y }
end

local function place_of(player)
  local x, y, z = combat.position(player)
  return { x = x, y = y, z = z }
end

-- ---- the summoning -------------------------------------------------------------------------------------------------------

-- The bow model's bytes and size (the mod's own file, as the game is served it), or nil when it cannot be read (logged once).
local function bow_model()
  if bow_size then return bow_cub, bow_size end
  if bow_cub == false then return nil end
  local ok, data = false, nil
  if kyubu.assets and kyubu.assets.read then ok, data = pcall(kyubu.assets.read, "data1.db", BOW_MODEL_FILE) end
  local size = ok and grip.cub_size(data) or nil
  if not size then
    bow_cub = false
    kyubu.warn("skills_unleashed: sniper: the bow's model " .. BOW_MODEL_FILE .. " cannot be read: no materializing bow, no motes")
    return nil
  end
  bow_cub, bow_size = data, size
  return bow_cub, bow_size
end

-- Where the bow is during the summoning (lib/grip's frame, world blocks): where the game would draw it in the right hand now, or,
-- when the player's draw record cannot be read, the tuning's fallback place. Nil without the model.
local function bow_frame(player)
  local _, size = bow_model()
  if not size then return nil end
  local at = place_of(player)
  return grip.read(player, size, at) or logic.fallback_frame(block, at, facing_of(player), size)
end

local function ghost_place(f)
  return world_pos(unpack(f.centre)), { grip.angles(f.axes) }
end

local function ghost_off()
  if ghost then fx.ghost_cancel(ghost) end
  ghost = nil
end

-- The halo: from the press a slow white ring over the bow and the rays down from it, which turn.
-- `fading`: the fade after the take, which takes the place of what is alive (EMTweaks cannot fade a ring or a ray it was given).
local function halo_spawn(fading)
  local t = block
  halo.ring = fx.shockwave(logic.halo_ring_def(t, world_pos(unpack(halo.centre)), halo.age_ms, fading))
  halo.rays = {}
  for k = 1, t.halo_rays do
    local start, dir, length = logic.halo_ray(t, halo.centre, halo.age_ms, k)
    halo.rays[k] = fx.beam(logic.halo_ray_def(t, world_pos(unpack(start)), dir, length, fading))
  end
end

local function halo_cancel()
  if not halo then return end
  fx.shockwave_cancel(halo.ring)
  for _, id in ipairs(halo.rays) do fx.beam_cancel(id) end
  halo = nil
end

local function halo_on(player)
  halo_cancel()
  halo = { centre = logic.halo_centre(block, place_of(player), facing_of(player)), age_ms = 0 }
  halo_spawn(false)
end

-- The take, or the summoning's end: the ring and the rays fade out where they are.
local function halo_fade()
  if not halo or halo.fade_ms then return end
  local age, centre = halo.age_ms, halo.centre
  halo_cancel()
  halo = { centre = centre, age_ms = age, fade_ms = block.halo_fade_ms }
  halo_spawn(true)
end

-- Every step: the rays turn; a faded halo is let go.
local function keep_halo(step)
  if not halo then return end
  local t = block
  halo.age_ms = halo.age_ms + step.dt
  if halo.fade_ms then
    halo.fade_ms = halo.fade_ms - step.dt
    if halo.fade_ms <= 0 then
      halo = nil
      return
    end
  end
  for k, id in ipairs(halo.rays) do
    local start, dir, length = logic.halo_ray(t, halo.centre, halo.age_ms, k)
    fx.beam_move(id, world_pos(unpack(start)), dir, length)
  end
end

-- No burst here: it did not fit; the motes are already falling, the ring and the rays come later. The bow
-- starts to fade in, see-through, where the hands will hold it.
local function spawn_bow(step)
  if not logic.on_spawn(state) then return end
  sound.play(block.spawn_sound, block.spawn_volume)
end

-- The bow starts to fade in (ghost_from_ms, before the clasp), once a summoning.
local ghost_shown = false
local function show_ghost(step)
  if ghost or ghost_shown or not logic.ghost_due(block, state) then return end
  ghost_shown = true
  local cub = bow_model()
  local f = bow_frame(step.player)
  if not cub or not f then return end
  local pos, rotation = ghost_place(f)
  local id = fx.ghost({ cub = cub, pos = pos, rotation = rotation, voxel = f.voxel, color = block.ghost_color,
    alpha = logic.ghost_alpha(block, state) })
  if id ~= 0 then ghost = id end
end

-- The ghost follows the hands and grows less see-through.
local function keep_ghost(f)
  if not ghost or not f then return end
  local pos, rotation = ghost_place(f)
  if not fx.ghost_set(ghost, pos, rotation, logic.ghost_alpha(block, state)) then ghost = nil end
end

local function take_bow(step)
  local t = block
  if not logic.on_catch(t, state) then return end
  ghost_off()                                   -- the real bow is drawn from this step, where the ghost was
  halo_fade()
  local ok, why = bow.swap_on(step.player)
  if not ok then kyubu.warn("skills_unleashed: sniper: the bow of light is not in the hand: " .. tostring(why)) end
  watch = true
  check_ms = t.grip_check_ms
end

-- Once after the take: the ghost's place (lib/grip, from the hand) against the bow the game drew in the same draw.
local function check_grip(step)
  if not check_ms then return end
  check_ms = check_ms - step.dt
  if check_ms > 0 then return end
  check_ms = nil
  local dist, deg = grip.check(step.player)
  if dist then
    kyubu.info(("skills_unleashed: sniper: the materializing bow against the drawn bow: %.3f blocks, %.1f degrees apart")
      :format(dist, deg))
  else
    kyubu.info("skills_unleashed: sniper: the materializing bow was not checked: no bow drawn in the hand")
  end
end

-- The bow is gone (`why` is logic's reason): the player's own weapon is back and the cooldown runs from now.
local function over(step, why)
  local player = step.player
  slow_from = nil
  ghost_off()
  halo_fade()
  check_ms = nil
  fx.rule(RULE_MOTES, nil)
  glow.light_clear(BOW_LIGHT)
  local back, how = bow.swap_off(player)
  if number then combat.set_cooldown(player, number, tuning.cooldown_at(block, state.rank or 1)) end
  kyubu.info(("skills_unleashed: sniper: the bow of light is gone (%s)%s"):format(why,
    back and "" or (", the own weapon not written back: " .. tostring(how))))
end

-- Everything is dropped without a write into the game: the world was left, or the player is another creature now.
local function forget()
  logic.finish(state, logic.ENDED_DIED)
  bow.forget()
  glow.lights_forget()
  glow_left = 0
  pending = {}
  fx.rule(RULE_CHARGE, nil)
  fx.rule(RULE_TRAIL, nil)
  fx.rule(RULE_SWIRL, nil)
  fx.rule(RULE_PUFF, nil)
  fx.rule(RULE_MOTES, nil)
  last_arrow, steer_ms = nil, 0
  owner = nil
  slow_from, watch, repair_ms = nil, false, 0
  ghost_off()                       -- a ghost has no life of its own: the mod that made it ends it
  halo_cancel()
  check_ms = nil
end

-- The slow of the summoning: of the way the player went since the last step, only move_factor is kept.
local function slow(player)
  local x, y = combat.position(player)
  if slow_from then
    x, y = logic.slowed(slow_from, x, y, block.move_factor)
    combat.set_ground_position(player, x, y)
  end
  slow_from = { x = x, y = y }
end

-- The falling motes of the summoning: their rule follows the bow (`frame`) at every step, so
-- they land on it while the hands and the player move, and new ones appear in the rectangle above its outline when they are due.
local function motes(step, frame)
  local t = block
  if not frame then return end
  local facing = facing_of(step.player)
  fx.rule(RULE_MOTES, logic.motes_rule(t, frame, facing))
  steer_ms = t.steer_linger_ms
  if logic.motes_due(t, state, step.dt) then
    local centre, along, length, depth = logic.motes_rect(t, frame, facing)
    fx.rect(logic.particles(t, "motes"), centre, along, t.motes_count, length, depth)
  end
end

local function run_pending(step)
  local queue = pending
  pending = {}
  for _, e in ipairs(queue) do
    if e.kind == "start" then
      if logic.active(state) then over(step, logic.finish(state, logic.ENDED_ABORTED)) end
      number = e.number
      ghost_shown = false
      logic.begin(state, e.rank, combat.mp(step.player))
      halo_on(step.player)
    elseif e.kind == "marker" then
      if e.name == logic.MARKER_SPAWN then spawn_bow(step)
      elseif e.name == logic.MARKER_CATCH then take_bow(step) end
    elseif e.kind == "end" then
      if e.reason == "done" then take_bow(step) end        -- a `catch` the last step did not report
      local ended = logic.on_ability_end(state, e.reason)
      if ended then over(step, ended) end
    end
  end
end

-- ---- the held bow --------------------------------------------------------------------------------------------------------

-- The particles of lib/fx's steering: the summoning's motes fall onto the bow, the charge's fly in to its middle, the trail's
-- live shorter. The rules stay for a while after the last use, for what is still in the air.
local function keep_steering(step)
  if steer_ms <= 0 then return end
  steer_ms = steer_ms - step.dt
  if steer_ms <= 0 then
    fx.rule(RULE_CHARGE, nil)
    fx.rule(RULE_TRAIL, nil)
    fx.rule(RULE_SWIRL, nil)
    fx.rule(RULE_PUFF, nil)
    fx.rule(RULE_MOTES, nil)
    return
  end
  fx.steer(step.dt)
end

local function charge_effects(step)
  local t = block
  local player = step.player
  local x, y, z = logic.bow_point(t, place_of(player), facing_of(player))
  fx.rule(RULE_CHARGE, logic.charge_rule(t, x, y, z))
  steer_ms = t.steer_linger_ms
  if logic.due(state, "ring_ms", step.dt, t.charge_particles_every_ms) then
    fx.sphere(logic.particles(t, "charge_particles"), { x, y, z }, t.charge_particles_count, t.charge_radius_min, t.charge_radius_max)
  end
  if logic.due(state, "sound_ms", step.dt, t.charge_sound_every_ms) then
    sound.play(logic.charge_sound(t, bow.charged(player)), t.charge_volume)
  end
end

-- The bow's light at its point while it is held, and the player's from the press: the glow goes on glow_ms after the ability is over.
local function glow_step(step)
  local t = block
  local player = step.player
  if state.has_bow then
    local x, y, z = logic.bow_point(t, place_of(player), facing_of(player))
    glow.light_set(BOW_LIGHT, logic.bow_light(t, { x = x, y = y, z = z }))
  else
    glow.light_clear(BOW_LIGHT)
  end
  if logic.active(state) then
    glow_left = t.glow_ms
  elseif glow_left > 0 then
    glow_left = glow_left - step.dt
  end
  if glow_left <= 0 then
    glow.light_clear(PLAYER_LIGHT)
    return
  end
  local place = place_of(player)
  local centre = { x = place.x, y = place.y, z = place.z - combat.height(player) / 2 + t.glow_height }
  glow.light_set(PLAYER_LIGHT, logic.player_light(t, centre, glow_left))
end

local function tick(step)
  local player = step.player
  if owner ~= nil and owner ~= player then forget() end
  owner = player
  run_pending(step)
  keep_halo(step)
  glow_step(step)
  pulse_ms = pulse_ms - step.dt
  bow.poll(step.dt, block.arrow_life_ms)
  if not logic.active(state) then
    keep_steering(step)
    return
  end
  local t = block

  if state.phase == logic.SUMMON then slow(player) else slow_from = nil end
  if number then combat.set_cooldown(player, number, tuning.cooldown_at(t, state.rank)) end
  local keep = logic.guard_mp(state, combat.mp(player))
  if keep then combat.set_mp(player, keep) end

  local ended = logic.step(t, state, step.dt, {
    alive = combat.is_alive(player), charging = bow.is_charging(player), shooting = bow.is_shooting(player) })
  if ended then
    over(step, ended)
    keep_steering(step)
    return
  end
  show_ghost(step)
  local frame = nil
  if ghost or logic.motes_on(t, state) then frame = bow_frame(player) end
  keep_ghost(frame)
  if logic.motes_on(t, state) then motes(step, frame) else fx.rule(RULE_MOTES, nil) end
  check_grip(step)
  if state.charging then charge_effects(step) end
  keep_steering(step)
end

-- ---- the frame guard -----------------------------------------------------------------------------------------------------
-- Once a frame, apart from the World's steps, which may not run for a dead player (the bow would
-- stay after a death): a player who died with the bow in the hand loses it at once, and after the bow is gone a marked item still on the
-- player (the slots, the cursor, the bags) is put right. Only the creature the steps saw, and only while it is still the game's
-- player: after the world is left nothing is written (forget).
local function guard_frame(ev)
  local player = owner
  if not watch or not player or bow.local_player() ~= player then return end
  if logic.active(state) then
    if state.has_bow and not combat.is_alive(player) then over({ player = player }, logic.finish(state, logic.ENDED_DIED)) end
    return
  end
  repair_ms = repair_ms - (ev and ev.dt or 0)
  if repair_ms > 0 then return end
  repair_ms = block.repair_every_ms
  local fixed = bow.repair(player)
  if #fixed > 0 then
    kyubu.warn("skills_unleashed: sniper: a bow of light was still on the player after it was gone: put right in "
      .. table.concat(fixed, ", "))
  end
end

-- ---- the arrow (lib/bow's sites) -------------------------------------------------------------------------------------------

local function armed(creature)
  return creature == owner and logic.armed(state)
end

-- The direction of the arrow that starts at `from` ({x, y, z} in blocks), or nothing for the game's own aim (logic/sniper.lua
-- decides: a far aim is the game's, a near one is levelled along the camera's heading).
local function arrow_direction(creature, from)
  local ax, ay, az = combat.aim(creature)
  if not ax then return nil end
  local ex, ey, ez = bow.camera()
  return logic.arrow_direction(block, ex and { x = ex, y = ey, z = ez } or nil, { x = ax, y = ay, z = az }, from)
end

local function on_arrow(creature, charge, sx, sy, sz)
  local t = block
  if not logic.on_arrow(state, charge) then return nil end
  local damage = logic.arrow_damage(t, combat.damage_stat(creature), state.charge)
  local facing = facing_of(creature)
  local p = place_of(creature)
  local x, y = p.x + facing.x * t.wave_forward, p.y + facing.y * t.wave_forward
  fx.shockwave(logic.wave_def(t, world_pos(x, y, p.z + t.bow_height), facing))
  sound.play(t.release_sound, t.release_volume)
  last_arrow, swirl_phase, pulse_ms = nil, 0, block.pulse_every_ms
  local dx, dy, dz = arrow_direction(creature, { x = sx, y = sy, z = sz })
  kyubu.info(("skills_unleashed: sniper: the arrow: charge %.2f, damage %.1f (%.1f times the damage stat), %s")
    :format(state.charge, damage, logic.damage_mult(t, state.charge), dx and "a near aim, levelled" or "the game's aim"))
  return damage, t.arrow_speed, dx, dy, dz
end

local function on_flight(x, y, z)
  local t = block
  local now = { x = x, y = y, z = z }
  steer_ms = t.steer_linger_ms          -- no plain trail: the swirl is the trail
  fx.rule(RULE_SWIRL, logic.swirl_rule(t))
  local swirl = logic.particles(t, "swirl")
  local points
  points, swirl_phase = logic.swirl(t, last_arrow, now, swirl_phase)
  for _, p in ipairs(points) do
    swirl.accel = p.vel
    fx.burst(swirl, world_pos(unpack(p.pos)))
  end
  if pulse_ms <= 0 then
    pulse_ms = pulse_ms + t.pulse_every_ms
    local dir = logic.flight_dir(last_arrow, now)
    if dir then fx.shockwave(logic.pulse_def(t, world_pos(x, y, z), dir)) end
  end
  last_arrow = now
end

local function on_surface(x, y, z)
  fx.rule(RULE_PUFF, logic.puff_rule(block))
  steer_ms = block.steer_linger_ms
  fx.burst(logic.particles(block, "puff"), world_pos(x, y, z))
  last_arrow = nil
end

-- ---- the skill tooltip ---------------------------------------------------------------------------------------------------

local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "ranger", specialization = SPEC, name = TEXT_NAME,
    values = function(rank) return logic.tooltip_values(block, rank) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: sniper: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the definition ------------------------------------------------------------------------------------------------------

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
  bow.set_bow_model(BOW_MODEL_ID)
  bow.set_arrow_model(ARROW_MODEL_ID)
  bow.install({ armed = armed, on_arrow = on_arrow, on_flight = on_flight, on_surface = on_surface, server_hits = combat.is_joined })
end

-- Before the game loads its models: the arrow of the mod is a white copy of the game's own (the bow is a file of the mod's).
function M.preinit()
  local t = tuning.get(SPEC)
  if not t then return end
  bow.provide_white(ARROW_MODEL_FILE, t.arrow_sources)
end

local function on_start(ctx)
  setup()
  pending[#pending + 1] = { kind = "start", rank = ctx.rank, number = ctx.number }
end

local function note_markers(ctx)
  for _, name in ipairs(ctx:marker()) do pending[#pending + 1] = { kind = "marker", name = name } end
end

local function on_step(ctx)
  note_markers(ctx)
end

local function on_end(ctx)
  if ctx.reason == "gone" then
    forget()
    return
  end
  note_markers(ctx)
  pending[#pending + 1] = { kind = "end", reason = ctx.reason }
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "sniper.png",
    anim = "skills_unleashed:sniper",
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "ranger", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
    on_end = on_end,
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  if kyubu.model and kyubu.model.add then
    for _, m in ipairs({ { BOW_MODEL_ID, BOW_MODEL_FILE }, { ARROW_MODEL_ID, ARROW_MODEL_FILE } }) do
      local mok, merr = pcall(kyubu.model.add, m[1], m[2])
      if not mok then kyubu.warn("skills_unleashed: sniper: the model " .. m[1] .. " was not added: " .. tostring(merr)) end
    end
  else
    kyubu.warn("skills_unleashed: sniper: this Kyubu has no kyubu.model: the bow and the arrow have the game's look")
  end
  kyubu.on("lifecycle.game_ready", setup_tooltip)
  kyubu.on("lifecycle.game_ready", setup)        -- the sites go in at the menu: at the first use they cost a 0.4 s hitch
  kyubu.on("lifecycle.world_enter", bow.world_entered)
  kyubu.on("lifecycle.world_exit", forget)
  kyubu.on("frame.begin", guard_frame)
end

return M
end

-- @module skills_unleashed.abilities.water_mage (abilities/water_mage.lua)
package.preload["skills_unleashed.abilities.water_mage"] = function(...)
-- skills_unleashed.abilities.water_mage: Mage, Water Mage, slot 4: Chain of the Deep.
-- The numbers are in lib/tuning.lua (`water_mage`), the rules in logic/water_mage.lua; this module is the callbacks and the game's side.
--
--   on_start   notes the rank
--   on_step    the clip's `cast` marker (the hands are flung out): a pulse leaves the mage's feet (EMTweaks' emtweaks:pulse) with
--              the cast sound
--   every step (combat.every), also after the ability is over: each pulse grows its hitbox by the clock of the ring that is drawn; an
--              enemy the ring reaches is snared (lib/snare: held, no AI, one pose, no stun, whitish; the Scout's trap uses the same) for
--              the rank's length and gets chains (emtweaks:chains) sized by its hitbox and a chains sound (5 a pulse at most, 70 ms apart). When
--              a snare ends the chains fade with drops (or go at once if the creature is gone). A creature that is snared already, or
--              that was snared in the last 10 s (by this or by a trap), is passed over.
--
-- The player walks through the whole ability at full speed: the game halves a walk's cap while an ability runs (probe
-- ability-walk-speed), and lib/sites on_walk keeps it whole from on_start until the game's lock after on_end is over.
-- A joined client applies nothing: the monsters are the server's (lib/combat is_joined). It draws its ring at
-- once, and the chains of each snare when the server tells of it (lib/snare on_shown), caster and bystanders alike.
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local fx = require("skills_unleashed.lib.fx")
local sites = require("skills_unleashed.lib.sites")
local snare = require("skills_unleashed.lib.snare")
local sound = require("skills_unleashed.lib.sound")
local tooltip = require("skills_unleashed.lib.tooltip")
local units = require("skills_unleashed.lib.units")
local logic = require("skills_unleashed.logic.water_mage")

local M = {}

local ID = "skills_unleashed:water_mage"
local SPEC = "water_mage"
local TEXT_NAME = "AbilityChainOfTheDeep"   -- the dictionary suffix: assets/text/dict_en.xml has description: and details: of it

local block = nil
local state = logic.new_state()
local state_world = nil
local rank = 1                    -- the rank of the activation under way
local chains = {}                 -- creature id -> the EMTweaks chains set round it
local ready = false
local walk_on = false             -- from on_start to on_end: the walk keeps its full speed
local walk_after = false          -- after on_end, while the game's lock of the mode that follows may still hold

local function world_pos(x, y, z) return { units.to_units(x), units.to_units(y), units.to_units(z) } end

-- The feet: the bottom of the hitbox, read by the loader from the mapped fields (combat.feet_z). nil and why without them.
local function feet_of(player)
  local x, y = combat.position(player)
  local z, why = combat.feet_z(player)
  if not z then return nil, why end
  return { x = x, y = y, z = z }
end

-- ---- the chains ------------------------------------------------------------------------------------------------------------

-- A snare ended (lib/snare's listener): the chains of that creature fade with their drops, or go at once when it is gone.
local function snare_ended(id, why)
  local set = chains[id]
  if not set then return end
  chains[id] = nil
  if why == "gone" then fx.chains_cancel(set) else fx.chains_end(set) end
end

local function chains_on(e)
  local def = logic.chains_def(block, e)
  def.pos = world_pos(unpack(def.pos))
  local set = fx.chains(def)
  if set == 0 then
    kyubu.warn("skills_unleashed: water_mage: EMTweaks refused the chains (32 alive, or no emtweaks:chains): the creature is held unchained")
    return
  end
  chains[e.id] = set
end

local function drop_all()
  for id, set in pairs(chains) do
    fx.chains_cancel(set)
    chains[id] = nil
  end
end

-- A new World starts without pulses or chains.
local function reset_for(world)
  if world == state_world then return end
  drop_all()
  state, state_world = logic.new_state(), world
end

-- A joined client: the server snared creature `id`. A Water Mage's snare gets its chains at the next World step, if the creature
-- is in this client's World and still shown snared then.
local function shown(id, by)
  if by ~= SPEC then return end
  combat.defer(function(step)
    reset_for(step.world)                            -- before the ring's tick of this step would, which would drop these chains
    if chains[id] or not snare.is_snared(id) then return end
    local c = combat.find(step.world, id)
    if not c then return end
    chains_on(combat.read(c))
    kyubu.info(("skills_unleashed: water_mage: creature %d snared by the server: chained"):format(id))
  end)
end

-- ---- the pulse -------------------------------------------------------------------------------------------------------------

local function cast(step)
  reset_for(step.world)
  local player = step.player
  local feet, why = feet_of(player)
  if not feet then
    kyubu.warn("skills_unleashed: water_mage: no pulse, the feet are unknown: " .. tostring(why))
    return
  end
  sound.play(block.cast_sound, block.cast_volume)
  local pulse = logic.new_pulse(state, feet, rank)
  logic.add(state, pulse)
  local def = logic.pulse_def(block, pulse)
  def.pos = world_pos(unpack(def.pos))
  if fx.pulse(def) == 0 then
    kyubu.warn("skills_unleashed: water_mage: EMTweaks refused the pulse (16 alive, or no emtweaks:pulse): the ring is not drawn")
  end
  kyubu.info(("skills_unleashed: water_mage: pulse %d from %.1f, %.1f, %.1f (rank %d, snare %.1f s)"):format(pulse.id, feet.x, feet.y,
    feet.z, pulse.rank, logic.snare_ms(block, pulse.rank) / units.MS_PER_S))
end

-- The enemies the ring reached this step are snared and chained, and a chains sound is queued for each (logic.queue_sounds).
local function catch(step, pulse, caught)
  if #caught == 0 then return end
  local before = pulse.snared
  local joined = combat.is_joined(step.world)         -- a joined client's monsters are the server's: nothing is applied
  local length = logic.snare_ms(block, pulse.rank)
  for _, entry in ipairs(caught) do
    local e = entry.c
    if not entry.snare then
      kyubu.info(("skills_unleashed: water_mage: creature %d reached at %.1f blocks: snared or immune"):format(e.id, entry.d))
    elseif joined then
      kyubu.info(("skills_unleashed: water_mage: creature %d reached at %.1f blocks: not snared (a joined client)"):format(e.id, entry.d))
    elseif snare.start(e.addr, length, SPEC) then
      pulse.snared = pulse.snared + 1
      chains_on(e)
      kyubu.info(("skills_unleashed: water_mage: creature %d snared at %.1f blocks for %.1f s"):format(e.id, entry.d, length / units.MS_PER_S))
    end
  end
  logic.queue_sounds(block, pulse, pulse.snared - before)
end

local function tick(step)
  reset_for(step.world)
  if #state.pulses == 0 then return end
  local enemies = combat.enemies(step.world, step.player)
  local list = {}
  for i, p in ipairs(state.pulses) do list[i] = p end
  for _, pulse in ipairs(list) do
    local caught, ring_done = logic.step(block, pulse, step.dt, enemies, snare.can_snare)
    catch(step, pulse, caught)
    for _ = 1, logic.due_sounds(pulse) do sound.play(block.catch_sound, block.catch_volume) end
    if logic.over(pulse, ring_done) then
      logic.remove(state, pulse)
      kyubu.info(("skills_unleashed: water_mage: pulse %d is over: %d snared"):format(pulse.id, pulse.snared))
    end
  end
end

-- ---- the skill tooltip -----------------------------------------------------------------------------------------------------

local function setup_tooltip()
  local ok, why = tooltip.register({
    class = "mage", specialization = SPEC, name = TEXT_NAME,
    values = function(r) return logic.tooltip_values(block, r) end,
  })
  if not ok then
    kyubu.warn("skills_unleashed: water_mage: tooltip: " .. tostring(why))
    return
  end
  if not tooltip.init() then return end
  tooltip.keep_names(combat)
end

-- ---- the walk ------------------------------------------------------------------------------------------------------------

-- lib/sites on_walk: true keeps the player's full walk speed this frame.
local function keep_walk(player)
  if walk_on then return true end
  if walk_after then
    if combat.mode(player) == 0 and combat.mode_time(player) < sites.WALK_LOCK_AFTER_MS then return true end
    walk_after = false
  end
  return false
end

-- ---- the definition --------------------------------------------------------------------------------------------------------

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  snare.configure({ immune_ms = block.immune_ms, tint = block.snare_tint })
  snare.on_end(snare_ended)
  snare.on_shown(shown)
  snare.install()
  combat.every(tick)
  sites.on_walk(keep_walk)
end

local function forget()
  drop_all()
  walk_on, walk_after = false, false
  state, state_world = logic.new_state(), nil
end

local function on_start(ctx)
  setup()
  rank = ctx.rank
  walk_on, walk_after = true, false
end

local function on_end()
  walk_on, walk_after = false, true
end

local function on_step(ctx)
  for _, name in ipairs(ctx:marker()) do
    if name == logic.MARKER_CAST then
      rank = ctx.rank
      combat.defer(cast)
    end
  end
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, {
    icon = "cubeworld:smash",
    icon_file = "water_mage.png",
    anim = t.clip,
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "mage", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
    on_end = on_end,
  })
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  kyubu.on("lifecycle.game_ready", setup_tooltip)
  kyubu.on("lifecycle.game_ready", setup)          -- the hooks go in at the menu, never at a cast
  kyubu.on("lifecycle.world_exit", forget)
end

M._tick, M._cast, M._keep_walk = tick, cast, keep_walk
M._state = function() return state, chains end   -- for the unit test

return M
end

-- @module skills_unleashed.lib.ability_channel (lib/ability_channel.lua)
package.preload["skills_unleashed.lib.ability_channel"] = function(...)
-- skills_unleashed.lib.ability_channel: what a joined client tells the server at an ability's clip marker.
-- One channel, `skills_unleashed:ability`, carries every such event as a table:
--   { kind = "cast" | "throw" | ..., run = n, seq = k, ... the event's own fields }
-- `run` is the client's count of its own starts of that ability (1, 2, ...), `seq` the event's number within that run (from 1).
-- The client says only what it aimed at (a spot, a charge, a direction); the server checks it against its own copy of the player and
-- its own run, and computes everything else. Nothing here decides whether an event is good: the ability's server module does.
--
-- The client sends only on a joined game (combat.is_joined): in single-player the client VM runs the ability itself and the local
-- server VM defines none. On Server.exe a joined player is connection `creature id + 1` (docs/sides-and-networking.md), so the
-- handler is given that player's id; a message from any other connection (the local client of a single-player game) is refused.
local M = {}

M.CHANNEL = "skills_unleashed:ability"

local handlers = {}               -- kind -> fn(player_id, event)
local served = false
local warned = {}
local runs = {}                   -- client side: kind -> the run number of the last start
local seqs = {}                   -- client side: kind -> the last seq sent in that run

local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  kyubu.warn("skills_unleashed: ability channel: " .. text)
end

-- ---- the client --------------------------------------------------------------------------------------------------------------

-- A new run of `kind`'s ability starts: its events count from 1 again. Returns the run number.
function M.new_run(kind)
  runs[kind] = (runs[kind] or 0) + 1
  seqs[kind] = 0
  return runs[kind]
end

-- Sends event `kind` with `fields` (a table, copied) to the server for the current run. Returns true, or false and why.
function M.send(kind, fields)
  local ch = kyubu.channel
  if not ch then return false, "this Kyubu has no channels" end
  if not runs[kind] then M.new_run(kind) end
  seqs[kind] = seqs[kind] + 1
  local msg = { kind = kind, run = runs[kind], seq = seqs[kind] }
  for k, v in pairs(fields or {}) do msg[k] = v end
  local ok, err = ch.send(M.CHANNEL, ch.SERVER, msg)
  if not ok then
    warn_once("send:" .. tostring(err), "an event was not sent: " .. tostring(err))
    return false, err
  end
  return true
end

-- ---- the server --------------------------------------------------------------------------------------------------------------

-- The player a connection stands for on Server.exe (connection = creature id + 1, players 1 to 10), or nil.
function M.player_of(conn)
  if type(conn) ~= "number" then return nil end
  local id = conn - 1
  if id < 1 or id > 10 or id ~= math.floor(id) then return nil end
  return id
end

local function on_message(conn, t)
  local id = M.player_of(conn)
  if not id then
    warn_once("conn:" .. tostring(conn), "an event from connection " .. tostring(conn) .. " was refused (not a joined player)")
    return
  end
  if type(t) ~= "table" or type(t.kind) ~= "string" or type(t.run) ~= "number" or type(t.seq) ~= "number" then
    kyubu.info(("skills_unleashed: server: an ability event from player %d was refused: malformed"):format(id))
    return
  end
  local fn = handlers[t.kind]
  if not fn then
    warn_once("kind:" .. t.kind, "an event of kind " .. t.kind .. " has no handler")
    return
  end
  fn(id, t)
end
M._on_message = on_message        -- for the unit test

-- Server side: `fn(player_id, event)` gets every well-formed event of `kind`. Registers the channel once.
function M.on(kind, fn)
  handlers[kind] = fn
  if served then return true end
  local ch = kyubu.channel
  if not ch then
    warn_once("none", "this Kyubu has no channels: no ability event is read")
    return false
  end
  local ok, err = ch.register(M.CHANNEL, function(conn, t)
    local fine, e = pcall(on_message, conn, t)
    if not fine then warn_once("msg:" .. tostring(e), "message error: " .. tostring(e)) end
  end)
  if not ok then
    warn_once("register", "the channel could not be registered: " .. tostring(err))
    return false
  end
  served = true
  return true
end

return M
end

-- @module skills_unleashed.lib.bow (lib/bow.lua)
package.preload["skills_unleashed.lib.bow"] = function(...)
-- skills_unleashed.lib.bow: the game's side of a bow the mod puts in the player's hand (the Sniper's Bow of Light): the weapon
-- swap, the charge on both mouse buttons, and the one straight arrow that goes through creatures. The facts are
-- on mapping/atlas/combat.md ("The bow's modes", "A straight arrow that goes through creatures"), creatures.md ("Equipment seen from
-- the game's loops") and saves.md (the save's copy).
--
--   the swap      the player's weapon item gets sub_type 6 (a bow) and a mark in minus_modifier: the bar, the HUD icons, the modes
--                 and the pose are then the game's own bow's. A save writes a copy of the player: at
--                 cube::GameController::saveCopiedSite that copy gets the real bytes back, so the bow is never saved.
--   the lock      every click that takes an equipped item out starts from cube::GameController::equipmentSlotUnderCursor: while
--                 the bow is in the hand it gives no weapon slot, so the bow cannot be taken out (to the bags, onto the cursor).
--                 A marked item found anywhere on the player after the bow is gone (the slots, the cursor, the bags) is put
--                 right by repair(): the safety net for a path nobody saw.
--   the look      a detour of ModelLoader::itemModel gives a marked item the mod's model.
--   the charge    cube::GameController::abilityBarBuiltSite copies the M1 key byte onto M2's, so both buttons hold the charge
--                 (mode 25); cube::GameController::bowReleaseSite turns the release (mode 55, four arrows) into mode 23 (one).
--                 The game's own sound of the charge (charge2.wav, queued every 200 ms of the hold with a pitch that rises with
--                 the charged mp) is queued at volume 0 at cube::World::chargeSoundSite: the ability plays its own.
--   the arrow     cube::World::bowShotSite: kind 1 (straight, no fall), no skill flag, the damage in XMM1, and the direction the
--                 ability gives it. The flight: projectileUpdateSite names the arrow, projectileStopSite clears the stop after a
--                 hit, a detour of cube::World::hitCreature lets it hit each creature once, projectileSurfaceSite ends it as an
--                 arrow. The draw: kind 0 for the length of its draw (turned along its flight), and at
--                 cube::GameController::projectileArrowModelSite the mod's model in place of the game's arrow.
--
-- Everything is hooked once, by install(), and stays: a hook written while the game runs stops every thread for a moment, which
-- would be a hitch at each cast. Nothing here detours a function that a worker thread calls: Lua that waits for one of the game's
-- locks keeps the Lua state from the main thread, which holds that lock (a detour of save_character froze the game).
-- A callback that fails is caught and logged once.
-- Not proved in the game: the lock (read statically), death with the bow in the hand, the charge's hush (read
-- statically), a joined client.
local ffi = require("ffi")
local units = require("skills_unleashed.lib.units")

local M = {}

-- cube::GameController
local GC_PLAYER = 0x8006D0
local GC_CAMERA = 0x140                                        -- camera_position: the camera's eye, three int64 in world units
local KEY_M1, KEY_M2 = 4, 5                                    -- the key bytes of the two mouse buttons
local BAR_CONTROLLER = 0x10                                    -- [ESP+0x10] at the bar site: the game controller
local SAVE_PLAYER = 0x0C                                       -- [EBP+0xC] at the save site: the player the copy was made of
-- cube::Creature (offsets already shifted by +0x10)
local C_ID, C_MODE = 0x08, 0x68
local C_CHARGED, C_SPENT = 0x144, 0x13B4
local SLOT_LEFT, SLOT_RIGHT, ITEM_SIZE = 0x990, 0xAA8, 0x118
-- the bags (cube::Inventory at +0x11DC: a vector of up to four vectors of slots, each a count then the item) and the item on the
-- mouse cursor (its count at +0x11E8, the item at +0x11EC): mapping/types/core.toml
local INV_TABS, HELD_COUNT, HELD_ITEM = 0x11DC, 0x11E8, 0x11EC
local TAB_SIZE, BAG_SLOT, BAG_ITEM = 0x0C, 0x11C, 0x04
local MAX_TABS, MAX_BAG_SLOTS = 8, 4096                        -- bounds against a vector that reads wrong
-- cube::ItemData
local I_TYPE, I_SUB, I_MARK, I_LEVEL = 0x00, 0x01, 0x08, 0x10  -- I_MARK is minus_modifier
local TYPE_WEAPON, SUB_BOW = 3, 6
local CUB_HEADER, WHITE = 12, string.char(255, 255, 255)      -- a .cub: three uint32 sizes, then one RGB triple per voxel
local EMPTY = string.char(0, 0, 0)
local MARK = 0x4C49                                            -- what a bow of the mod carries in minus_modifier
local MODE_CHARGE, MODE_SHOT = 25, 23                          -- a bow's held charge; the one-arrow shot
-- cube::Projectile
local PR_OWNER, PR_POS, PR_VEL, PR_SKILL, PR_KIND, PR_AGE = 0x00, 0x18, 0x3C, 0x5C, 0x60, 0x68
local KIND_ARROW, KIND_STRAIGHT = 0, 1
local SHOT_CREATURE, SHOT_PROJECTILE = 0x2B14, 0x578           -- below EBP at the shot site
local STOP_FLAG = 0x2B58                                       -- below EBP at the stop site
-- the game's sound of the charge: a sound action (the position, the sound id at +0xC, pitch +0x10, volume +0x14)
local CHARGE_SOUND, SOUND_VOLUME = 0x740, 0x14                 -- below EBP at the charge sound's site; its volume

M.MARK = MARK
M.offsets = { mode = C_MODE, charged = C_CHARGED, spent = C_SPENT, slot_left = SLOT_LEFT, slot_right = SLOT_RIGHT, item_size = ITEM_SIZE, item_mark = I_MARK,
  item_level = I_LEVEL, gc_player = GC_PLAYER, gc_camera = GC_CAMERA, save_player = SAVE_PLAYER, proj_pos = PR_POS,
  proj_vel = PR_VEL, proj_skill = PR_SKILL, proj_kind = PR_KIND, proj_age = PR_AGE, shot_creature = SHOT_CREATURE,
  shot_projectile = SHOT_PROJECTILE, stop_flag = STOP_FLAG, inv_tabs = INV_TABS, held_count = HELD_COUNT, held_item = HELD_ITEM,
  bag_slot = BAG_SLOT, bag_item = BAG_ITEM, charge_sound = CHARGE_SOUND, sound_volume = SOUND_VOLUME }
M.MODE_CHARGE, M.MODE_SHOT = MODE_CHARGE, MODE_SHOT

local function u8(a) return ffi.cast("uint8_t*", a)[0] end
local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function f32(a) return ffi.cast("float*", a)[0] end
local function i64(a) return tonumber(ffi.cast("int64_t*", a)[0]) end
local function put_u8(a, v) ffi.cast("uint8_t*", a)[0] = v end
local function put_i32(a, v) ffi.cast("int32_t*", a)[0] = v end
local function put_f32(a, v) ffi.cast("float*", a)[0] = v end

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: bow: " .. text) end
end

local function guarded(name, fn)
  return function(ctx)
    local ok, e = pcall(fn, ctx)
    if not ok then warn_once("run:" .. name .. tostring(e), name .. ": " .. tostring(e)) end
  end
end

local function controller()
  local at = kyubu.symbol("cube::game_controller")
  return at and u32(at) or 0
end

local function local_player()
  local gc = controller()
  return gc ~= 0 and u32(gc + GC_PLAYER) or 0
end
M.local_player = local_player

-- The camera's eye in blocks (x, y, z), or nil outside a game. The crosshair's ray runs from it through the player's aim.
function M.camera()
  local gc = controller()
  if gc == 0 then return nil end
  return units.to_blocks(i64(gc + GC_CAMERA)), units.to_blocks(i64(gc + GC_CAMERA + 8)), units.to_blocks(i64(gc + GC_CAMERA + 16))
end

-- ---- what the creature is doing ------------------------------------------------------------------------------------------

function M.mode(c) return u8(c + C_MODE) end
function M.is_charging(c) return u8(c + C_MODE) == MODE_CHARGE end
function M.is_shooting(c) return u8(c + C_MODE) == MODE_SHOT end
-- The mp gathered by the held charge (0 to 1, at most the creature's mp).
function M.charged(c) return f32(c + C_CHARGED) end

-- ---- the swap ------------------------------------------------------------------------------------------------------------

local handlers = nil            -- what install() was given
local site_ok = {}              -- the sites install() put a hook on, by name
local swap = nil                -- { player =, at = the item's address, sub =, mark =, whole = the 0x118 bytes of an empty slot or nil }
local last_swap = nil           -- the last swap made: a save's copy that still carries the mark is put right from it
local model_id, model_slot = nil, nil
local get_model = nil           -- ModelLoader::get(this, slot) -> Model*, thiscall
local loader = nil              -- the ModelLoader, as the game hands it to its own itemModel
local item_hook = nil
local SAVE_SITE = "cube::GameController::saveCopiedSite"

-- The model a marked item is drawn with: the id given to kyubu.model.add. Its table slot is read when it is first needed, and
-- again in each world (a world's id map renumbers the slots when it is entered).
function M.set_bow_model(id) model_id = id; model_slot = nil end

local function bow_slot()
  if model_slot == nil and model_id and kyubu.model and kyubu.model.slot then model_slot = kyubu.model.slot(model_id) end
  return model_slot
end

local function is_marked(at)
  return u8(at + I_TYPE) == TYPE_WEAPON and u8(at + I_SUB) == SUB_BOW and i32(at + I_MARK) == MARK
end
M.is_marked = is_marked

-- Makes the item at `at` a bow of the mod: an item that is a weapon keeps everything but its sub_type and the mark; an empty
-- slot becomes a level 1 bow.
local function mark(at, was_weapon)
  if not was_weapon then
    ffi.fill(ffi.cast("void*", at), ITEM_SIZE)
    put_u8(at + I_TYPE, TYPE_WEAPON)
    put_i32(at + I_LEVEL, 1)
  end
  put_u8(at + I_SUB, SUB_BOW)
  put_i32(at + I_MARK, MARK)
end

-- Writes the item swap `s` replaced back at `at`: the player's own slot, or the same slot of a copy of the player.
local function unmark(at, s)
  if s.whole then
    ffi.copy(ffi.cast("void*", at), s.whole, ITEM_SIZE)
  else
    put_u8(at + I_SUB, s.sub)
    put_i32(at + I_MARK, s.mark)
  end
end

local function on_item_model(next, this, item)
  loader = this
  local a = tonumber(ffi.cast("uint32_t", item))
  if a ~= 0 and get_model and u8(a + I_TYPE) == TYPE_WEAPON and i32(a + I_MARK) == MARK then
    local slot = bow_slot()
    if slot then return get_model(this, slot) end
  end
  return next(this, item)
end
M._on_item_model = on_item_model                -- for the unit test

-- cube::GameController::saveCopiedSite: the game has copied the player (EBX) and is about to write the copy. A copy that carries
-- the mark gets the real item, so the save never holds the bow; the player in the game is not touched. The save itself is not
-- detoured: the autosave runs on a worker thread and takes the World's lock (see the head of this file).
local function on_save_copy(ctx)
  local s = swap or last_swap
  local copy = ctx.ebx
  if not s or copy == 0 then return end
  if swap and u32(ctx.ebp + SAVE_PLAYER) ~= s.player then return end
  local at = copy + (s.at - s.player)
  if is_marked(at) then unmark(at, s) end
end

-- A marked item (the bow in the hand) is drawn with the mod's model. Returns true when it is.
function M.look_on()
  if item_hook then return true end
  local g = kyubu.symbol("ModelLoader::get")
  if not g then
    warn_once("get-symbol", "ModelLoader::get has no symbol: the bow and the arrow have the game's look")
    return false
  end
  get_model = ffi.cast("void*(__thiscall*)(void*, int32_t)", g)
  local id, err = kyubu.hook("ModelLoader::itemModel", "void*(__thiscall*)(void*, void*)", on_item_model)
  if id then item_hook = id else warn_once("item", "ModelLoader::itemModel: the hook failed (" .. tostring(err) .. "): the bow has the game's look") end
  return item_hook ~= nil
end

-- Puts the bow in the player's hand: the right weapon when there is one, else the left, else a new item in the right slot.
-- Returns true, or false and the reason (without the save's site nothing is swapped: a save would keep the bow).
function M.swap_on(player)
  if swap then return swap.player == player end
  if not site_ok[SAVE_SITE] then return false, "no save guard" end
  local at = player + SLOT_RIGHT
  local was_weapon = u8(at + I_TYPE) == TYPE_WEAPON
  if not was_weapon and u8(player + SLOT_LEFT + I_TYPE) == TYPE_WEAPON then
    at = player + SLOT_LEFT
    was_weapon = true
  end
  local s = { player = player, at = at, sub = u8(at + I_SUB), mark = i32(at + I_MARK) }
  if not was_weapon then
    s.whole = ffi.new("uint8_t[?]", ITEM_SIZE)
    ffi.copy(s.whole, ffi.cast("void*", at), ITEM_SIZE)
  end
  mark(at, was_weapon)
  swap, last_swap = s, s
  return true
end

-- Calls fn(item, count) for every item creature `c` carries outside its equipment: the one on the mouse cursor and those in its
-- bags (`count` is the address of the slot's count word). Vectors that read wrong are skipped.
local function each_carried(c, fn)
  fn(c + HELD_ITEM, c + HELD_COUNT)
  local first, last = u32(c + INV_TABS), u32(c + INV_TABS + 4)
  if first == 0 or last < first or (last - first) % TAB_SIZE ~= 0 or (last - first) / TAB_SIZE > MAX_TABS then return end
  for tab = first, last - TAB_SIZE, TAB_SIZE do
    local s0, s1 = u32(tab), u32(tab + 4)
    if s0 ~= 0 and s1 >= s0 and (s1 - s0) % BAG_SLOT == 0 and (s1 - s0) / BAG_SLOT <= MAX_BAG_SLOTS then
      for slot = s0, s1 - BAG_SLOT, BAG_SLOT do fn(slot + BAG_ITEM, slot) end
    end
  end
end

-- Puts right every item of creature `c` that carries the mark, from what swap `s` replaced: its two weapon slots, the cursor and
-- the bags. A bow that was made from an empty hand is taken away (its slot emptied). Returns the places put right ("right",
-- "left", "cursor", "bag"), in that order.
local function repair_marked(c, s)
  local fixed = {}
  local function fix(at, count, where)
    if not is_marked(at) then return end
    unmark(at, s)
    if s.whole and count then put_i32(count, 0) end
    fixed[#fixed + 1] = where
  end
  fix(c + SLOT_RIGHT, nil, "right")
  fix(c + SLOT_LEFT, nil, "left")
  each_carried(c, function(at, count) fix(at, count, count == c + HELD_COUNT and "cursor" or "bag") end)
  return fixed
end

-- Puts the player's own weapon back. A bow that left its slot after all (the lock below keeps the clicks off it) is put right
-- where it is now. When it is nowhere, the item was replaced by other means: nothing is written and false is returned.
-- `player` must be the creature the swap was made on, and alive in memory.
function M.swap_off(player)
  local s = swap
  swap = nil
  if not s then return true end
  if s.player ~= player then return false, "another creature" end
  if is_marked(s.at) then
    unmark(s.at, s)
    return true
  end
  local fixed = repair_marked(player, s)
  if #fixed > 0 then
    warn_once("left", "the bow of light had left its slot: put right in " .. table.concat(fixed, ", "))
    return true
  end
  warn_once("moved", "the bow of light was moved out of its slot while it was held, and is not on the player any more")
  return false, "moved"
end

-- The safety net once the bow is gone: a marked item still on creature `c` (the slots, the cursor, the bags) is put right from the
-- last swap. Returns the places put right, an empty list when there was nothing (or no swap was ever made, or one is on).
function M.repair(c)
  if swap or not last_swap or not c or c == 0 then return {} end
  return repair_marked(c, last_swap)
end

-- cube::GameController::equipmentSlotUnderCursor: the slot under the mouse, where every click that takes an equipped item out
-- starts (a right click sends it to the bags, a left click swaps it with the cursor's item, a left click on the left hand bags a
-- two-handed right weapon). While the bow is in the hand neither weapon slot is under the mouse for the game, so those clicks do
-- nothing there and the bow cannot leave the hand. The hover box of the two slots is gone for that time as well.
local function on_slot_under_cursor(next, this)
  local slot = next(this)
  local s = swap
  if s and slot ~= nil then
    local a = tonumber(ffi.cast("uint32_t", slot))
    if a == s.player + SLOT_RIGHT or a == s.player + SLOT_LEFT then return nil end
  end
  return slot
end
M._on_slot_under_cursor = on_slot_under_cursor  -- for the unit test

function M.is_swapped() return swap ~= nil end

-- Drops the swap without a write: the world was left, the creature's memory is no longer the mod's to touch. What the swap
-- replaced is kept for the save that the game makes on the way out.
function M.forget()
  swap = nil
  model_slot = nil
  M._flight_reset()
end

-- ---- the white models ---------------------------------------------------------------------------------------------------

-- A .cub model with every voxel pure white (an empty one stays empty), or nil when `cub` is not a model.
function M.white_copy(cub)
  if type(cub) ~= "string" or #cub <= CUB_HEADER or (#cub - CUB_HEADER) % #WHITE ~= 0 then return nil end
  local body = cub:sub(CUB_HEADER + 1):gsub("...", function(v)
    if v == EMPTY then return v end
    return WHITE
  end)
  return cub:sub(1, CUB_HEADER) .. body
end

-- Serves the model key `key` (the file name given to kyubu.model.add) as a white copy of the first of the game's own models
-- `sources` that can be read. Call it in lifecycle.preinit: the game loads its models right after. Returns true when the
-- provider is in place.
function M.provide_white(key, sources)
  if not (kyubu.assets and kyubu.assets.provider and kyubu.assets.read) then
    warn_once("assets", "this Kyubu has no asset providers: the arrow has the game's look")
    return false
  end
  local ok, id, err = pcall(kyubu.assets.provider, "data1.db", key, function()
    for _, name in ipairs(sources) do
      local rok, data = pcall(kyubu.assets.read, "data1.db", name)
      local white = rok and M.white_copy(data) or nil
      if white then return white end
    end
    warn_once("source:" .. key, key .. ": none of the game's models could be read: the placeholder is drawn")
    return nil
  end)
  if not ok or not id then
    warn_once("provider:" .. key, key .. ": no provider (" .. tostring(ok and err or id) .. ")")
    return false
  end
  return true
end

-- ---- the charge's sound -------------------------------------------------------------------------------------------------

-- cube::World::chargeSoundSite: the game queues its charge sound (charge2.wav, pitch 1 + 0.5 * charged mp) for a creature that
-- holds a charge, once in each 200 ms of the hold. For the player who may charge the bow of the mod it is queued at volume 0:
-- the ability's own sound follows the charge instead (otherwise both are heard at once). Every other creature's is the game's.
local function on_charge_sound(ctx)
  local c = ctx.esi
  if c == 0 or not handlers.armed(c) then return end
  put_f32(ctx.ebp - CHARGE_SOUND + SOUND_VOLUME, 0)
end

-- ---- the arrow -----------------------------------------------------------------------------------------------------------

local arrow = nil               -- the arrow in flight: { hit = { [creature id] = true }, age =, ms =, ended = }
local current = nil             -- the address of the arrow while the World's loop is on it
local drawn = nil               -- the arrow whose draw is on (its kind is 0 for it)
local arrow_model_id, arrow_slot = nil, nil
local released = 0              -- the charge read at the release

function M.set_arrow_model(id) arrow_model_id = id; arrow_slot = nil end

local function arrow_model()
  if arrow_slot == nil and arrow_model_id and kyubu.model and kyubu.model.slot then arrow_slot = kyubu.model.slot(arrow_model_id) end
  return arrow_slot
end

local function is_ours(proj)
  if not arrow or i32(proj + PR_KIND) ~= KIND_STRAIGHT or u8(proj + PR_SKILL) ~= 0 then return false end
  local p = local_player()
  return p ~= 0 and i64(proj + PR_OWNER) == i64(p + C_ID)
end

local function proj_pos(proj)
  return units.to_blocks(i64(proj + PR_POS)), units.to_blocks(i64(proj + PR_POS + 8)), units.to_blocks(i64(proj + PR_POS + 16))
end

local function end_draw()
  if drawn then
    put_i32(drawn + PR_KIND, KIND_STRAIGHT)
    drawn = nil
  end
end

function M._flight_reset()
  arrow, current, drawn, released = nil, nil, nil, 0
  arrow_slot = nil
end

local function on_bar(ctx)
  local gc = u32(ctx.esp + BAR_CONTROLLER)
  if gc == 0 then return end
  local p = u32(gc + GC_PLAYER)
  if p == 0 or not handlers.armed(p) then return end
  local keys = ffi.cast("uint8_t*", gc)
  if keys[KEY_M1] ~= 0 and keys[KEY_M2] == 0 then keys[KEY_M2] = 1 end
end

local function on_release(ctx)
  local p = ctx.eax
  if p == 0 or not handlers.armed(p) then return end
  released = f32(p + C_CHARGED)
  put_u8(p + C_MODE, MODE_SHOT)
end

-- cube::World::bowShotSite: the game's arrow, complete and not yet in the World's list, becomes the mod's. The game aims it from
-- the shooter's own position at the aimed point, which sends it off at any angle when that point is near: the ability gives the
-- direction (a unit vector) instead, and the speed stays.
local function on_shot(ctx)
  local frame = ctx.ebp
  local creature = u32(frame - SHOT_CREATURE)
  if creature == 0 or u8(creature + C_MODE) ~= MODE_SHOT or not handlers.armed(creature) then return end
  local proj = frame - SHOT_PROJECTILE
  local charge = math.max(released, f32(creature + C_CHARGED), f32(creature + C_SPENT))
  released = 0
  local damage, speed, dx, dy, dz = handlers.on_arrow(creature, charge, proj_pos(proj))
  if not damage then return end
  put_i32(proj + PR_KIND, KIND_STRAIGHT)
  put_u8(proj + PR_SKILL, 0)
  local vx, vy, vz = f32(proj + PR_VEL), f32(proj + PR_VEL + 4), f32(proj + PR_VEL + 8)
  local pace = math.sqrt(vx * vx + vy * vy + vz * vz) * (speed or 1)
  if dx and pace > 0 then
    put_f32(proj + PR_VEL, dx * pace); put_f32(proj + PR_VEL + 4, dy * pace); put_f32(proj + PR_VEL + 8, dz * pace)
  elseif speed and speed ~= 1 then
    put_f32(proj + PR_VEL, vx * speed); put_f32(proj + PR_VEL + 4, vy * speed); put_f32(proj + PR_VEL + 8, vz * speed)
  end
  ctx.xmm[1].f32[0] = damage
  arrow = { hit = {}, age = -1, ms = 0, ended = false }
end

local function on_update(ctx)
  local proj = ctx.edi
  current = nil
  if proj == 0 or not is_ours(proj) or arrow.ended then return end
  current = proj
  arrow.age = i32(proj + PR_AGE)
  if handlers.on_flight then handlers.on_flight(proj_pos(proj)) end
end

local function on_stop(ctx)
  if current and ctx.edi == current then put_u8(ctx.ebp - STOP_FLAG, 0) end
end

local function on_surface(ctx)
  if not current or ctx.edi ~= current then return end
  put_i32(current + PR_KIND, KIND_ARROW)         -- the game ends it as its own arrow: a puff, no explosion, removal
  local x, y, z = proj_pos(current)
  current = nil
  if arrow then arrow.ended = true end
  if handlers.on_surface then handlers.on_surface(x, y, z) end
end

-- hitCreature takes 14 stack words: the target is the first, the projectile the 13th. A creature the arrow has hit is skipped.
-- Where `handlers.server_hits(world)` says the server makes the arrow's hits (a joined client),
-- the arrow makes none here: the call is skipped, so no hit goes to the server, and it is logged.
local function on_hit_creature(next, this, target, attacker, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, proj, a14)
  if current and arrow and proj == current and target ~= 0 then
    local id = i64(target + C_ID)
    if arrow.hit[id] then return 0 end
    arrow.hit[id] = true
    if handlers.server_hits and handlers.server_hits(tonumber(ffi.cast("uint32_t", this))) then
      kyubu.info(("skills_unleashed: bow: the arrow reached creature %d: no hit here (the server makes it)"):format(id))
      return 0
    end
  end
  return next(this, target, attacker, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, proj, a14)
end
M._on_hit_creature = on_hit_creature            -- for the unit test

local function on_draw_kind(ctx)
  end_draw()                                     -- a draw whose end was not seen
