  float pixel_size;
} EmShockwaveDef;
typedef struct EmShockwaveApi {
  uint32_t size, version;
  uint32_t (*spawn)(const EmShockwaveDef*);
  int (*cancel)(uint32_t);
  uint32_t (*count)(void);
  void (*clear)(void);
} EmShockwaveApi;
typedef struct EmParticleDef {
  uint32_t size; uint32_t type;
  int64_t pos[3];
