-- ---- steering the game's own particles -----------------------------------------------------------------------------------
-- What the game does with a particle record (read from cube::GameController::update): each of its `count` cubes
-- becomes a particle in the std::list at GameController+0x800740 with the record's `accel` as its starting VELOCITY (blocks a
-- second) plus a random one of `spreading`; it then moves at that velocity (types other than 4 also fall at 30 blocks a second
-- squared, type 3 does not move) and is removed when its age passes its life, which the game's constructor sets to 4000 ms. A
-- record cannot say "come here and stop", so a mod that wants that writes the live particles: a rule names its particles by their
-- exact scale (a float no other effect uses) and gives them a shorter life, or a point to fly to at a speed, where they end.
-- The game draws a particle as a cube of its scale's side and nothing else changes with its age (the draw loop at 0x4B7DB3 reads
-- +0xAC each frame), so a rule may also shrink its particles as they come in: it then names them by a few exact
-- scales, one a step of the shrink. EMTweaks has no call for this yet; it belongs there, and this is the same list its particles
-- are in.
local GC_PARTICLES = 0x800740
local PT_TYPE, PT_AGE, PT_POS, PT_VEL, PT_SCALE, PT_LIFE = 0x00, 0x04, 0x08, 0x54, 0xAC, 0xB4
local NODE_VALUE = 8
local MAX_PARTICLES = 6000                 -- the game keeps 5000 at most: a guard against a corrupt list
local BLOCK = 65536
local DEFAULT_STEP_MS, MS_PER_S = 20, 1000      -- the World's step, when the caller does not say

M.particle_offsets = { list = GC_PARTICLES, type = PT_TYPE, age = PT_AGE, pos = PT_POS, vel = PT_VEL, scale = PT_SCALE, life = PT_LIFE }

local rules = {}                            -- name -> { scale = float, life_ms =, target = {x, y, z} blocks, line =, half =,
                                            --          speed =, reach =, fade =, levels = }
local rule_count = 0
local tags = {}                             -- a particle's exact scale -> { rule =, level = (nil: a rule that does not shrink) }
local one_float = ffi.new("float[1]")

local function as_float(v)
  one_float[0] = v
  return one_float[0]
end

local function retag()
  tags = {}
  for _, r in pairs(rules) do
    if r.level_tags then
      for k, tag in ipairs(r.level_tags) do tags[tag] = { rule = r, level = k } end
    else
      tags[r.tag] = { rule = r }
    end
  end
end

-- Sets (or, with nil, removes) the rule `name`. def: scale (the particles' exact scale), and life_ms (their whole life) and/or
-- target {x, y, z} in blocks with speed (blocks a second) and reach (blocks: a particle this near the target ends). With line
-- {x, y, z} (a unit vector) and half (blocks), the target is a segment through `target`, half long each way along `line`, and
-- each particle flies to its own nearest point of it: particles above the segment come straight down onto it. With fade (blocks)
-- and levels (2 or more), a particle nearer its target than `fade` shrinks in `levels` steps, in proportion to what is left of
-- the way, never growing back: scale * k / levels for the k-th step, the full scale the last. With drag (a share a second, no
-- target needed) each particle's velocity is multiplied by e^(-drag * dt) at every steer(dt_ms): it slows down.
-- Smoke (no target needed): with life_jitter (0 to 1) a particle's life is cut to life_ms times 1 less up to that share, at random,
-- so a puff does not vanish all at once; with shrink = true and levels (2 or more) a particle shrinks with its age, in proportion
-- to what is left of its life (the game draws a particle as a cube of its scale and nothing else fades it); with rise (blocks a
-- second squared) it is pushed up at every steer, so with drag it rises at rise / drag at most.
function M.rule(name, def)
  if rules[name] == nil and def ~= nil then rule_count = rule_count + 1 end
  if rules[name] ~= nil and def == nil then rule_count = rule_count - 1 end
  if def then
    def.tag = as_float(def.scale)
    if (def.fade or def.shrink) and def.levels and def.levels >= 2 then
      def.level_tags = {}
      for k = 1, def.levels do def.level_tags[k] = as_float(def.scale * k / def.levels) end
    end
  end
  rules[name] = def
  retag()
end

function M.has_rules() return rule_count > 0 end
function M.clear_rules() rules, rule_count, tags = {}, 0, {} end

-- Applies the rules to the live particles once. Returns how many particles a rule touched. Call it from the game's thread.
function M.steer(dt_ms)
  if rule_count == 0 or not (kyubu and kyubu.symbol) then return 0 end
  local dt_s = (dt_ms or DEFAULT_STEP_MS) / MS_PER_S
  local at = kyubu.symbol("cube::game_controller")
  local gc = at and ffi.cast("uint32_t*", at)[0] or 0
  if gc == 0 then return 0 end
  local head = ffi.cast("uint32_t*", gc + GC_PARTICLES)[0]
  if head == 0 then return 0 end
  local node, n, touched = ffi.cast("uint32_t*", head)[0], 0, 0
  while node ~= head and node ~= 0 and n < MAX_PARTICLES do
    local p = node + NODE_VALUE
    local scale_at = ffi.cast("float*", p + PT_SCALE)
    local hit = tags[scale_at[0]]
    if hit then
      local r = hit.rule
      touched = touched + 1
      local life = ffi.cast("int32_t*", p + PT_LIFE)
      if r.life_ms and life[0] > r.life_ms then
        local l = r.life_ms
        if r.life_jitter then l = l * (1 - r.life_jitter * math.random()) end
        life[0] = math.floor(l)
      end
      if r.shrink and hit.level and life[0] > 0 then
        local left = 1 - ffi.cast("int32_t*", p + PT_AGE)[0] / life[0]
        local want = math.ceil(r.levels * left)
        if want < 1 then want = 1 end
        if want < hit.level then scale_at[0] = r.level_tags[want] end
      end
      local t = r.target
      if t then
        local pos = ffi.cast("int64_t*", p + PT_POS)
        local px, py, pz = tonumber(pos[0]) / BLOCK, tonumber(pos[1]) / BLOCK, tonumber(pos[2]) / BLOCK
        local tx, ty, tz = t[1], t[2], t[3]
        local l = r.line
        if l then
          local along = (px - tx) * l[1] + (py - ty) * l[2] + (pz - tz) * l[3]
          local half = r.half or 0
          if along > half then along = half elseif along < -half then along = -half end
          tx, ty, tz = tx + l[1] * along, ty + l[2] * along, tz + l[3] * along
        end
        local dx, dy, dz = tx - px, ty - py, tz - pz
        local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
        local vel = ffi.cast("float*", p + PT_VEL)
        if dist <= r.reach then
          life[0] = 0                       -- it has arrived: the game removes it at its next update
          vel[0], vel[1], vel[2] = 0, 0, 0
        else
          local k = r.speed / dist
          vel[0], vel[1], vel[2] = dx * k, dy * k, dz * k
          if hit.level and dist < r.fade then
            local want = math.ceil(r.levels * dist / r.fade)
            if want < 1 then want = 1 end
            if want < hit.level then scale_at[0] = r.level_tags[want] end
          end
        end
      end
      if r.drag then                        -- no target: the particle slows down, e to the minus drag a second
        local vel = ffi.cast("float*", p + PT_VEL)
        local k = math.exp(-r.drag * dt_s)
        vel[0], vel[1], vel[2] = vel[0] * k, vel[1] * k, vel[2] * k
      end
      if r.rise then                        -- smoke: pushed up
        local vel = ffi.cast("float*", p + PT_VEL)
        vel[2] = vel[2] + r.rise * dt_s
      end
    end
    node = ffi.cast("uint32_t*", node)[0]
    n = n + 1
  end
  return touched
end

-- `count` single particles at rest at random points of a flat rectangle centred on `centre` {x, y, z} (blocks): `length` blocks
-- along `across` (a unit vector {x, y} on the ground plane) and `depth` blocks along the ground direction square to it. With a
-- rule that has the same scale and a target they fly to it. def: type, scale, color.
function M.rect(def, centre, across, count, length, depth)
  local api = interface(PARTICLES, "EmParticleApi*")
  if not api then return 0 end
  local d = ffi.new("EmParticleDef")
  local made = 0
  for _ = 1, count do
    local u, v = (math.random() - 0.5) * length, (math.random() - 0.5) * depth
    fill_particle(d, { type = def.type, count = 1, scale = def.scale, spreading = 0, color = def.color },
      { (centre[1] + across[1] * u - across[2] * v) * BLOCK, (centre[2] + across[2] * u + across[1] * v) * BLOCK, centre[3] * BLOCK })
    if api.spawn(d) == 1 then made = made + 1 end
  end
  return made
end

-- `count` single particles at rest on a sphere round `centre` {x, y, z} (blocks), each at its own distance between radius_min and
-- radius_max: with a rule that has the same scale and a target they fly in to it. def: type, scale, color.
function M.sphere(def, centre, count, radius_min, radius_max)
  local api = interface(PARTICLES, "EmParticleApi*")
  if not api then return 0 end
  local d = ffi.new("EmParticleDef")
  local made = 0
  for _ = 1, count do
    local z = math.random() * 2 - 1
    local a = math.random() * 2 * math.pi
    local flat = math.sqrt(1 - z * z)
    local r = radius_min + (radius_max - radius_min) * math.random()
    fill_particle(d, { type = def.type, count = 1, scale = def.scale, spreading = 0, color = def.color },
      { (centre[1] + flat * math.cos(a) * r) * BLOCK, (centre[2] + flat * math.sin(a) * r) * BLOCK, (centre[3] + z * r) * BLOCK })
    if api.spawn(d) == 1 then made = made + 1 end
  end
  return made
end

-- `count` single particles at random points of an upright cylinder: within `radius` blocks of the axis through `centre` {x, y, z}
-- (blocks) and from its z up to `height` blocks higher. Each starts at def.accel (blocks a second) plus `out` blocks a second away
-- from the axis, and the game's random `spreading` (def.spreading, 0 when not given) on top. def: type, scale, color, accel.
-- Returns how many were made.
function M.scatter(def, centre, count, radius, height, out)
  local api = interface(PARTICLES, "EmParticleApi*")
  if not api then return 0 end
  local d = ffi.new("EmParticleDef")
  local acc = def.accel or { 0, 0, 0 }
  local one = { type = def.type, count = 1, scale = def.scale, spreading = def.spreading or 0, color = def.color, accel = { 0, 0, 0 } }
  local made = 0
  for _ = 1, count do
    local a = math.random() * 2 * math.pi
    local r = (radius or 0) * math.sqrt(math.random())
    local ca, sa = math.cos(a), math.sin(a)
    local push = out or 0
    one.accel[1], one.accel[2], one.accel[3] = acc[1] + ca * push, acc[2] + sa * push, acc[3]
    fill_particle(d, one, { (centre[1] + ca * r) * BLOCK, (centre[2] + sa * r) * BLOCK, (centre[3] + (height or 0) * math.random()) * BLOCK })
    if api.spawn(d) == 1 then made = made + 1 end
  end
  return made
end

local function full_name(name)
  if name:find(".", 1, true) then return name end
  return M.PREFIX .. "." .. name
end

-- Keeps `def` (as burst takes it, without a position) under "skills_unleashed.<name>" for the session.
function M.define_preset(name, def)
  local api = interface(PARTICLES, "EmParticleApi*")
  if not api then return false end
  local d = ffi.new("EmParticleDef")
  fill_particle(d, def, nil)
  return api.define_preset(M.PREFIX .. "." .. name, d) == 1
end

-- Plays a preset at `pos` (world units). `color` {r,g,b,a} replaces the preset's, `scale_mul` multiplies its scale.
function M.preset(name, pos, color, scale_mul)
  local api = interface(PARTICLES, "EmParticleApi*")
  if not api then return false end
  local p = ffi.new("int64_t[3]", pos[1], pos[2], pos[3])
  local col = nil
  if color then col = ffi.new("float[4]", color[1], color[2], color[3], color[4] or 1) end
  return api.spawn_preset(full_name(name), p, col, scale_mul or 1) == 1
end

return M
end

-- @module skills_unleashed.lib.glow (lib/glow.lua)
package.preload["skills_unleashed.lib.glow"] = function(...)
-- skills_unleashed.lib.glow: point lights at a place (the Fire Mage's circle and hands, the Sniper's bow and player), through the
-- loader's light API. No lamp is lit on a creature: a light is only ever a point light of the API.
--
--   glow.light_set(key, light)  a point light at a place (see below); nil clears it
--   glow.light_clear(key)       ends it
--   glow.lights_forget()        ends every light of the module (the world was left)
local M = {}

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: glow: " .. text) end
end

-- ---- lights at a place ------------------------------------------------------------------------------------------------------
-- Point lights through the loader (kyubu.game.light_spawn, light_set, light_remove; docs/game-api.md): the loader pushes them into
-- the frame's light vector before the render sorts it and hands it to the terrain and the models, so they light the ground too.
-- (See probe light-place for why a mod's own mid hook is not enough.) A light is { x, y, z (blocks), radius, r, g, b };
-- the key is any value. A light that cannot be had (the primitive unavailable, 16 alive) is said once in the log and skipped.
local UNITS = 65536
local ids = {}                                   -- key -> the loader's id

local function spec(l)
  return { pos = { math.floor(l.x * UNITS + 0.5), math.floor(l.y * UNITS + 0.5), math.floor(l.z * UNITS + 0.5) },
    radius = l.radius, color = { l.r, l.g, l.b } }
end

local function game() return kyubu and kyubu.game end

-- Sets (or moves) the light `key`; nil clears it.
function M.light_set(key, l)
  if not l then return M.light_clear(key) end
  local g = game()
  if not (g and g.light_spawn) then
    warn_once("api", "kyubu.game.light_spawn is missing (a loader older than the light API): no light at a place")
    return
  end
  local id = ids[key]
  if id then
    local ok = g.light_set(id, spec(l))
    if ok then return end
    ids[key] = nil                               -- it ended (the world was left): start it again
  end
  local new, why = g.light_spawn(spec(l))
  if new then ids[key] = new else warn_once("spawn:" .. tostring(why), "no light at a place: " .. tostring(why)) end
end

function M.light_clear(key)
  local id = ids[key]
  if not id then return end
  ids[key] = nil
  local g = game()
  if g and g.light_remove then g.light_remove(id) end
end

-- Ends every light of the module (the world was left: the loader has ended them already).
function M.lights_forget()
  local g = game()
  for _, id in pairs(ids) do
    if g and g.light_remove then g.light_remove(id) end
  end
  ids = {}
end

return M
end

-- @module skills_unleashed.lib.grip (lib/grip.lua)
package.preload["skills_unleashed.lib.grip"] = function(...)
-- skills_unleashed.lib.grip: where the game draws a bow in a creature's right hand (hand B), so that a drawing of the mod (the
-- Sniper's materializing bow, an EMTweaks ghost) can sit exactly there before the real bow is in the hand.
--
-- What the game does (read from draw_creature, 0x4129C0; static, checked in play by `check` below): after a draw the
-- creature's draw record holds a 4x4 matrix per part (the creatures atlas, "Posing"), in Direct3D's row-vector form: row c is the
-- image of the model's axis c and row 4 the translation, in render space (blocks; x and y moved by the game controller's origin).
-- With column vectors and the helpers post-multiplied, the two that matter here are
--   hand B (slot 10)          Trunk * T(p) * R * S(-h, h, h) * T(-hand_size / 2)
--   its weapon (slot 7)       Trunk * T(p) * R * Rx(look_pitch / 2) * S(w) * T(grip)
-- where p and R are hand B's position and angles, h and w the creature's hand and weapon scales (its appearance) and, for a bow
-- (sub_type 6), grip = (-sx / 2, 1.5 - sy, -sz / 2) in the bow model's voxels. So the bow is a fixed turn and shift of the hand: from
-- the hand's last drawn matrix, its model and the creature's numbers, the bow's place follows, for any race, pose and camera pitch.
-- Hand B is drawn mirrored on x; the S(-1/h, 1/h, 1/h) that takes the hand back to R cancels the mirror.
local ffi = require("ffi")

local M = {}

local RECORD = 0x1498                 -- cube::Creature: the draw record; its first word is the creature itself
local REC_MATRICES, MATRIX_BYTES = 0xEC, 0x40
local SLOT_ROOT, SLOT_WEAPON_B, SLOT_HAND_B = 0, 7, 10
local REC_HANDS, REC_WEAPON_B = 0xCC, 0xDC   -- the record's Model* of the hands and of hand B's weapon
local MODEL_SIZE = 0x44               -- Model: the size in voxels, three int32 (x, y, z)
local C_LOOK_PITCH = 0x58             -- cube::Creature, degrees
local C_HAND_SCALE, C_WEAPON_SCALE = 0xA4, 0xB0   -- the appearance's hand_scale and weapon_scale (0x68 + 0x2C, + 0x38, +0x10)
local GC_ORIGIN = 0x1D8               -- GameController: two int64 (x, y, world units) a position gets added for render space
local GRIP_TOP = 1.5                  -- a bow's hand is this many voxels in from the model's +y face (middle of x and z)
local PITCH_SHARE = 0.5               -- the weapon turns about the hand's x by this share of the look pitch
local GIMBAL = 1e-3                   -- below this the model's y is taken as straight up or down (yaw and roll then share a turn)
local STALE_BLOCKS = 3                -- a record whose root is farther than this from the creature was not drawn lately
local BLOCK = 65536

M.offsets = { record = RECORD, matrices = REC_MATRICES, slot_root = SLOT_ROOT, slot_weapon = SLOT_WEAPON_B,
  slot_hand = SLOT_HAND_B, hands = REC_HANDS, weapon = REC_WEAPON_B, model_size = MODEL_SIZE, look_pitch = C_LOOK_PITCH,
  hand_scale = C_HAND_SCALE, weapon_scale = C_WEAPON_SCALE, origin = GC_ORIGIN }

local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function f32(a) return ffi.cast("float*", a)[0] end

-- ---- pure ------------------------------------------------------------------------------------------------------------------

local function axis(m, c) return { m[c * 4 + 1], m[c * 4 + 2], m[c * 4 + 3] } end
local function len(v) return math.sqrt(v[1] * v[1] + v[2] * v[2] + v[3] * v[3]) end
local function scaled(v, k) return { v[1] * k, v[2] * k, v[3] * k } end
local function plus(a, b) return { a[1] + b[1], a[2] + b[2], a[3] + b[3] } end
local function dot(a, b) return a[1] * b[1] + a[2] * b[2] + a[3] * b[3] end

-- The image of the model point q (voxels) under the matrix m (16 numbers, row-vector form).
local function point(m, q)
  return { m[13] + q[1] * m[1] + q[2] * m[5] + q[3] * m[9],
           m[14] + q[1] * m[2] + q[2] * m[6] + q[3] * m[10],
           m[15] + q[1] * m[3] + q[2] * m[7] + q[3] * m[11] }
end
M.point = point

-- The bow in the hand, from hand B's matrix `hand` (16 numbers), the hand model's size {x, y, z}, the creature's hand and weapon
-- scales, its look pitch (degrees) and the bow model's size {x, y, z}. Returns { centre = {x, y, z} (the middle of the bow model's
-- box, in the hand matrix's space), axes = { x, y, z } (the bow model's axes there, unit vectors), voxel = the bow's voxel in
-- blocks, size = the bow model's size }, or nil for a matrix or scale that cannot be a hand's.
function M.bow_frame(hand, hand_size, hand_scale, weapon_scale, look_pitch, size)
  local x, y, z = axis(hand, 0), axis(hand, 1), axis(hand, 2)
  local lx, ly, lz = len(x), len(y), len(z)
  if not (lx > 0 and ly > 0 and lz > 0 and hand_scale > 0 and weapon_scale > 0) then return nil end
  local e0, e1, e2 = scaled(x, -1 / lx), scaled(y, 1 / ly), scaled(z, 1 / lz)    -- the hand's own frame, the mirror undone
  local pivot = point(hand, { hand_size[1] / 2, hand_size[2] / 2, hand_size[3] / 2 })
  local a = math.rad(look_pitch * PITCH_SHARE)
  local c, s = math.cos(a), math.sin(a)
  local b1 = plus(scaled(e1, c), scaled(e2, s))
  local b2 = plus(scaled(e1, -s), scaled(e2, c))
  local voxel = ly / hand_scale * weapon_scale
  -- the box's middle is (sx / 2, sy / 2, sz / 2); with the grip's shift it lies (0, 1.5 - sy / 2, 0) voxels from the hand
  local centre = plus(pivot, scaled(b1, (GRIP_TOP - size[2] / 2) * voxel))
  return { centre = centre, axes = { e0, b1, b2 }, voxel = voxel, size = { size[1], size[2], size[3] } }
end

-- The frame of a model drawn with the matrix `m` (16 numbers) and of size {x, y, z}: as bow_frame returns it.
function M.drawn_frame(m, size)
  local x, y, z = axis(m, 0), axis(m, 1), axis(m, 2)
  local lx, ly, lz = len(x), len(y), len(z)
  if not (lx > 0 and ly > 0 and lz > 0) then return nil end
  return { centre = point(m, { size[1] / 2, size[2] / 2, size[3] / 2 }), axes = { scaled(x, 1 / lx), scaled(y, 1 / ly),
    scaled(z, 1 / lz) }, voxel = ly, size = { size[1], size[2], size[3] } }
end

-- The ghost's yaw, pitch and roll (degrees, docs/emtweaks.md: Rz(yaw) * Rx(pitch) * Ry(roll)) that turn a model's axes onto
-- `axes` (three unit vectors, a rotation).
function M.angles(axes)
  local b0, b1, b2 = axes[1], axes[2], axes[3]
  local up = b1[3]
  if up > 1 then up = 1 elseif up < -1 then up = -1 end
  local flat = math.sqrt(b1[1] * b1[1] + b1[2] * b1[2])
  if flat < GIMBAL then
    return math.deg(math.atan2(b0[2], b0[1])), math.deg(math.asin(up)), 0
  end
  return math.deg(math.atan2(-b1[1], b1[2])), math.deg(math.asin(up)), math.deg(math.atan2(-b0[3], b2[3]))
end

-- How far two frames are apart: the distance of their middles (blocks) and the largest angle between their axes (degrees).
function M.difference(a, b)
  local d = len({ a.centre[1] - b.centre[1], a.centre[2] - b.centre[2], a.centre[3] - b.centre[3] })
  local worst = 0
  for i = 1, 3 do
    local c = dot(a.axes[i], b.axes[i])
    if c > 1 then c = 1 elseif c < -1 then c = -1 end
    local deg = math.deg(math.acos(c))
    if deg > worst then worst = deg end
  end
  return d, worst
end

-- The size {x, y, z} of a model from the bytes of its .cub file (docs/assets.md: three little-endian uint32 first), or nil.
function M.cub_size(bytes)
  if type(bytes) ~= "string" or #bytes < 12 then return nil end
  local out = {}
  for i = 0, 2 do
    local b1, b2, b3, b4 = bytes:byte(i * 4 + 1, i * 4 + 4)
    out[i + 1] = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
  end
  if out[1] < 1 or out[2] < 1 or out[3] < 1 then return nil end
  return out
end

-- ---- the game ------------------------------------------------------------------------------------------------------------

local function matrix(rec, slot)
  local p = ffi.cast("float*", rec + REC_MATRICES + slot * MATRIX_BYTES)
  local m = {}
  for i = 0, 15 do m[i + 1] = p[i] end
  return m
end

local function model_size(model)
  return { i32(model + MODEL_SIZE), i32(model + MODEL_SIZE + 4), i32(model + MODEL_SIZE + 8) }
end

-- The render origin (x, y in world units), or nil.
local function origin()
  local cell = kyubu.symbol and kyubu.symbol("cube::game_controller")
  local gc = cell and u32(cell) or 0
  if gc == 0 then return nil end
  local o = ffi.cast("int64_t*", gc + GC_ORIGIN)
  return tonumber(o[0]), tonumber(o[1])
end

-- The draw record of `creature`, or nil when it does not name the creature (never drawn yet).
local function record(creature)
  local rec = creature + RECORD
  if u32(rec) ~= creature then return nil end
  return rec
end

-- Where the game would draw a bow of size `size` in the right hand of `creature`, from its last draw, in world blocks (the
-- frame of bow_frame). `at` is the creature's position {x, y, z} in blocks: a record whose root is far from it is old (the
-- creature was not drawn lately) and gives nil, as does a record that cannot be read.
function M.read(creature, size, at)
  local rec = record(creature)
  if not rec then return nil end
  local hands = u32(rec + REC_HANDS)
  local ox, oy = origin()
  if hands == 0 or not ox then return nil end
  local f = M.bow_frame(matrix(rec, SLOT_HAND_B), model_size(hands), f32(creature + C_HAND_SCALE),
    f32(creature + C_WEAPON_SCALE), f32(creature + C_LOOK_PITCH), size)
  if not f then return nil end
  local root = matrix(rec, SLOT_ROOT)
  local rx, ry, rz = root[13] - ox / BLOCK, root[14] - oy / BLOCK, root[15]
  if math.abs(rx - at.x) > STALE_BLOCKS or math.abs(ry - at.y) > STALE_BLOCKS or math.abs(rz - at.z) > STALE_BLOCKS then
    return nil
  end
  f.centre = { f.centre[1] - ox / BLOCK, f.centre[2] - oy / BLOCK, f.centre[3] }
  return f
end

-- The check of this file against the game: in one draw record, the bow the game drew in hand B (slot 7, its model's own size)
-- against the place bow_frame gives from the hand. Returns the distance of the middles (blocks) and the worst angle (degrees), or
-- nil when no weapon was drawn there.
function M.check(creature)
  local rec = record(creature)
  if not rec then return nil end
  local hands, weapon = u32(rec + REC_HANDS), u32(rec + REC_WEAPON_B)
  if hands == 0 or weapon == 0 then return nil end
  local size = model_size(weapon)
  local drawn = M.drawn_frame(matrix(rec, SLOT_WEAPON_B), size)
  local want = M.bow_frame(matrix(rec, SLOT_HAND_B), model_size(hands), f32(creature + C_HAND_SCALE),
    f32(creature + C_WEAPON_SCALE), f32(creature + C_LOOK_PITCH), size)
  if not drawn or not want then return nil end
  return M.difference(want, drawn)
end

return M
end

