-- ---- the hit: the list push and the damage site ----------------------------------------------------------------------------
-- hitCreature builds a cube::Hit on its stack, copies it into the step output's hit list (the damage numbers the game shows are
-- read from that copy) and then calls applyHit with the same Hit, which subtracts the damage at hitDamageSite. A cut made only at
-- the damage site changes the hp and leaves the number showing the old damage (30 shown, 4 taken).
-- The copy is made in two ways: the normal path (a monster's or a player's melee, a projectile) inserts inline, at
-- cube::World::hitListSite, with the Hit at ESP+0xC4; the special paths (hit types 3 and 5) call step_output_push_hit. The
-- hook on the push alone never runs for a monster's hit.
-- So the callbacks run at whichever of the two the hit reaches, where the copy and the Hit applyHit gets are still one object,
-- and the damage site skips a Hit already handled. A hit that reaches neither (a hit received from a server) is handled at
-- the damage site. Without the list site the number of a normal hit is not cut: the hp is right and the number is not.

local hit_listeners = {}
local hit_installed = false
local push_installed = false
local list_installed = false
local LIST_HIT = 0xC4                           -- hitListSite: the Hit is at ESP+0xC4
local handled = nil                             -- { addr =, attacker =, victim =, damage = } of the last Hit the push passed on

-- Runs the callbacks on the Hit at `hit` (an address): the damage is replaced by what they return. Returns attacker, victim and
-- the damage after.
local function run_hit_listeners(hit)
  local attacker, victim = i64(hit + H_ATTACKER), i64(hit + H_VICTIM)
  local damage = ffi.cast("float*", hit + H_DAMAGE)
  local was = damage[0]
  local now = was
  for _, fn in ipairs(hit_listeners) do
    local ok, out = pcall(fn, attacker, victim, now, hit)
    if ok and type(out) == "number" then now = out
    elseif not ok then warn_once("hit:" .. tostring(out), "a hit callback failed: " .. tostring(out)) end
  end
  if now ~= was then damage[0] = now end
  return attacker, victim, damage[0]
end

local function on_hit_site(ctx)
  local hit = ctx.ebx
  if hit == 0 then return end
  local h = handled
  if h and h.addr == hit then
    handled = nil
    if h.attacker == i64(hit + H_ATTACKER) and h.victim == i64(hit + H_VICTIM) and h.damage == ffi.cast("float*", hit + H_DAMAGE)[0] then
      return                                    -- the push cut it already: the number and the hp agree
    end
  end
  run_hit_listeners(hit)
end
M._on_hit_site = on_hit_site                    -- for the unit test

-- The mid hook of cube::World::hitListSite: the normal path's Hit is on the stack at ESP+0xC4.
local function on_list_site(ctx)
  local addr = ctx.esp + LIST_HIT
  local ok, attacker, victim, damage = pcall(run_hit_listeners, addr)
  if ok then handled = { addr = addr, attacker = attacker, victim = victim, damage = damage }
  else warn_once("list:" .. tostring(attacker), "the hit list site failed: " .. tostring(attacker)) end
end
M._on_list_site = on_list_site                  -- for the unit test

-- The hook of step_output_push_hit(this, const cube::Hit*), thiscall.
local function on_push(next, this, hit)
  if hit ~= nil then
    local addr = tonumber(ffi.cast("uint32_t", hit))
    if addr ~= 0 then
      local ok, attacker, victim, damage = pcall(run_hit_listeners, addr)
      if ok then handled = { addr = addr, attacker = attacker, victim = victim, damage = damage }
      else warn_once("push:" .. tostring(attacker), "the hit push failed: " .. tostring(attacker)) end
    end
  end
  return next(this, hit)
end
M._on_push = on_push                            -- for the unit test

function M.on_hit(fn)
  hit_listeners[#hit_listeners + 1] = fn
  if not hit_installed then hit_installed = install("cube::World::hitDamageSite", on_hit_site) end
  if not list_installed then list_installed = install("cube::World::hitListSite", on_list_site) end
  if not push_installed and kyubu.symbol("step_output_push_hit") then
    local id, err = kyubu.hook("step_output_push_hit", "void(__thiscall*)(void*, void*)", on_push)
    if id then push_installed = true
    else warn_once("push-install", "step_output_push_hit: the hook failed (" .. tostring(err) .. "): damage numbers show the uncut damage") end
  elseif not push_installed and not (kyubu.host and kyubu.host().host == "server") then   -- Server.exe shows no number
    warn_once("push-symbol", "step_output_push_hit has no symbol: the damage numbers show the uncut damage")
  end
  return hit_installed
end

-- ---- the draw site -----------------------------------------------------------------------------------------------------

local tint_listeners = {}
local tint_installed = false

local function on_tint_site(ctx)
  local creature = ctx.esi
  if creature == 0 then return end
  local colour = nil
  for _, fn in ipairs(tint_listeners) do
    local ok, f = pcall(fn, creature)
    if ok and type(f) == "table" then
      colour = colour or ffi.cast("float*", u32(ctx.esp + STACK_COLOUR))
      colour[0], colour[1], colour[2] = colour[0] * f[1], colour[1] * f[2], colour[2] * f[3]
    elseif not ok then
      warn_once("tint:" .. tostring(f), "a tint callback failed: " .. tostring(f))
    end
  end
end
M._on_tint_site = on_tint_site                  -- for the unit test

function M.on_tint(fn)
  tint_listeners[#tint_listeners + 1] = fn
  if not tint_installed then tint_installed = install("creature_draw_site", on_tint_site) end
  return tint_installed
end

-- ---- the stun's mark ---------------------------------------------------------------------------------------------------

local mark_wants = {}                           -- { want = fn, slot_of = fn } in the order given
local mark_installed = false
local get_model = nil                           -- ModelLoader::get(this, slot) -> Model*, thiscall
local faked, saved_stun = 0, 0                  -- the creature whose stun time is 1 for this draw, and what it held

local function wanted(creature)
  for _, w in ipairs(mark_wants) do
    local ok, yes = pcall(w.want, creature)
    if ok and yes then return w end
  end
  return nil
end

local function on_gate_site(ctx)
  local c = ctx.esi
  if c == 0 or i32(c + C_STUN) > STUN_FLOOR then return end     -- the game draws its own mark here: the model site swaps it
  if not wanted(c) then return end
  faked, saved_stun = c, i32(c + C_STUN)
  ffi.cast("int32_t*", c + C_STUN)[0] = 1
end
M._on_gate_site = on_gate_site                  -- for the unit test

local function on_model_site(ctx)
  local c = ctx.esi
  if faked ~= 0 then
    ffi.cast("int32_t*", faked + C_STUN)[0] = saved_stun
    faked = 0
  end
  if c == 0 or not get_model then return end
  local w = wanted(c)
  if not w then return end
  local models = u32(ctx.esp + STACK_MODELS)
  if models == 0 then return end
  local ok, slot = pcall(w.slot_of)
  if not ok or type(slot) ~= "number" then return end
  local m = get_model(ffi.cast("void*", models), nil, slot)
  if m ~= nil then ctx.eax = tonumber(ffi.cast("uint32_t", m)) end
end
M._on_model_site = on_model_site                -- for the unit test

-- `want(creature_addr)` -> true to draw the bolts there; `slot_of()` -> the model's table slot (read at each draw: the slot
-- is known only after the game is ready).
function M.on_mark(want, slot_of)
  mark_wants[#mark_wants + 1] = { want = want, slot_of = slot_of }
  if mark_installed then return true end
  local a = kyubu.symbol("ModelLoader::get")
  if not a then
    warn_once("get", "ModelLoader::get has no symbol: no mark")
    return false
  end
  get_model = ffi.cast("void*(__fastcall*)(void*, void*, int32_t)", a)
  -- the model site first: the gate fakes a stun that only the model site puts back, so the gate goes in only when that is there
  local model = install("stun_mark_model_site", on_model_site)
  local gate = model and install("stun_mark_gate_site", on_gate_site)
  mark_installed = gate and true or false
  return mark_installed
end

-- ---- the walk while an ability runs ----------------------------------------------------------------------------------------
-- The game clears the full-speed bit at walkLockSite only on its mode rule's path; the bit still holds what the frame's input
-- gave it (the slow-walk key and stamina decide it). When a callback wants the full walk, that value is put back at
-- walkLockEndSite, where every path joins, so the World steps after it keep the doubled cap. The penalty site is reached only
-- while lock-on is set and the walk points away from the facing: XMM0 holds the cap's factor (0.5 to 1), made 1 there.

-- After an ability ends the game may lock the walk of the mode that follows for its first 200 ms (its duration is 0); a callback
-- that keeps the walk through that lock asks for this long, with room to spare.
M.WALK_LOCK_AFTER_MS = 400

local walk_wants = {}
local walk_installed = false
local walk_player = 0                           -- the player seen at the last lock site
local walk_keep = 0                             -- the player whose full-speed bit goes back at the end site

local function walk_wanted(p)
  for _, fn in ipairs(walk_wants) do
    local ok, yes = pcall(fn, p)
    if ok and yes then return true end
    if not ok then warn_once("walk:" .. tostring(yes), "a walk callback failed: " .. tostring(yes)) end
  end
  return false
end

local function flags(c) return ffi.cast("uint16_t*", c + C_FLAGS) end

local function on_walk_lock(ctx)
  local p = u32(ctx.edi + GC_PLAYER)
  walk_player = p
  if p ~= 0 and bit.band(flags(p)[0], F_FULL_SPEED) ~= 0 and walk_wanted(p) then walk_keep = p end
end
M._on_walk_lock = on_walk_lock                  -- for the unit test

local function on_walk_end(ctx)
  if walk_keep == 0 then return end
  if walk_keep == u32(ctx.edi + GC_PLAYER) then flags(walk_keep)[0] = bit.bor(flags(walk_keep)[0], F_FULL_SPEED) end
  walk_keep = 0
end
M._on_walk_end = on_walk_end                    -- for the unit test

local function on_walk_penalty(ctx)
  local c = u32(ctx.ebp - EBP_CREATURE)
  if c == 0 or c ~= walk_player or not walk_wanted(c) then return end
  ctx.xmm[0].f32[0] = 1.0
end
M._on_walk_penalty = on_walk_penalty            -- for the unit test

function M.on_walk(fn)
  walk_wants[#walk_wants + 1] = fn
  if walk_installed then return true end
  -- the end site first: the lock site only notes a player that the end site gives the bit back to
  local done = install("cube::GameController::walkLockEndSite", on_walk_end)
  local lock = done and install("cube::GameController::walkLockSite", on_walk_lock)
  walk_installed = lock and true or false
  if walk_installed then install("cube::World::lockOnWalkPenaltySite", on_walk_penalty) end
  return walk_installed
end

-- ---- the AI's first-target scan ------------------------------------------------------------------------------------------
-- A monster with no target scans every creature for the nearest enemy in range (cube::CombatBehavior::update). At
-- cube::CombatBehavior::targetScanSite EBX is the candidate and XMM2 its squared distance; a huge XMM2 puts it out of range, so
-- the scan never picks it (probe ninja-scan-skip: every pass with the player skipped, five slimes with no target for 15 s).
-- It does not make a monster drop a target it has: that is its threat map (combat.set_threat).

local FAR = 1.0e30
local scan_wants = {}
local scan_installed = false

local function on_scan_site(ctx)
  local c = ctx.ebx
  if c == 0 then return end
  for _, fn in ipairs(scan_wants) do
    local ok, yes = pcall(fn, c)
    if ok and yes then
      ctx.xmm[2].f32[0] = FAR
      return
    end
    if not ok then warn_once("scan:" .. tostring(yes), "a scan callback failed: " .. tostring(yes)) end
  end
end
M._on_scan_site = on_scan_site                  -- for the unit test

-- sites.on_scan(fn): fn(creature) -> true keeps that creature out of every monster's first-target scan.
function M.on_scan(fn)
  scan_wants[#scan_wants + 1] = fn
  if scan_installed then return true end
  scan_installed = install("cube::CombatBehavior::targetScanSite", on_scan_site)
  return scan_installed
end

return M
end

-- @module skills_unleashed.lib.snare (lib/snare.lua)
package.preload["skills_unleashed.lib.snare"] = function(...)
-- skills_unleashed.lib.snare: the snare, shared by every ability that roots a creature (the Scout's trap, the Water Mage's chains:
-- a creature one of them holds cannot be snared by the other). A snared creature
--   * is rooted: the loader's KY_CREATURE_ROOTED flag (creature_set_flags). At the World's
--     AI tick its behaviour is not run and its mode is held at none; at its move step it does not walk and is not knocked back,
--     but may fall. The behaviour stays in place, so the creature goes on as before once the flag is cleared;
--   * keeps one pose: its draw record (Creature+0x1498, EDI at draw_creature_join_site) is saved at its first draw and its words
--     +0x10 to +0x4EC are written back at every later draw (client only);
--   * cannot be stunned: its stun timer is held under the mark's floor (-3000), and a hit on it has its stun, slow and push taken
--     out (cube::Hit +0x18, +0x1C, +0x38), so it still takes the damage (the hit hook is the client's);
--   * is drawn whitish: its draw colour times `tint` (overbright, as the probe's white_level 3; client only).
-- After a snare it cannot be snared again for `immune_ms`. The clock is the World steps' own (ms), so a pause stops it.
-- Who roots: the side that owns the creature. On Server.exe lib/snare runs in the server VM and sets the flag itself. In
-- single-player it runs in the client VM, which owns only the local player (KY_E_SIDE for a monster), so it sends
-- `skills_unleashed:snare { id, rooted }` to its own server VM over the loopback channel; serve() there sets the flag, and takes
-- the message only from KY_CONN_LOCAL_CLIENT, so a joined player (connections 2 to 11) cannot root anything with it. The flag then
-- takes hold at the server side's next update. A joined client never snares: its monsters are the server's.
-- What the clients see: on Server.exe each start and end is sent to every joined client on `skills_unleashed:world`
-- (lib/world_events) as `snare_on { id, ms, by }` and `snare_off { id, why }`. A joined client keeps those as `shown` snares: they
-- get the one pose and the tint, and the listeners of on_shown and on_end, but nothing is written to the creature (it is the
-- server's). The stun and the hold are the server's, and reach the client with the creature's own updates.
local ffi = require("ffi")
local combat = require("skills_unleashed.lib.combat")
local sites = require("skills_unleashed.lib.sites")
local world_events = require("skills_unleashed.lib.world_events")

local M = {}

M.CHANNEL = "skills_unleashed:snare"

local C_ID, C_STUN = 0x08, 0x12C
local REC_FIRST, REC_LAST = 0x10, 0x4F0         -- the draw record's words that are frozen
local H_STUN, H_SLOW, H_DIR = 0x18, 0x1C, 0x38  -- cube::Hit: stun ms, slow ms, the push direction (3 floats)
local STUN_FLOOR, STUN_HELD = -3000, -4000      -- the mark is drawn above the floor; a snared creature is held below it

local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function i64(a) return tonumber(ffi.cast("int64_t*", a)[0]) end
local function put_f32(a, v) ffi.cast("float*", a)[0] = v end
local function put_i32(a, v) ffi.cast("int32_t*", a)[0] = v end

local cfg = { immune_ms = 10000, tint = { 3, 3, 3 } }
local snared = {}                               -- id -> { ends (clock ms, nil: until released), released, snap }
local immune = {}                               -- id -> the clock until which it cannot be snared
local shown = {}                                -- a joined client: id -> { by, snap }, the server's snares as its events said
local clock = 0
local world_of = nil                            -- the World the tables belong to: a new World starts empty
local installed = false
local served = false
local ended_listeners = {}
local shown_listeners = {}

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: snare: " .. text) end
end

M._state = function() return snared, immune, clock, shown end   -- for the unit test

-- The numbers: { immune_ms, tint = { r, g, b } }. Any field left out keeps its value.
function M.configure(t)
  if t.immune_ms then cfg.immune_ms = t.immune_ms end
  if t.tint then cfg.tint = t.tint end
end

function M.is_snared(id) return snared[id] ~= nil or shown[id] ~= nil end
-- A creature the loader flags unstoppable (creature_set_flags) is never snared.
function M.unstoppable_id(id)
  local g = kyubu and kyubu.game
  if not (g and g.creature_find) then return false end
  local h = g.creature_find(id)
  local info = h and h:get()
  return info ~= nil and info.flags ~= nil and info.flags.unstoppable == true
end
function M.is_immune(id) return (immune[id] or 0) > clock end
function M.can_snare(id) return not M.is_snared(id) and not M.is_immune(id) and not M.unstoppable_id(id) end
function M.now() return clock end

-- fn(id, why) after a snare ended ("time", "released", "gone", "dead"), this side's own or one the server told of.
function M.on_end(fn) ended_listeners[#ended_listeners + 1] = fn end
-- A joined client: fn(id, by, ms) when the server tells of a snare it started (`by` the ability that set it, `ms` nil: until
-- released).
function M.on_shown(fn) shown_listeners[#shown_listeners + 1] = fn end

-- Server.exe tells its joined clients. Elsewhere nothing is sent: in single-player the client VM snares and draws itself.
local function tell(kind, fields)
  if kyubu.side ~= "server" then return end
  local ok, err = world_events.broadcast(kind, fields)
  if not ok and err ~= "no channels" then
    kyubu.info(("skills_unleashed: snare: %s of creature %d not sent: %s"):format(kind, fields.id, tostring(err)))
  end
end

-- Sets or clears the rooted flag of creature `id` on this side, keeping its other flags. Returns true, or false and why.
local function set_rooted(id, on)
  local g = kyubu.game
  if not (g and g.creature_find and g.creature_set_flags) then return false, "this Kyubu has no creature_set_flags" end
  local h, why = g.creature_find(id)
  if not h then return false, why end
  local info = h:get()
  local f = (info and info.flags) or {}
  local ok, err = g.creature_set_flags(h, { unstoppable = f.unstoppable == true, invulnerable = f.invulnerable == true,
    rooted = on == true })
  if not ok then return false, err end
  return true
end
M._set_rooted = set_rooted                      -- for the unit test

-- Roots or frees creature `id` through the side that owns it (see the top of this file).
local function root(id, on)
  if kyubu.side == "server" then return set_rooted(id, on) end
  local ch = kyubu.channel
  if not ch then return false, "this Kyubu has no channels" end
  local ok, err = ch.send(M.CHANNEL, ch.SERVER, { id = id, rooted = on == true })
  if not ok then return false, err end
  return true
end

-- The server VM's end of the loopback: roots or frees the creature the local client names.
local function on_message(conn, t)
  if conn ~= kyubu.channel.LOCAL_CLIENT then
    warn_once("conn:" .. tostring(conn), "a snare message from connection " .. tostring(conn) ..
      " was refused (only the local client)")
    return
  end
  if type(t) ~= "table" or type(t.id) ~= "number" then return end
  local ok, why = set_rooted(t.id, t.rooted == true)
  if not ok then warn_once("set:" .. tostring(why), "creature " .. t.id .. " could not be rooted: " .. tostring(why)) end
end
M._on_message = on_message                      -- for the unit test

-- Registers the loopback channel's handler on the server side (call it once from the server script, at lifecycle.register).
function M.serve()
  if served then return true end
  local ch = kyubu.channel
  if not ch then return false end
  local ok, err = ch.register(M.CHANNEL, function(conn, t)
    local fine, e = pcall(on_message, conn, t)
    if not fine then warn_once("msg:" .. tostring(e), "message error: " .. tostring(e)) end
  end)
  if not ok then
    warn_once("register", "the channel could not be registered (" .. tostring(err) .. "): single-player snares do not root")
    return false
  end
  served = true
  return true
end

-- Snares creature `c` (an address) for `ms` (nil: until release); `by` names the ability for the clients ("water_mage", "scout").
-- Returns true, or false and why.
function M.start(c, ms, by)
  local id = combat.id(c)
  if snared[id] then return false, "snared" end
  if M.is_immune(id) then return false, "immune" end
  if M.unstoppable_id(id) then return false, "unstoppable" end
  local ok, why = root(id, true)
  if not ok then
    warn_once("root:" .. tostring(why), "creature " .. id .. " is not snared: " .. tostring(why))
    return false, "no root"
  end
  local x, y, z = combat.position(c)
  snared[id] = { ends = ms and (clock + ms) or nil, from = { x, y, z }, at = clock }
  M.hold(c, snared[id])
  tell("snare_on", { id = id, ms = ms, by = by })
  return true
end

-- Ends the snare of `id` at the next World step.
function M.release(id)
  local s = snared[id]
  if s then s.released = true end
end

-- One step of holding: called for each snared creature every World step. The flag holds it in place and keeps its AI from acting;
-- the stun is held here, under the mark's floor.
function M.hold(c, _)
  if i32(c + C_STUN) > STUN_FLOOR then put_i32(c + C_STUN, STUN_HELD) end
end

local function finish(id, why, c)
  local s = snared[id]
  if s and s.from and c then                    -- how far it went while held (a fall is allowed; a walk or a knock is not)
    local x, y, z = combat.position(c)
    local dx, dy = x - s.from[1], y - s.from[2]
    kyubu.info(("skills_unleashed: snare: creature %d freed (%s) after %d ms: moved %.2f blocks across, %.2f up"):format(id, why,
      clock - s.at, math.sqrt(dx * dx + dy * dy), z - s.from[3]))
  end
  snared[id] = nil
  immune[id] = clock + cfg.immune_ms
  if why ~= "gone" then root(id, false) end   -- a gone creature's flags went with it
  tell("snare_off", { id = id, why = why })
  for _, fn in ipairs(ended_listeners) do pcall(fn, id, why) end
end

-- ---- a joined client: the server's snares ----------------------------------------------------------------------------------

local function shown_end(id, why)
  if not shown[id] then return end
  shown[id] = nil
  for _, fn in ipairs(ended_listeners) do pcall(fn, id, why) end
end

local function on_shown_on(t)
  if type(t.id) ~= "number" then return end
  if shown[t.id] then shown_end(t.id, "again") end   -- a second start before the end: the old one is over
  shown[t.id] = { by = t.by }
  for _, fn in ipairs(shown_listeners) do pcall(fn, t.id, t.by, t.ms) end
end
local function on_shown_off(t)
  if type(t.id) ~= "number" or not shown[t.id] then return end
  kyubu.info(("skills_unleashed: snare: the server freed creature %d (%s)"):format(t.id, tostring(t.why)))
  shown_end(t.id, t.why or "released")
end
M._on_shown_on, M._on_shown_off = on_shown_on, on_shown_off   -- for the unit test

-- The World step (combat.every): the clock runs, every snared creature is held, a snare whose time is up ends.
function M.step(step)
  if step.world ~= world_of then
    snared, immune, clock, world_of = {}, {}, 0, step.world   -- shown snares go at world_exit: their events may come first
  end
  clock = clock + step.dt
  if next(shown) ~= nil then                     -- a shown creature that left this client's World is dropped
    local here = {}
    combat.each_creature(step.world, function(c) here[combat.id(c)] = true end)
    for id in pairs(shown) do
      if not here[id] then shown_end(id, "gone") end
    end
  end
  if next(snared) == nil then return end
  local found = {}
  combat.each_creature(step.world, function(c)
    local id = combat.id(c)
    if snared[id] then found[id] = c end
  end)
  for id, s in pairs(snared) do
    local c = found[id]
    if not c then finish(id, "gone")
    elseif not combat.is_alive(c) then finish(id, "dead", c)
    elseif s.released then finish(id, "released", c)
    elseif s.ends and clock >= s.ends then finish(id, "time", c)
    else M.hold(c, s) end
  end
end

-- ---- the game's draw and hit code ----------------------------------------------------------------------------------------

-- draw_creature_join_site: EDI is the draw record of the creature drawn; its first word the creature.
local function on_join(ctx)
  local rec = ctx.edi
  if rec == 0 then return end
  local c = u32(rec)
  if c == 0 then return end
  local id = i64(c + C_ID)
  local s = snared[id] or shown[id]
  if not s then return end
  local w = ffi.cast("uint32_t*", rec)
  local a, b = REC_FIRST / 4, REC_LAST / 4 - 1
  if not s.snap then
    s.snap = {}
    for i = a, b do s.snap[i] = w[i] end
  else
    for i = a, b do w[i] = s.snap[i] end
  end
end
M._on_join = on_join                            -- for the unit test

-- stun_mark_gate_site: ESI the creature. A stun given since the last step would show the mark: put it under the floor now.
local function on_gate(ctx)
  local c = ctx.esi
  if c ~= 0 and snared[i64(c + C_ID)] then put_i32(c + C_STUN, STUN_HELD) end
end
M._on_gate = on_gate

local function on_hit(_, victim, _, hit)
  if not hit or not snared[victim] then return nil end
  put_i32(hit + H_STUN, 0); put_i32(hit + H_SLOW, 0)
  put_f32(hit + H_DIR, 0); put_f32(hit + H_DIR + 4, 0); put_f32(hit + H_DIR + 8, 0)
  return nil
end
M._on_hit = on_hit

local function hook(name, fn)
  local id, err = kyubu.hook_mid(name, function(ctx)
    local ok, e = pcall(fn, ctx)
    if not ok and kyubu.warn then kyubu.warn("skills_unleashed: snare: " .. name .. ": " .. tostring(e)) end
  end)
  if not id and kyubu.warn then kyubu.warn("skills_unleashed: snare: " .. name .. ": the hook failed (" .. tostring(err) .. ")") end
  return id ~= nil
end

-- Installs the step and the hooks once (call it at lifecycle.game_ready or the first cast's setup, after combat.install_hook).
function M.install()
  if installed then return end
  installed = true
  combat.every(M.step)
  hook("draw_creature_join_site", on_join)
  hook("stun_mark_gate_site", on_gate)
  sites.on_hit(on_hit)
  if kyubu.side ~= "server" then
    world_events.on("snare_on", on_shown_on)
    world_events.on("snare_off", on_shown_off)
    kyubu.on("lifecycle.world_exit", function() shown = {} end)
  end
  sites.on_tint(function(c)
    local id = combat.id(c)
    if snared[id] or shown[id] then return cfg.tint end
    return nil
  end)
end

return M
end

-- @module skills_unleashed.lib.sound (lib/sound.lua)
package.preload["skills_unleashed.lib.sound"] = function(...)
-- skills_unleashed.lib.sound: the mod's own sounds, the .wav files of assets/sounds/ (Kyubu serves them from data2.db by file name).
-- They are played with the two calls the game's play_sound makes on its sound engine (GameController+0x800714, a
-- cube::XAudio2Engine): vtable slot 7 loads a sound by name and gives a handle (the engine keeps a loaded sound by name, so a second
-- load is a lookup), slot 6 plays a handle with a volume, a pan and a pitch. Facts: mapping/atlas/audio.md, "A sound of the mod's
-- own"; probe sound-file (dev mod sound_file_proto).
--
-- The name goes in a std::string of the game's library: 16 bytes of text in place, then the size and the capacity 15. A longer
-- name would need the string's heap form, which was not tried, so names are 15 characters at most.
-- A sound has no place: it is heard at the volume asked for (times the game's sound option), as the player's own. Other players
-- do not hear it.
local ffi = require("ffi")

local M = {}

local GC_ENGINE, GC_VOLUME = 0x800714, 0x184   -- the engine; the sound option (0 to 100)
local VT_PLAY, VT_LOAD = 0x18, 0x1C
local STR_SIZE, STR_LEN, STR_CAP = 24, 16, 20
local SHORT_CAP = 15
local PERCENT = 0.01
M.MAX_NAME = SHORT_CAP

local function u32(a) return ffi.cast("uint32_t*", a)[0] end

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: sound: " .. text) end
end

local str = ffi.new("uint8_t[?]", STR_SIZE)

-- Plays the mod's sound `name` (a file of assets/sounds/) at `volume` (1 is the game's own level; default 1) and `pitch` (default 1).
-- Returns true when the engine played it, else false and the reason (logged once per name).
function M.play(name, volume, pitch)
  if type(name) ~= "string" or #name == 0 or #name > SHORT_CAP then
    warn_once("name:" .. tostring(name), tostring(name) .. ": a name of 1 to " .. SHORT_CAP .. " characters is needed")
    return false, "name"
  end
  local at = kyubu.symbol("cube::game_controller")
  local gc = at and u32(at) or 0
  if gc == 0 then return false, "no game" end
  local engine = u32(gc + GC_ENGINE)
  if engine == 0 then return false, "no engine" end
  local vt = u32(engine)
  local load_sound = ffi.cast("uint32_t(__thiscall*)(void*, void*)", u32(vt + VT_LOAD))
  local play_handle = ffi.cast("void(__thiscall*)(void*, uint32_t, float, float, float, uint32_t)", u32(vt + VT_PLAY))
  ffi.fill(str, STR_SIZE)
  ffi.copy(str, name)
  ffi.cast("uint32_t*", str + STR_LEN)[0] = #name
  ffi.cast("uint32_t*", str + STR_CAP)[0] = SHORT_CAP
  local handle = load_sound(ffi.cast("void*", engine), str)
  if handle == 0 then
    warn_once("load:" .. name, name .. ": the engine did not load it (no such file in assets/sounds, or not a 16-bit PCM wav)")
    return false, "not loaded"
  end
  local option = ffi.cast("int32_t*", gc + GC_VOLUME)[0]
  play_handle(ffi.cast("void*", engine), handle, option * (volume or 1) * PERCENT, 0, pitch or 1, 0)
  return true
end

return M
end

-- @module skills_unleashed.lib.terrain (lib/terrain.lua)
package.preload["skills_unleashed.lib.terrain"] = function(...)
-- skills_unleashed.lib.terrain: the world's blocks, for the rules that need the ground or a wall (the Scout's trap, the Fire Mage's
-- circle, the Ninja's bomb, the Sniper's arrow).
-- kyubu.game.world_block (docs/game-api.md) reads the block that holds a point on either host,
-- Cube.exe and Server.exe, with the same walk, so a rule gets the same input on both. It answers "unknown" for a place in no loaded
-- zone. A loader without it (older than API 1.4, or `terrain` unavailable) gives no blocks: the rules then keep the height they were
-- given and nothing stops a flight.
-- A block is solid unless its kind (type & 0x1F) is 0 (air) or 2 (water), as the game's own test. An unknown place counts as solid,
-- as the game's own lookup does: find_ground then keeps the spot's height and a flight stops there.
-- Call it on the game thread, inside a World step (combat.every): world_block holds the World's lock.
-- The `world` argument of the calls below is not used (world_block reads the calling side's World); it stays for the callers.
local bit = require("bit")

local M = {}

local KIND_MASK = 0x1F
local AIR, WATER = 0, 2

local game_block = nil   -- kyubu.game.world_block, when the loader has it
local looked = false

local function resolve()
  if looked then return game_block end
  looked = true
  local game = kyubu.game
  if game and game.world_block and (not game.available or game.available("terrain")) then
    game_block = game.world_block
  elseif kyubu.warn then
    kyubu.warn("skills_unleashed: terrain: this Kyubu has no world_block (API 1.4): things lie at the height they were dropped from")
  end
  return game_block
end

-- True when the blocks can be asked.
function M.available() return resolve() ~= nil end

-- Where the blocks come from: "world_block" or nil.
function M.source()
  return resolve() and "world_block" or nil
end

-- The type byte of the block that holds the point x, y, z (blocks), or nil when the place is in no loaded zone or the blocks cannot
-- be asked.
function M.block_type(_, x, y, z)
  if not resolve() then return nil end
  return (game_block(x, y, z))
end

-- Whether the block that holds the point x, y, z (blocks) is solid. An unknown place is solid; false when the blocks cannot be
-- asked at all.
function M.solid(world, x, y, z)
  if not resolve() then return false end
  local t = M.block_type(world, x, y, z)
  if t == nil then return true end
  local kind = bit.band(t, KIND_MASK)
  return kind ~= AIR and kind ~= WATER
end

-- A solid(x, y, z) function for the pure logic; nil when the blocks cannot be asked.
function M.solid_fn(world)
  if not resolve() then return nil end
  return function(x, y, z) return M.solid(world, x, y, z) end
end

return M
end

-- @module skills_unleashed.lib.tooltip (lib/tooltip.lua)
package.preload["skills_unleashed.lib.tooltip"] = function(...)
-- skills_unleashed.lib.tooltip: the text of the fourth skill button (skill 9) in the skill tree: a name, a description and the
-- level lines ("upgrades": this level, then the next one).
--
-- How the game builds a skill tooltip (mapping/atlas/ui.md, "Skill tooltip"):
--   * it asks the World for the skill's name, a std::map<int, wstring> at World+0x800114 that the World constructor fills for
--     skills 0 to 5 and 10; skill 9 has no entry, so without the mod its name and every text are empty;
--   * with the name it reads two texts of the dictionary, "description:<name>" and "details:<name>" (the loader merges the
--     mod's assets/text/dict_en.xml into the game's), and fills their @placeholders from a map that skill_description_fill
--     builds for the skill's rank, once for the current rank and once for the next.
-- So the mod does two things: puts a name at index 9 of the map (every World step, cheaply: the entry is checked, not
-- rewritten), and wraps skill_description_fill so that after the game's own fill the ability's placeholders are added.
--
-- One entry per specialization that has an ability: tooltip.register{ class =, specialization =, name =, values = fn(rank) }.
-- The name is the dictionary suffix ("AbilityUppercut" reads description:AbilityUppercut); values(rank) returns a table
-- placeholder name (no @) to text. Use names of the game's own placeholders (the dictionary text writes the same ones): the
-- engine left a name of the mod's own blank although the map held it, and the map is made again for
-- every tooltip, so overwriting a vanilla name for this skill touches nothing else. Nothing here runs without the game: init() reports what could not be resolved.
local ffi = require("ffi")

local M = {}

local SKILL_INDEX = 9                       -- cube::GameController.skill_buttons[9]: ABILITY4
local W_SKILL_NAMES = 0x800114              -- cube::World: skill index -> dictionary name, std::map<int, std::wstring>
local C_CLASS, C_SPEC = 0x140, 0x141        -- cube::Creature (already shifted by +0x10: class_type, specialization)
local MAP_OF_VALUES = 8                     -- skill_description_fill's third argument holds its wstring map at +8
local WSTRING_SIZE = 0x10                   -- a MSVC 2012 std::wstring: 16 byte buffer, size at +0x10, capacity at +0x14
local GC_SKILLS_OPEN = 0x8008F1             -- cube::GameController.skills_open (byte)
local GC_SKILL_WIDGET = 0x80090C            -- cube::GameController.skill_widget (cube::SkillWidget*)
local WIDGET_SPEC = 0x18C                   -- the SkillWidget's working specialization (int32): the one the open panel shows

-- The game's numbering of the classes and of each class's two specializations (cube::Specialization: 0 and 1 for each).
local CLASS_ID = { warrior = 1, ranger = 2, mage = 3, rogue = 4 }
local SPEC_ID = {
  warrior = { berserker = 0, guardian = 1 },
  ranger = { sniper = 0, scout = 1 },
  mage = { fire_mage = 0, water_mage = 1 },
  rogue = { assassin = 0, ninja = 1 },
}

local function u8(a) return ffi.cast("uint8_t*", a)[0] end
local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: tooltip: " .. text) end
end

local int_index_fn = nil                    -- wstring_map_index(map*, const int*) -> wstring*, thiscall, ret 4
local assign_fn = nil                       -- wstring_assign_cstr(wstring*, const wchar_t*), thiscall, ret 4
local from_cstr_fn = nil                    -- wstring_from_cstr(wstring*, const wchar_t*) -> wstring*, thiscall, ret 4
local ws_index_fn = nil                     -- wstring_map_index_ws(map*, const wstring*) -> wstring*, thiscall, ret 4
local hook_id = nil

local entries = {}                          -- class id -> specialization id -> entry
local current = nil                         -- the entry of the local player's class and the panel's specialization, set every step
local skill_key = ffi.new("int32_t[1]", SKILL_INDEX)
local keys = {}                             -- "@name" -> a persistent wstring (made once, never freed: a handful of strings)
local scratch = {}                          -- wide strings kept alive until the call that reads them returns

local function wide(text)
  local n = #text
  local buf = ffi.new("uint16_t[?]", n + 1)
  for i = 1, n do buf[i - 1] = text:byte(i) end
  buf[n] = 0
  scratch[#scratch + 1] = buf
  return buf
end

local function wstring_size(w) return u32(w + WSTRING_SIZE) end

-- Registers the tooltip of a specialization's ability. Returns true, or false and the reason.
function M.register(def)
  local class, spec = CLASS_ID[def.class], SPEC_ID[def.class] and SPEC_ID[def.class][def.specialization]
  if not class or not spec then return false, "unknown class or specialization: " .. tostring(def.class) .. "/" .. tostring(def.specialization) end
  if type(def.name) ~= "string" or def.name == "" then return false, "no name" end
  if type(def.values) ~= "function" then return false, "no values function" end
  entries[class] = entries[class] or {}
  entries[class][spec] = { name = def.name, values = def.values }
  return true
end

-- The specialization the skill panel shows for the local player: while the panel is open, the SkillWidget's working copy (a click
-- on a specialization button sets it before Learn, as the game's own buttons 6 to 8 follow it); otherwise the player's own.
local function shown_spec(player)
  local own = u8(player + C_SPEC)
  local at = kyubu and kyubu.symbol and kyubu.symbol("cube::game_controller")
  local gc = at and u32(at) or 0
  if gc == 0 or u8(gc + GC_SKILLS_OPEN) == 0 then return own end
  local widget = u32(gc + GC_SKILL_WIDGET)
  if widget == 0 then return own end
  local s = i32(widget + WIDGET_SPEC)
  if s == 0 or s == 1 then return s end
  return own
end

-- The entry for a creature (the local player), or nil.
local function entry_of(player)
  local by_class = entries[u8(player + C_CLASS)]
  return by_class and by_class[shown_spec(player)] or nil
end

-- Called in every World step of the local player: remembers which entry applies and keeps the name at index 9 of the World's
-- skill-name map. The game's constructor builds that map empty for 9, and a new World (a new session) starts without it.
function M.step(world, player)
  current = entry_of(player)
  if not current or not int_index_fn or not assign_fn then return end
  local value = int_index_fn(ffi.cast("void*", world + W_SKILL_NAMES), nil, skill_key)
  if value == nil then return end
  local at = tonumber(ffi.cast("uintptr_t", value))
  if wstring_size(at) ~= #current.name then assign_fn(value, nil, wide(current.name)) end
  scratch = {}
end

local function set_value(map, name, text)
  local key = keys[name]
  if not key then
    key = ffi.new("uint8_t[?]", WSTRING_SIZE + 8)
    from_cstr_fn(key, nil, wide(name))
    keys[name] = key
  end
  local value = ws_index_fn(ffi.cast("void*", map + MAP_OF_VALUES), nil, key)
  if value == nil then return false end
  assign_fn(value, nil, wide(text))
  return true
end

-- Adds the placeholders of `rank` to the fill's map when the skill is the fourth button's. `map` is the address of the
-- placeholder struct (an int argument holds a pointer above 2 GB as a negative number).
local function apply(skill, rank, map)
  if map < 0 then map = map + 4294967296 end
  local entry = current
  if skill == SKILL_INDEX and entry and map ~= 0 then
    local ok, values = pcall(entry.values, rank)
    if not ok or type(values) ~= "table" then
      warn_once("values:" .. tostring(values), "values failed: " .. tostring(values))
    else
      for name, text in pairs(values) do set_value(map, "@" .. name, tostring(text)) end
    end
    scratch = {}
  end
end

local function on_fill(next, this, skill, rank, map)
  next(this, skill, rank, map)
  apply(skill, rank, map)
end

-- Resolves the game's functions and wraps skill_description_fill. Returns true when the tooltip texts can work.
function M.init()
  if hook_id then return true end
  local function sym(name) return kyubu.symbol(name) end
  local a, b, c, d = sym("wstring_map_index"), sym("wstring_assign_cstr"), sym("wstring_from_cstr"), sym("wstring_map_index_ws")
  if not (a and b and c and d) then
    warn_once("symbols", "a string function has no symbol (wstring_map_index, wstring_assign_cstr, wstring_from_cstr, "
      .. "wstring_map_index_ws): no skill text")
    return false
  end
  int_index_fn = ffi.cast("void*(__fastcall*)(void*, void*, const int32_t*)", a)
  assign_fn = ffi.cast("void(__fastcall*)(void*, void*, const uint16_t*)", b)
  from_cstr_fn = ffi.cast("void*(__fastcall*)(void*, void*, const uint16_t*)", c)
  ws_index_fn = ffi.cast("void*(__fastcall*)(void*, void*, const void*)", d)
  local id, err = kyubu.hook("skill_description_fill", "void(__thiscall*)(void*, int, int, int)", on_fill)
  if not id then
    warn_once("hook", "the skill_description_fill hook failed: " .. tostring(err))
    return false
  end
  hook_id = id
  return true
end

-- Keeps the name at index 9 up to date in every World step, through lib/combat's one hook, once however many abilities ask.
-- Returns true when it is in place.
local stepping = false
function M.keep_names(combat)
  if stepping then return true end
  if not combat.install_hook() then return false end
  combat.every(function(step) M.step(step.world, step.player) end)
  stepping = true
  return true
end

M.SKILL_INDEX = SKILL_INDEX
M._on_fill = on_fill                         -- for the unit test

return M
end

-- @module skills_unleashed.lib.trap_rig (lib/trap_rig.lua)
package.preload["skills_unleashed.lib.trap_rig"] = function(...)
-- skills_unleashed.lib.trap_rig: where each part of the Scout's trap is drawn, from a pose of its clips. Pure: no kyubu, no ffi.
-- The geometry is models-src/scout-trap.rig.toml's (the Animator's preview); keep the two the same:
--   trap   T(body.pos) T(0, 0, 1) Rz(body.rot.z) Ry(body.rot.y) Rx(body.rot.x) T(0, 0, -1)   (a tilt round the hinge line)
--   plate  trap * T(0, 0, 1)
--   front  trap * T(0, 0.5, 1) Rx(90) Rx(-hand_l.rot.x) T(0, 3, 0)            (hand_l: 0 shut, 90 open)
--   back   trap * Rz(180) T(0, 0.5, 1) Rx(90) Rx(-hand_r.rot.x) T(0, 3, 0)
-- in voxels, x right, y forward, z up, the origin the middle of the trap on the ground; the first step is the outermost. A model is
-- centred on its node, as in the Animator and as an emtweaks:ghost is placed (pos is the middle of the model's box).
-- In the world the trap's frame is turned by its yaw (the ghost's yaw: 0 faces north, 90 west) and scaled by the voxel size.
local M = {}

M.PARTS = { "plate", "jaw_front", "jaw_back" }

-- 3x4 affine matrices: { m = { {r1}, {r2}, {r3} }, p = { x, y, z } }
local function ident() return { m = { { 1, 0, 0 }, { 0, 1, 0 }, { 0, 0, 1 } }, p = { 0, 0, 0 } } end

local function mul(a, b)
  local m, p = {}, {}
  for r = 1, 3 do
    m[r] = {}
    for c = 1, 3 do m[r][c] = a.m[r][1] * b.m[1][c] + a.m[r][2] * b.m[2][c] + a.m[r][3] * b.m[3][c] end
    p[r] = a.m[r][1] * b.p[1] + a.m[r][2] * b.p[2] + a.m[r][3] * b.p[3] + a.p[r]
  end
  return { m = m, p = p }
end

local function T(x, y, z) local a = ident(); a.p = { x, y, z }; return a end
local function Rx(d)
  local c, s = math.cos(math.rad(d)), math.sin(math.rad(d))
  return { m = { { 1, 0, 0 }, { 0, c, -s }, { 0, s, c } }, p = { 0, 0, 0 } }
end
local function Ry(d)
  local c, s = math.cos(math.rad(d)), math.sin(math.rad(d))
  return { m = { { c, 0, s }, { 0, 1, 0 }, { -s, 0, c } }, p = { 0, 0, 0 } }
end
local function Rz(d)
  local c, s = math.cos(math.rad(d)), math.sin(math.rad(d))
  return { m = { { c, -s, 0 }, { s, c, 0 }, { 0, 0, 1 } }, p = { 0, 0, 0 } }
end

local function chain(list)
  local a = ident()
  for _, b in ipairs(list) do a = mul(a, b) end
  return a
end

local ZERO = { pos = { 0, 0, 0 }, rot = { 0, 0, 0 } }
local function part(pose, name) return (pose and pose[name]) or ZERO end

-- The yaw, pitch and roll (degrees) of a rotation m = Rz(yaw) Rx(pitch) Ry(roll), as emtweaks:ghost composes them.
function M.euler(m)
  local sp = m[3][2]
  if sp > 1 then sp = 1 elseif sp < -1 then sp = -1 end
  local pitch = math.deg(math.asin(sp))
  local yaw, roll
  if math.abs(sp) < 0.99999 then
    yaw = math.deg(math.atan2(-m[1][2], m[2][2]))
    roll = math.deg(math.atan2(-m[3][1], m[3][3]))
  else                                   -- straight up or down: yaw and roll turn about the same axis; put it all in yaw
    yaw = math.deg(math.atan2(m[2][1], m[1][1]))
    roll = 0
  end
  return yaw, pitch, roll
end

-- The local matrices of the three parts (voxels, the trap's own frame) for a pose of the trap's clips.
function M.local_frames(pose)
  local body, front, back = part(pose, "body"), part(pose, "hand_l"), part(pose, "hand_r")
  local trap = chain({ T(body.pos[1], body.pos[2], body.pos[3]), T(0, 0, 1), Rz(body.rot[3]), Ry(body.rot[2]), Rx(body.rot[1]),
    T(0, 0, -1) })
  return {
    plate = mul(trap, T(0, 0, 1)),
    jaw_front = mul(trap, chain({ T(0, 0.5, 1), Rx(90), Rx(-front.rot[1]), T(0, 3, 0) })),
    jaw_back = mul(trap, chain({ Rz(180), T(0, 0.5, 1), Rx(90), Rx(-back.rot[1]), T(0, 3, 0) })),
  }
end

-- Where the parts are drawn: { [part] = { x, y, z (blocks: the middle of the model), yaw, pitch, roll (degrees) } } for the trap
-- lying at `origin` {x, y, z} (blocks, the middle of the trap on the ground), turned by `yaw` degrees, one voxel `voxel` blocks.
function M.place(pose, origin, yaw, voxel)
  local world = Rz(yaw)
  local out = {}
  for name, f in pairs(M.local_frames(pose)) do
    local w = mul(world, f)
    local y, p, r = M.euler(w.m)
    out[name] = { x = origin.x + w.p[1] * voxel, y = origin.y + w.p[2] * voxel, z = origin.z + w.p[3] * voxel, yaw = y, pitch = p, roll = r }
  end
  return out
end

return M
end

-- @module skills_unleashed.lib.world_events (lib/world_events.lua)
package.preload["skills_unleashed.lib.world_events"] = function(...)
-- skills_unleashed.lib.world_events: what the server tells the joined clients about the things it owns in the world.
-- One channel, `skills_unleashed:world`, carries every such event as a table:
--   { kind = "snare_on" | "snare_off" | ..., ... the event's own fields }
-- The server sends to every joined client (KY_CONN_ALL_CLIENTS): caster and bystanders draw from the same events. A client takes
-- events only from the server's connection (KY_CONN_SERVER).
--
-- Only Server.exe sends (combat.is_server: a World with no local player that is not joined). The server VM of a single-player game
-- sends nothing: there the client VM runs the abilities and draws its own snares.
local M = {}

M.CHANNEL = "skills_unleashed:world"

local handlers = {}               -- client side: kind -> { fn(event), ... }
local served = false
local warned = {}

local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  kyubu.warn("skills_unleashed: world events: " .. text)
end

-- ---- the server --------------------------------------------------------------------------------------------------------------

-- Sends event `kind` with `fields` (copied) to every joined client. Returns true, or false and why. A server with no joined player
-- yet refuses with KY_E_NOT_FOUND or KY_E_NO_REMOTE: that is not logged, there is no one to tell.
function M.broadcast(kind, fields)
  local ch = kyubu.channel
  if not ch then
    warn_once("none", "this Kyubu has no channels: the clients are not told")
    return false, "no channels"
  end
  local msg = { kind = kind }
  for k, v in pairs(fields or {}) do msg[k] = v end
  local ok, err = ch.send(M.CHANNEL, ch.ALL_CLIENTS, msg)
  if not ok then return false, err end
  return true
end

-- ---- the client --------------------------------------------------------------------------------------------------------------

local function on_message(conn, t)
  if conn ~= kyubu.channel.SERVER then
    warn_once("conn:" .. tostring(conn), "an event from connection " .. tostring(conn) .. " was refused (not the server)")
    return
  end
  if type(t) ~= "table" or type(t.kind) ~= "string" then return end
  for _, fn in ipairs(handlers[t.kind] or {}) do
    local fine, e = pcall(fn, t)
    if not fine then warn_once("fn:" .. t.kind .. tostring(e), t.kind .. ": " .. tostring(e)) end
  end
end
M._on_message = on_message        -- for the unit test

-- Client side: `fn(event)` gets every event of `kind`, after the handlers added before it. Registers the channel once.
function M.on(kind, fn)
  local list = handlers[kind] or {}
  list[#list + 1] = fn
  handlers[kind] = list
  if served then return true end
  local ch = kyubu.channel
  if not ch then
    warn_once("none", "this Kyubu has no channels: no world event is read")
    return false
  end
  local ok, err = ch.register(M.CHANNEL, on_message)
  if not ok then
    warn_once("register", "the channel could not be registered: " .. tostring(err))
    return false
  end
  served = true
  return true
end

return M
end

-- @module skills_unleashed.main (main.lua)
package.preload["skills_unleashed.main"] = function(...)
-- SkillsUnleashed: one fourth ability (slot 4, key 4) for every specialization. This module only registers them: each ability is a
-- module of src/abilities/<specialization>.lua that returns { define = function() ... end } and is listed in
-- logic/roster.lua. A specialization that is not listed keeps the placeholder, so the mod is valid with any number of abilities.
--
-- "Shockwave" in this mod always means EMTweaks' shockwave (emtweaks:shockwave), drawn through skills_unleashed.lib.fx.
--
-- scripts/client.lua is GENERATED from src/ by tools/bundle_lua.py: edit the sources, never that file.
local PREFIX = "skills_unleashed"

-- The specializations that have an ability (logic/roster.lua: the server defines the same list, so
-- that both number the abilities alike).
local ENABLED = require(PREFIX .. ".logic.roster").ENABLED

local function register()
  if not kyubu.ability then
    kyubu.warn(PREFIX .. ": this Kyubu has no ability API (it needs 1.1 with abilities): no ability is defined")
    return
  end
  local defined = 0
  for _, spec in ipairs(ENABLED) do
    local ok, mod = pcall(require, PREFIX .. ".abilities." .. spec)
    if not ok then
      kyubu.warn(PREFIX .. ": " .. spec .. ": cannot load the ability: " .. tostring(mod))
    else
      local dok, err = pcall(mod.define)
      if dok then defined = defined + 1 else kyubu.warn(PREFIX .. ": " .. spec .. ": define failed: " .. tostring(err)) end
    end
  end
  kyubu.info(("%s: %d of %d ability(ies) defined"):format(PREFIX, defined, #ENABLED))
end

-- Before the game loads its assets: an ability that makes assets from code (a module with a `preinit`) does it here.
local function preinit()
  for _, spec in ipairs(ENABLED) do
    local ok, mod = pcall(require, PREFIX .. ".abilities." .. spec)
    if ok and type(mod.preinit) == "function" then
      local pok, err = pcall(mod.preinit)
      if not pok then kyubu.warn(PREFIX .. ": " .. spec .. ": preinit failed: " .. tostring(err)) end
    end
  end
end

kyubu.on("lifecycle.preinit", preinit)
kyubu.on("lifecycle.register", register)

return { ENABLED = ENABLED }
end

require("skills_unleashed.main")
